COLLDATA("asabahur","ur",[[6328,"§۷۷۰۰ ۔ مالک بن ہدم(1)(2)\nابن ابی بن حارث بن بداء تجیبی، ابوعمرو، ابن یونس نے ان کا ذکر کیا ہے، فرماتے ہیں: فتح مصر میں شریک ہوئے، انہوں نے سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت کیا۔ یعقوب بن سفیان نے اپنی تاریخ میں حدیث نقل کی ہے، جس کا تقاضا یہ ہے کہ وہ صحابی ہیں۔ انہوں نے بطریق ربیعہ بن لقیط، بحوالہ مالک بن ہدم نقل کیا ہے، فرماتے ہیں: ہم نے جہاد کیا، ہم پر سیدنا عمرو بن العاص امیر تھے، ہم میں سیدنا عمر بن خطاب اور ابو عبیدہ بن جراح تھے، ہمیں بہت سخت بھوک لگی، میں کھانے کی کوئی چیز تلاش کرنے لگا، میں نے لوگوں کو دیکھا کہ وہ اپنے اونٹ ذبح کرنا چاہتے تھے۔\nمیں کہتا ہوں: نبی کریم صلی اللہ علیہ وسلم کے زمانے میں غزوہ ذات السلاسل کا واقعہ ہے۔ انہیں لشکر کا امیر بنایا، انہوں نے آپ سے کمک طلب کی، آپ نے ابو عبیدہ کو ان کی مدد کے لیے بھیجا۔","",{"fn":"(1) اسد الغابہ (۴۶۵۰) تجرید (۲/۴۹)\n(2) دلائل النبوۃ (۶/۳۰۸) جامع المسانید والسنن (۱۱/۶۳) اسد الغابہ (۴/۴۱)"}],[6329,"§۷۷۰۱ ۔ مالک بن ولیدہ(1)\nعبدان بن محمد مروزی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے اور بطریق خالد بن حمید، بحوالہ مالک بن خیر نقل کیا ہے کہ مالک بن ولید نے فرمایا:\n\"نبی کریم صلی اللہ علیہ وسلم نے مجھے وصیت کی کہ میں گورنری حاصل کرنے کے لیے ایک قدم بھی نہ اٹھاؤں اور نہ کسی ذمی سے سوئی یا اس سے چھوٹی چیز حاصل کروں اور نہ برے بادشاہ کے خلاف بغاوت کروں\"۔\n(2) یہ بروایت انس بن ابی انیسہ، بحوالہ خالد مذکور مروی ہے، اس میں نامعلوم راوی ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۵۱) تجرید (۲/۴۹)\n(2) جامع المسانید والسنن (۱۱/۶۴) اسد الغابہ (۴/۴۱)"}],[6330,"§۷۷۰۲ ۔ مالک بن وہب خزاعی\nابو نعیم نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابو موسیٰ اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے، بزار کے ہاں ان کی مسند میں بطریق عبدالعزیز بن ابی بکر بن مالک بن وہب خزاعی، عن ابیہ عن جدة ان کی حدیث ہے کہ نبی کریم صلی اللہ علیہ وسلم نے احزاب کے دن سلیط اور سفیان بن عوف کو جاسوس بنا کر بھیجا، انہیں شہید کر دیا گیا، نبی کریم صلی اللہ علیہ وسلم نے انہیں ایک قبر میں دفن کیا، وہ دونوں شہید اور قریبی رشتہ دار ہیں۔ بزار کا قول ہے:(1) ہمیں مالک بن وہب کی اس حدیث کے علاوہ کوئی روایت معلوم نہیں۔\nمیں کہتا ہوں: اس کی سند میں نامعلوم راوی ہیں۔","",{"fn":"(1) مجمع الزوائد (۶/۱۳۵) کشف الاسناد (۱۸۰۵) جامع المسانید والسنن (۱۱/۶۵)"}],[6331,"§۷۷۰۳ ۔ مالک بن یخامر سکسکی(1)\nالہانی حمصی، ابن عساکر کا قول ہے: ایک قول ہے کہ صحابی ہیں، ابو نعیم نے کہا: صحابہ میں ان کا ذکر ہے، جو ثابت نہیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مرسل روایت کی ہے، حدیث یہ ہے: \"قرض، دین میں عیب ہے\"۔\nابوزرعہ دمشقی نے اس طبقہ علیا میں ان کا ذکر کیا ہے جو صحابہ سے ملا ہوا ہے۔ سیدنا معاذ بن جبل رضی اللہ عنہ کے ساتھی ہیں اور ان سے روایت کیا، عبد الرحمن بن عوف، عبد اللہ بن سعدی، عمرو بن عوف اور عبد اللہ بن عمرو وغیرہ سے روایت کی۔\nان سے معاویہ نے ان کی موجودگی میں روایت کیا، ان کے حوالے سے، بحوالہ معاذ صحیح بخاری رحمہ اللہ میں ان کی حدیث ہے ان سے اسی طرح ان کے دونوں بیٹوں عبداللہ، عبد الرحمن، عمیر بن ہانی، جبیر بن نصر، شریح بن عبید محمول اور دوسرے لوگوں نے روایت کیا۔\nابن سعد(2) کا قول ہے: ثقہ ہیں، عجلی کا قول ہے: شامی، تابعی اور ثقہ ہیں، ابن حبان(3) نے ثقات تابعین میں ان کا ذکر کیا ہے۔ ہیثم کا قول ہے: ۷۲ ھ میں وفات پائی، ابن ابی عاصم کا قول ہے: ۷۰ ھ میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۴۶۵۴) تجرید (۲/۵۰)\n(2) طبقات کبریٰ (۷/۱۵۲)\n(3) ثقات تابعین (۵/۳۸۳)"}],[6332,"§۷۷۰۴ ۔ مالک بن یسار سکونی(1)\nپھر عوفی، ابوداؤد، بغوی، ابن ابی عاصم، ابن سکن اور معمری نے یوم واللیلۃ میں ان کی حدیث نقل کی ہے۔ ابن قانع نے بطریق ضمضم، بحوالہ ابو بحریہ، ان کے حوالے سے نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم اللہ سے دعا کرو تو ہتھیلیوں کے اندرونی حصے سے دعا کرو، ہاتھ الٹے کر کے دعا نہ کرو\"۔(2)\nسلیمان بن عبدالحمید، شیخ ابوداؤد نے کہا: مالک بن یسار کو ہمارے نزدیک شرف صحابیت حاصل ہے۔ سنن کے نسخے میں ہے: ہمارے نزدیک مالک صحابی نہیں، اس میں ما نافیہ زیادہ ہے۔ بغوی رحمہ اللہ کا قول ہے: مجھے اس اسناد سے، اس کے علاوہ کوئی اور حدیث معلوم نہیں۔ مجھے معلوم نہیں کہ صحابی ہیں یا نہیں۔ ابن سکن کے ہاں صرف مالک بن سنان سکسکی ہیں۔ پہلا قول اولیٰ ہے، عبدالصمد سعید کی طبقات حمصیین میں مالک بن سنان سکونی پھر عوفی ہے جو سکون کا قبیلہ ہے، ان سے مالک بن عامر نے روایت کیا، میرا خیال ہے کہ وہ اس کے علاوہ ہیں۔","",{"fn":"(1) اسد الغابہ (۴۶۵۵) استیعاب (۲۳۳۲) تجرید (۲/۵۰)\n(2) ابوداؤد (۱۴۸۶) الأحاد والمثانی (۴/۴۱۰)"}],[6333,"§۷۷۰۵ ۔ مالک بن ابی امیہ ازدی\nجنادہ کے والد ہیں، کنیتوں میں اس کا ذکر آئے گا۔"],[6334,"§۷۷۰۶ ۔ مالک، ابو سمح\nکنیتوں میں ان کا ذکر آئے گا۔"],[6335,"§۷۷۰۷ ۔ مالک بن اسلمی\nماعز کے والد ہیں۔"],[6336,"§۷۷۰۸ ۔ مالک قشیری\nبغوی نے بحوالہ مالک بن عمرو ان کا تنہا ذکر کیا ہے، اور بطریق سلمہ بن علقمہ، بحوالہ مالک قشیری نقل کیا ہے، فرماتے ہیں:\nرسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کا کوئی رشتہ دار اس سے وہ چیز مانگنے آتا ہے اور وہ اس کے دینے میں بخل کرتا ہے تو قیامت کے دن وہ مال گنجے سانپ کی شکل میں ظاہر ہوگا\"۔\nپھر فرمایا: مجھے معلوم نہیں کہ صحابی ہیں یا نہیں، اسے بحوالہ داؤد سلمہ کے علاوہ کسی نے روایت نہیں کیا وہ بصری ہیں۔ حدیث بیان کرنے کی صلاحیت رکھتے ہیں۔"],[6337,"§۷۷۰۹ ۔ مالک مری(1)\nابو غطفان کے والد ہیں، ابن مندہ کا قول ہے: بخاری(2) نے صحابہ میں ان کا ذکر کیا ہے۔ دوسرے راویوں کا قول ہے: ابو غطفان کے والد کا نام طریف ہے، ابو غطفان نے اپنے والد کے حوالے سے روایت کیا۔","",{"fn":"(1) اسد الغابہ (۴۶۴۰) تجرید (۲/۴۸)\n(2) تاریخ کبیر (۷/۳۰۴)"}],[6338,"§۷۷۱۰ ۔ مالک ہلالی(1)\nعبد اللہ کے والد ہیں۔ حارث بن ابی اسامہ نے اپنی مسند میں بطریق عمر بن عبدالرحمن بحوالہ عبد اللہ بن مالک ہلالی، عن ابیہ نقل کیا ہے۔ ایک شخص نے کہا: یا رسول اللہ! اصحاب اعراف کون ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ لوگ اپنے آباء کی اجازت کے بغیر جہاد کے لیے نکلے اور شہید ہو گئے، شہادت کی وجہ سے آگ میں داخل نہیں ہو سکے اور اپنے آباء کی نافرمانی کی وجہ سے جنت میں نہیں جاسکتے\"۔(2)\nواقدی کی مسند میں ضعیف روایت ہے، اسے ابن لہیعہ نے بحوالہ یحییٰ بن نہل نقل کیا ہے کہ بنو ہلال میں سے ایک شخص نے انہیں بتایا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اصحاب اعراف کے بارے میں پوچھا، پھر اسی مفہوم کی روایت ذکر کی۔","",{"fn":"(1) اسد الغابہ (۴۶۱۵) استیعاب (۲۳۳۳)\n(2) مجمع الزوائد (۷/۲۴) جامع المسانید والسنن (۱۱/۴۵) اسد الغابہ (۴/۲۷)"}],[6339,"§۷۷۱۱ ۔ مامر جنی\nابن درید نے ان جنات میں ان کا ذکر کیا ہے جو رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔"],[6340,"§۷۷۱۲ ۔ ماناہہ فارسی\nمحمد نامی لوگوں میں ان کا ذکر آئے گا۔"],[6341,"§۷۷۱۳ ۔ مبارک\nمولیٰ ثابت بن قیس بن شماس انصاری ہیں، ان کے ساتھی سعد کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[6342,"§۷۷۱۴ ۔ مبرح بن شہاب(1)\nابن حارث بن ربیعہ بن حیت بن شرحیل یافعی، ابن یونس نے تاریخ مصر میں ان کا ذکر کیا ہے۔ فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم کے پاس چار افراد میں آئے، پھر فتح مصر میں شریک ہوئے، اہل مصر میں معروف ہیں۔ ان کی کوئی روایت نہیں جو نہیں معلوم ہو۔ جیزہ میں ان کا قطعہ ارضی ہے، ان کے بھائی بھی فتح مصر میں شریک تھے، وہ صحابی نہیں، دونوں معروف ہیں۔","",{"fn":"(1) اسد الغابہ (۴۶۵۶) تجرید (۲/۵۰)"}],[6343,"§۷۷۱۵ ۔ مبرق شاعر\nبقول بعض: ان کا نام ربیعہ بن لیث ہے، ایک قول ہے: عبد اللہ بن حارث، اسماء میں ان کا ذکر گزر چکا ہے۔"],[6344,"§۷۷۱۶ ۔ مبشر بن ابیرق\nحدیث قتادہ بن نعمان میں ان کا ذکر گزر چکا ہے، رفاعہ بن زید کے سوانح میں ان کا ذکر ہے۔"],[6345,"§۷۷۱۷ ۔ مبشر بن براء\nابن معرور انصاری، ابن کلبی کا قول ہے: بیعت رضوان میں شریک ہوئے۔"],[6346,"§۷۷۱۸ ۔ مبشر بن عبدالمنذر(1)\nبن زنبر، ابن زید بن امیر انصاری، ابولبابہ کے بھائی ہیں، ابن اسحاق(2) وغیرہ نے بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے، اسی میں شہید ہوئے۔ اسی طرح ابن حبان کا قول ہے: وہ ابولبابہ کے بھائی ہیں، بقول بعض: ابولبابہ کا نام مبشر ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۵۹) استیعاب (۲۵۴۰) تجرید (۲/۵۰)\n(2) السیرۃ النبویۃ (۲/۲۵۰)"}],[6347,"§۷۷۱۹ ۔ متمم بن نویرہ تمیمی(1)\nان کے بھائی مالک کے سوانح میں ان کا نسب گزر چکا ہے۔ طبری(2) نے ان کا ذکر کیا ہے، فرماتے ہیں: وہ اور ان کے بھائی اسلام لائے، نبی کریم صلی اللہ علیہ وسلم نے مالک کو بنو تمیم کے صدقات وصول کرنے کے لیے بھیجا، وہ اور ان کے بھائی متمم اسلام لا چکے تھے۔\nمتمم اپنے بھائی کے بارے میں اچھے مرثیہ کہنے والے شاعر ہیں، انہی کا یہ مشہور شعر ہے:\n\"جب ہم دونوں جدا ہو گئے تو ایسا لگا کہ میں اور مالک ایک شب بھی اکٹھے نہ تھے، کیونکہ جدائی بہت طویل ہے\"۔\nاس سے پہلے یہ شعر ہے:\n\"ہم دونوں جزیمہ کے دو شراب کے ساتھیوں میں سے تھے، جو کافی سال اکٹھے رہے یہاں تک کہ لوگ کہنے لگے یہ تو کبھی جدا نہیں ہوں گے\"۔(3)\nسیدہ عائشہ رضی اللہ عنہا نے یہی اشعار اپنے بھائی عبدالرحمن بن ابی بکر کی قبر پر کھڑے ہو کر پڑھے تھے، کسی نے متمم سے کہا: تمہیں اپنے بھائی کا کتنا غم ہوا ہے؟ انہوں نے کہا: میری آنکھ کو کوئی بیماری لاحق ہوئی جس سے اس میں سے ایک قطرہ بھی نہیں بہا، جب میرا بھائی قتل ہوا تو رکنے نہ پائیں، مرزبانی لکھتے ہیں کہ متمم کی کنیت ابو نہشل، ایک قول ہے: ابورہم، بقول بعض: ابوابراہیم، کانے تھے، ان کا سلام اچھا تھا، ان کے زیادہ تر اشعار اپنے بھائی کے بارے میں مرثیوں پر مشتمل ہیں: \"اس کی ماں کے بیٹے کے بعد لوگوں میں ہر جوان ایسا ہے جیسے بیٹری میں سے ایک ہاتھ گر گیا ہو\"۔\nجب حضرت عمر بن عبد العزیز کے بھائی فوت ہوئے تو انہوں نے ان اشعار کو دہرایا تھا۔ مروی ہے کہ عمر نے حطیبہ سے کہا: کیا تم نے اس سے زیادہ رونے والا شخص دیکھا یا سنا ہے؟ انہوں نے کہا: نہیں، اللہ کی قسم! کوئی عربی ان جیسا کبھی نہیں رویا نہ کوئی روئے گا۔ اوروں کا کہنا ہے کہ زبیر اور طلحہ رضی اللہ عنہما جا رہے تھے کہ راستے میں انہیں متمم مل گئے، وہ دونوں رُک گئے تا کہ وہ گزر جائیں، تو وہ ٹھہر گئے۔ ان دونوں نے جلدی کی، ادھر سے انہوں نے بھی جلدی کی تو متمم نے کہا: تم دونوں کو کس چیز نے بوجھل کر کے روک دیا ہے، تو ان دونوں نے کہا: مجھے لوگوں کے دھوکا دینے کا خوف ہے۔ انہوں نے کہا: کیا اصحاب محمد صلی اللہ علیہ وسلم کو میں دھوکا دوں گا۔ مجھے گمراہی کا خدشہ ہے، مجھے پسند ہے کہ تم دونوں سے ہدایت حاصل کروں، مجھے وحشت کا خوف ہے، میں چاہتا ہوں کہ تم دونوں سے انس حاصل کروں، ان دونوں نے ان سے کہا: تم کون ہو؟ انہوں نے کہا: متمم بن نویرہ، ان دونوں نے کہا: ہم بلا وجہ اکتا گئے ہیں ہمیں کچھ اشعار سناؤ تو انہوں نے اپنا قصیدہ عینیہ ان کے سامنے پڑھنا شروع کیا:\n\"تیری زندگی کی قسم! میرا زمانہ مالک کے لیے نہ تو مردوں کے اوصاف بیان کرنے والا ہے اور نہ اس غم کی وجہ سے جو اسے پہنچا، بے صبری کرنے والا ہے، تا کہ وہ دردمند ہو، اس نے ان نشانیوں کی وجہ سے جو دیکھی ہیں، صبر کرنے سے انکار کر دیا ہے اور میں تیرے علاوہ جو تعلق دیکھتا ہوں وہ جلدی ختم ہونے والا ہے۔ میں ایسا جوان ہوں کہ جب تجھے، تیرے نام سے پکاروں، تو جواب نہ دے جبکہ تو تو جواب دینے اور سننے کا اہل تھا۔ اے مخاطب تو اسے تلوار کی دھار کی طرح حرکت کرتے دیکھے گا جو تر ہونے کے لیے ہل رہی ہو، جب وہ برے آدمی کے پاس کھانے کی کوئی چیز نہ پائے، اگر زمانہ ہم میں جدائی ڈال دے گا تو کوئی بات نہیں، میرا بھائی تعریف یافتہ اس وقت مجھ سے جدا ہو گیا، جب اس نے الوداع کہا، اللہ تعالیٰ اس زمین کو سیراب کرے جس میں مالک کی قبر بنی ہے۔ صبح کے وقت اٹھنے والے بھاری بادل، جو روئیدگی کا باعث ہوتے ہیں۔ اللہ کی قسم! میرے دل میں شہروں کی محبت نہیں لیکن الوداع کہنے والے محبوب کی محبت رچی بسی ہے\"۔","",{"fn":"(1) اسد الغابہ (۴۶۵۹) استیعاب (۲۵۴۱) تجرید (۲/۵۰)\n(2) اسد الغابہ (۴/۴۳) شعر والشعراء (۳۳۸)\n(3) اسد الغابہ (۴/۴۳) الشعر والشعراء (۳۳۸)"}],[6348,"§۷۷۲۰ ۔ مثعب (بے نسبت)(1)\nمطین نے وحدان میں صحابہ میں ان کا ذکر کیا ہے اور بطریق اشعث بن ابی شعثاء بحوالہ مثعب ذکر کیا ہے، فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جہاد کیا، ان میں سے بعض روزہ رکھتے تھے اور بعض نہیں رکھتے تھے، نہ رکھنے والے روزہ دار کو اور روزہ دار نہ رکھنے والے کو برا نہیں کہتے تھے۔\nاسی طرح طبرانی، ابونعیم(2)، علی بن سعید عسکری، یحییٰ بن یونس شیرازی، ابن سکن نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، فرماتے ہیں: مجھے ان کا نسب اور قبیلہ معلوم نہیں۔ ابو عمر(3) کا قول ہے: مثعب سلمی، بقول بعض: محاربی، ابوحاتم رازی(4) نے فرمایا: حمزہ بن عمرو اسلمی کا لقب مثعب تھا یا ان کا نام منعب تھا۔ نبی کریم صلی اللہ علیہ وسلم نے ان کا نام مثعب رکھا، احتمال ہے کہ یہ وہی ہوں، ابو عمر کا قول کہ وہ سلمی ہیں لفظی غلطی ہے یہ اسلمی ہے۔ اس کی تائید اس سے ہوتی ہے کہ یہ وہی ہیں: طبرانی کی پہلی حدیث ہے: وہ جہاد میں تھے۔ صحابہ میں سے جس کے پاس سواری تھی وہ باری باری اس پر دوسرے کو سوار کرتا تھا، رسول اللہ صلی اللہ علیہ وسلم اترتے پھر مجھ سے فرماتے: \"سوار ہو جاؤ\"۔ میں کہتا: میرے اندر قوت ہے، یہاں تک کہ آپ نے دو یا تین مرتبہ ایسا کیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم مثعب ہو\"۔(5) وہ میرے ناموں میں سے مجھے سب سے زیادہ پسند تھا، اسی طرح یہ زیادہ ابن سکن نے نقل کیا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۴۶۶۰) استیعاب (۲۵۴۲) تجرید (۲/۵۰)\n(2) المعجم الکبیر (۲۰/۸۴۷)\n(3) استیعاب (۴/۱۸)\n(4) الجرح والتعدیل (۸/۴۲۷)\n(5) مجمع الزوائد (۲۰/۱۵۹) جامع المسانید والسنن (۱۱/۷۶)"}],[6349,"§۷۷۲۱ ۔ مثلم بن حذافہ\nابن غانم بن عامر بن عبداللہ بن عبید بن عویج بن عدی بن کعب قرشی عدوی، مرزبانی نے معجم الشعراء(1) میں ان کا ذکر کیا ہے، فرماتے ہیں: حضرمی ہیں، اس کا تقاضا یہ ہے کہ صحابی ہیں، کیونکہ نبی کریم صلی اللہ علیہ وسلم کے زمانے کے آخر میں کوئی قریشی ایسا نہ تھا جو اسلام نہ لے آیا ہو، ان کا ابی بن خلف کے ساتھ قصہ ذکر کیا۔","",{"fn":"(1) المعجم المشتمل (۳۰۲)"}],[6350,"§۷۷۲۲ ۔ مثنی بن حارثہ(1)\nابن سلمہ بن ضمضم بن سعد بن مرہ بن ذہل بن شیبان ربعی شیبانی ہیں۔ ابن حبان کا قول ہے: صحابی ہیں۔ عمر بن شبہ کا قول ہے: مثنی بن حارثہ سواد پر حملہ کر رہے تھے، ابو بکر کو اطلاع ملی تو فرمایا: یہ کون شخص ہے جس کے جنگی کارناموں کی اطلاعیں ہم تک اس کے نسب کی جان پہچان کے بغیر پہنچ رہی ہیں۔ پھر ابو بکر رضی اللہ عنہ کے پاس آئے اور کہا: اے رسول اللہ صلی اللہ علیہ وسلم کے خلیفہ! مجھے میری قوم کے پاس بھیجیں، کیونکہ ان میں کچھ لوگ مسلمان ہیں، میں چاہتا ہوں کہ میں ان کے ذریعے اہل فارس سے جنگ کروں، اور اپنے علاقے کی جانب دشمنوں سے مقابلہ کروں، سیدنا ابو بکر رضی اللہ عنہ نے ایسے ہی کیا۔ پھر مثنی عراق آئے اور جہاد کیا، اہل سواد اور فارس پر حملہ کیا، انہوں نے اپنے بھائی کو سیدنا ابو بکر رضی اللہ عنہ کے پاس کمک طلب کرنے کے لیے بھیجا، انہوں نے سیدنا خالد بن ولید کو کمک دے کر بھیجا، جس سے فتوحات عراق کی ابتداء ہوئی۔ فتوحات میں مثنی کے بہت سے واقعات ہیں، انہیں سیف، طبری(2) اور بلاذری وغیرہ نے ذکر کیا ہے، ثابت نے دلائل میں ذکر کیا ہے کہ سیدنا عمر رضی اللہ عنہ انہیں اپنے نفس کو حکم دینے والا کہتے تھے۔ ابو عمر کا قول ہے: ۹ھ(3) میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور اسلام لائے۔ بقول بعض: ۱۰ھ میں۔ سیدنا ابوبکر رضی اللہ عنہ نے انہیں اپنی خلافت کی ابتداء میں عراق بھیجا، وہ رعب داب والے، بہادر، خوش بخت، اچھی رائے دینے والے تھے۔ انہوں نے فتوحات عراق میں ایسے کارنامے انجام دیئے جن تک کسی اور کی رسائی نہ ہوسکی۔ سراج نے ذکر کیا ہے کہ ۱۲ھ میں قادسیہ سے پہلے وفات پائی سیدنا سعد بن ابی وقاص نے ان کی زوجہ سلمیٰ بنت جعفر سے نکاح کیا۔\nابن مندہ نے ان کے سوانح میں ایسی روایت نقل کی ہے، جس سے ان کے اسلام جس سے وہم ہوتا ہے کہ وہ قدیم الاسلام ہیں۔ آخری قسم میں مقرون بن عمرو شیبانی کے سوانح میں اس کا بیان آئے گا۔ ان شاء اللہ تعالیٰ\nمرزبانی کا قول ہے: حضرمی ہے، یہ وہی ہیں جنہوں نے کہا:\n\"لوگوں نے اس وقت یقین سے سوال کیا جب تیرا نہیں نوچ رہے تھے۔ بھالوں کی دونوں مشرقی جانب اور خون سے سینے رنگین تھے، میں نے اڑتے غبار میں ان کی لاشوں کے ایسے دھڑ چھوڑے جو موٹے گدھوں کی گوشت خوری اور بھوکے جانوروں کے لیے سامان خوراک تھے\"۔","",{"fn":"(1) اسد الغابہ (۴۶۶۱) استیعاب (۲۵۴۳) تجرید (۲/۵۰)\n(2) تاریخ طبری (۳۶۷، ۲/۳۶۸)\n(3) استیعاب (۴/۱۹)"}],[6351,"§۷۷۲۳ ۔ مجاشع بن مسعود(1)\nابن ثعلبہ بن وہب بن عائذ بن ربیعہ بن یربوع بن سمال بن عوف بن امرئی القیس بن بھثہ بن سلیم بن منصور سلمی، بخاری(2) وغیرہ کا قول ہے: صحابی ہیں۔ صحیحین وغیرہ(3) کی روایت میں ہے، ان سے ابو عثمان نہدی، کلیب بن شہاب، ابو ساسان رقاشی، عبدالملک بن عمیرہ وغیرہ نے روایت کیا، نصر بن حجاج کے سوانح میں ان کا ذکر ہے۔\nابن کلبی رحمہ اللہ نے ذکر کیا ہے: انہوں نے سمیلہ بنت ابی حیوۃ بن ازبہر دوسیہ سے نکاح کیا، وہ جنگ جمل میں شہید ہو گئے تو ان سے سیدنا عبداللہ بن عباس رضی اللہ عنہما نے نکاح کر لیا، ابواعور سلمی کے سوانح میں بھی ان کا ذکر ہے۔\nدولابی کا قول ہے: انہوں نے بلا دھند میں سے کابل میں جہاد کیا، امیہد نے ان سے صلح کر لی، سیدنا مجاشع بت خانے میں داخل ہوئے، اور بت کی آنکھ سے موتی نکالنے لگے۔ انہوں نے کہا: میں اسے اس لیے نکال رہا ہوں تا کہ تم جان لو کہ وہ نہ نقصان پہنچا سکتے ہیں، نہ نفع دیتے ہیں۔ خلیفہ بن خیاط کا قول ہے: جنگ شروع ہونے سے پہلے جنگ جمل کے دن قتل ہوئے، مدائنی اور عمرو بن عتبہ نے بیان کیا ہے کہ وہ سیدنا زبیر رضی اللہ عنہ کے ساتھ جنگوں میں حکیم بن جبلہ کے ساتھ، عثمان بن حنیف کی وجہ سے قتل ہوئے، کیونکہ وہ بصرہ کے گورنر تھے۔ جب سیدنا زبیر رضی اللہ عنہ اور ان کے ساتھی آئے تو ان سے حکیم نے جنگ کی۔ وہ بصرہ پر غالب آگئے اور عثمان کو نکال دیا۔ مجاشع اور ان کے بھائی مجالد قتل ہو گئے، یہ سب سیدنا علی رضی اللہ عنہ کے آنے سے پہلے کا واقعہ ہے۔\nمدائنی نے بھی اپنی سند سے ذکر کیا ہے کہ عمرو بن معدیکرب نے ایک ضمانت لی، مجاشع ان کے پاس اس کے بارے میں مدد لینے آئے۔ انہوں نے کہا: اگر تم چاہو تو میں تمہیں یہ اپنے مال سے ادا کر دوں، اگر تم چاہو تو تمہارے حق میں فیصلہ کر دوں، پھر ان کے حق میں فیصلہ کر دیا، وہ ان کا شکریہ ادا کرتے ہوئے واپس چلے گئے، عمرو کے سوانح میں آئے گا کہ وہ مجاشع سے پہلے وفات پاگئے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۴۶۶۲) استیعاب (۲۵۴۴) تجرید (۲/۵۱)\n(2) تاریخ کبیر (۴/۲۷)\n(3) بخاری (۳۰۷۸) مسلم (۸۴) مسند احمد (۳/۵۶۸) جامع المسانید والسنن (۱۱/۷۷)"}],[6352,"§۷۷۲۴ ۔ مجاعہ بن مرارہ(1)\nابن سلمی، بقول بعض: سلیم بن زید بن عبید بن ثعلبہ بن یربوع بن ثعلبہ بن دول بن حنیفہ حنفی یمامی، بنو حنیفہ کے رؤساء میں سے ہیں، اسلام لائے اور وفد میں آئے۔ ابوداؤد(2) نے بحوالہ ہلال بن سراج بن مجاعہ، عن ابیہ، عن جدة مجاعہ نقل کیا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس اپنے بھائی کی دیت طلب کرنے آئے، انہیں بنو اسد اور بنو ذہل میں سے تمیم نے قتل کیا، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اگر میں کسی مشرک کو دیت دیتا تو اس کے بھائی کے لیے دیتا، لیکن میں تمہیں اس کا بدلہ دے دوں گا۔ آپ صلی اللہ علیہ وسلم نے انہیں بنو ذہل کے مشرکین کے پہلے خمس میں سے سو(۱۰۰) اونٹوں کی تحریر لکھ دی، انہوں نے اس میں سے کچھ لے لیے۔ بنو ذہل اسلام لے آئے تو مجاعہ نے اسے سیدنا ابوبکر رضی اللہ عنہ سے طلب کیا، انہوں نے ان کے لیے بارہ ہزار(۱۲۰۰۰) ہزار صالح یمامہ کے صدقہ میں سے لکھ کر دیئے.....۔ (الحدیث)\nبغوی نے بحوالہ سراج بن مجاعہ نقل کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے مجاعہ بن مرارہ کو یمامہ میں زمین دی، اسے غورہ کہا جاتا ہے اور انہیں تحریر لکھ کر دی۔\nابن حبان نے صحابہ میں فرمایا: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے زمین کا ٹکڑا مانگا، آپ صلی اللہ علیہ وسلم نے انہیں عطا فرمایا۔ وہ بلاغت سے کلام کرنے والے اور حکمت بھری باتیں کرنے والے تھے۔ ان کی حکمت کی باتوں میں سے یہ ہے کہ انہوں نے سیدنا ابوبکر رضی اللہ عنہ سے فرمایا: جب رائے دینے والے وہ لوگ ہوں جن کی رائے قبول نہ کی جاتی ہو اور ہتھیار اس شخص کے پاس ہوں جو اس سے جنگ نہ کرے، اور مال ایسے شخص کے پاس ہو، جو اسے خرچ نہ کرتا ہو تو تمام کام ضائع ہو گئے۔ مجاعہ، یمامہ کے دن اسیر ہوئے، ساریہ بن عمر حنفی نے سیدنا خالد بن ولید سے فرمایا: اگر آپ کو اہل یمامہ سے کوئی حاجت ہے تو انہیں زندہ رہنے دیں، انہوں نے انہیں ابوبکر صدیق کی طرف بھیج دیا، اس کے بارے میں بنو خیثمہ کا شاعر کہتا ہے:\n\"یمامہ کا مجاشع نامی شخص ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم کی بات بتانے کے لیے آیا، ہم نے اسے قیادت دے دی، اور سیدھے ہو گئے، وہ ایسا شخص تھا جو کہتے سنتا تھا\"۔\nان اشعار میں مجاعہ نے اپنے بارے میں کہا:\n\"کیا تو سمجھتا ہے کہ آج خالد ہمیں چھوٹے گناہ کی وجہ سے جو جھوٹ پر مبنی ہے قتل کردے گا، نبی صلی اللہ علیہ وسلم کی ملت کو نہیں چھوڑا، نہ ہم الٹے پاؤں پھرے ہیں\"۔\nزبیر نے ذکر کیا ہے کہ خالد نے بنت مجاعہ سے اس وقت نکاح کیا، وقیمہ نے کتاب الردہ میں سیدنا خالد رضی اللہ عنہ کے ساتھ اس کے علاوہ واقعہ بیان کیا ہے۔ مرزبانی نے ذکر کیا ہے کہ وہ خلافت معاویہ رضی اللہ عنہ تک زندہ رہے، ان کے اس کے بارے میں شعر نقل کیے ہیں:\n\"معاویہ جب تمہیں کوئی عیب نہ ملا تو تم نے معذرت کر لی، بے شک عذر خواہی بخل کا حصہ ہے، خصوصاً جب تنگدستی اور بغض کے بغیر ہو، جو میرے بارے میں ثابت نہ ہو سکا\"۔\nان کے باقی حالات، آخری قسم میں ان کے والد کے سوانح میں آئیں گے۔ ان شاء اللہ تعالیٰ","",{"fn":"(1) اسد الغابہ (۴۶۶۴) استیعاب (۲۵۴۵) تجرید (۲/۵۱)\n(2) ابوداؤد (۲۹۹۰)"}],[6353,"§۷۷۲۵ ۔ مجالد بن ثور\nابن معاویہ، ان کے وفد میں آنے کا ذکر بشر بن معاویہ کے سوانح میں گزر چکا ہے۔"],[6354,"§۷۷۲۶ ۔ مجالد بن مسعود سلمی(1)\nمجاشع کے بھائی ہیں، جن کا ذکر ابھی گزرا ہے۔ بخاری رحمہ اللہ(2) وغیرہ کا قول ہے۔ اور ابن حبان نے فرمایا کہ صحابی ہیں، ان کے بھائی مجاشع کی حدیث میں ان کا ذکر گزر چکا ہے۔\nبغوی نے بطریق یونس بن عبید، بحوالہ حسن نقل کیا ہے، فرماتے ہیں: بصرہ میں سب سے پہلے وعظ ونصیحت کرنے والے اسود بن سریع ہیں، آوازیں بلند ہوئیں تو مجالد بن مسعود سلمی آئے، لوگوں نے کہا: ان کے لیے جگہ کشادہ کرو، انہوں نے کہا: اللہ کی قسم! میں تمہارے پاس بیٹھنے کے لیے نہیں آیا، لیکن میں نے دیکھا کہ تم ایسا کام کر رہے ہو جس کا مسلمانوں نے انکار کیا ہے۔ تم اس بات سے بچو، جس کا مسلمانوں نے انکار کیا ہے۔ بخاری(3) نے بحوالہ ضمرہ بن ربیعہ نقل کیا ہے کہ مجالد جمل کے دن شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۴۶۶۷) استیعاب (۲۵۴۶) تجرید (۲/۵۱)\n(2) التاریخ الکبیر (۴/۸)\n(3) بخاری (۲۹۶۲، ۳۰۷۸، ۳۰۷۹)"}],[6355,"§۷۷۲۷ ۔ مجالد\nابو عثمہ کے والد ہیں، تجھی میں ان کا ذکر آئے گا۔"],[6356,"§۷۷۲۸ ۔ مجذر بن زیاد(1)\nابن عمرو بن اخرم بن عمرو بن عمارہ بن مالک بن عمرو بن بشیر بن شنوہ بن قشیر بن تیم بن عوذ مناۃ بن ناج بن تیم بن رراشہ بن عامر بن عبیلہ بن قسم بن قران بن بلی بلوی، بقول بعض ان کا نام عبداللہ ہے۔ مجذر لقب ہے۔ اس کا مطلب ہے: موٹا تازہ۔ حارث بن صامت کے سوانح میں ان کا ذکر گزر چکا ہے، موسیٰ بن عقبہ نے بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے۔ اُحد میں شہید ہوئے۔ ابن اسحاق نے قصہ بدر میں بطریق زہری اور بطریق عروہ وغیرہ نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے جو ابو البختری سے ملے، اسے قتل نہ کرے۔\" مجذر ان سے ملے، اور کہا: میں تمہیں قید کرنا چاہتا ہوں، رسول اللہ صلی اللہ علیہ وسلم نے ہمیں تمہارے قتل سے روکا ہے۔ اس نے کہا: میرے ساتھی کے بارے میں کیا حکم ہے؟ مجذر نے کہا: نہیں، اللہ کی قسم! میں اس کا قاتل ہوں، اسے اور اس کے ساتھی کو قتل کر دیا۔\nابن اسحاق(2) نے اسے بروایت ابراہیم بن سعد، ان کی سند سے نقل کیا ہے۔ اس میں ایسا راوی ہے کہ بحوالہ ابن عباس اس کا نام نہیں لیا، یہ اضافہ کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ابو البختری کے اور بنو ہاشم کے قتل سے روکا ہے، کیونکہ وہ زبردستی نکالے گئے تھے۔ موسیٰ بن عقبہ نے بحوالہ ابن شہاب فرمایا: لوگوں کا خیال ہے کہ ابو یسر نے ابو البختری کو قتل کیا، بہت سے لوگوں کا خیال ہے کہ مجذر نے اسے قتل کیا تھا۔\nاسی طرح زبیر بن بکار اور واقدی نے اس پر اعتماد کیا ہے، حاکم نے بطریق محمد بن یحییٰ بن حبان ان سب نے نقل کیا ہے کہ مجذر نے اسے قتل کیا تھا، مجذر نے جاہلیت میں سوید بن صامت کو قتل کیا تھا، جب اُحد کا دن ہوا تو حارث بن سوید نے مجذر کو دھوکے سے قتل کر دیا، اور بھاگ گیا، مکہ پناہ حاصل کی اور مرتد ہو گیا، پھر فتح مکہ کے دن اسلام لایا، رسول اللہ صلی اللہ علیہ وسلم نے اسے مجذر کے بدلے قتل کر دیا۔ حارث کے سوانح میں اس کی طرف اور جو کچھ جھگڑا ہوا اس کے بارے میں اشارہ گزر چکا ہے۔ ابن حبان نے مجذر کا صحابہ میں ذکر کیا ہے، فرماتے ہیں: صحابی ہیں۔ مجھے ان کی کوئی روایت یاد نہیں۔","",{"fn":"(1) اسد الغابہ (۴۶۷۰) استیعاب (۲۵۴۹) تجرید (۲/۵۱)\n(2) السیرۃ النبویۃ (۲/۲۰۴)"}],[6357,"§۷۷۲۹ ۔ مجذر انصاری\nدوسرے ہیں، ابن شاہین نے ان کا ذکر کیا ہے اور بطریق ابو زکریا خواص بحوالہ انس ذکر کیا ہے، فرماتے ہیں: عکرمہ بن ابو جہل نے مجذر انصاری کو خندق کے دن شہید کیا، نبی کریم صلی اللہ علیہ وسلم کو اس کی خبر دی گئی تو آپ ہنسنے لگے، انصار نے کہا: آپ اس لیے ہنس رہے ہیں کہ آپ کی قوم کے ایک شخص نے ہماری قوم کے ایک شخص کو قتل کر دیا ہے؟! آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں اس وجہ سے نہیں ہنس رہا، بلکہ اس وجہ سے کہ اس نے اسے قتل کیا اور وہ جنت میں اس کے ساتھ اس کے درجے میں ہے\"۔\nمیں کہتا ہوں: یہ پہلے والے کے علاوہ ہیں، کیونکہ وہ اُحد میں شہید ہوئے اور ان کا قاتل حارث بن سوید ہے جیسا کہ آپ دیکھتے ہیں، ابو موسیٰ نے اپنے استدراک میں ان کا ذکر نہیں کیا، وہ ان کی شرط کے مطابق ہے، میرا خیال ہے کہ وہ پہلے والے ہی ہیں۔"],[6358,"§۷۷۳۰ ۔ مجذی ضمری(1)\nابن سکن وغیرہ نے ان کا ذکر کیا ہے۔ ابن حبان کا قول ہے: بقول بعض صحابی ہیں، ابو عمر(2) کا قول ہے: محمد بن سلیمان بن مسمول کے ہاں بحوالہ فرج بن عطا بن مجدی، عن ابیہ، عن جدة ان کی حدیث ہے۔ میں کہتا ہوں: دونوں ناموں میں لفظی غلطی ہے، وہ ابو مخرج کنیت کے الفاظ ہیں، ان کے والد عطی ہیں، اسی طرح بخاری رحمہ اللہ(3) نے تاریخ میں اور ابن ابی عاصم اور ابن سکن وغیرہ نے ذکر کیا ہے۔\nابن فتحون کا قول ہے: میں نے اسے حافظ ابن علی پر پیش کیا، انہوں نے اسے مستحسن کہا اور صحیح قرار دیا، اپنی کتاب میں اس پر تنبیہ کی ہے، ان کی حدیث کے الفاظ یہ ہیں: رسول اللہ صلی اللہ علیہ وسلم ایک شخص کو ایک اونٹ اور دو اونٹ عطا کرتے تھے۔ قریش کی ایک بڑھیا آئی، جس کے سر کے ملے جلے سفید سیاہ بال تھے، کبڑی تھی، بڑھاپے سے گویا زمین پر رینگ رہی تھی، وہ جھک کر چل رہی تھی۔ اس نے آپ صلی اللہ علیہ وسلم سے سوال کیا، آپ صلی اللہ علیہ وسلم نے اسے تین اونٹ دیئے۔\nابن مندہ نے بطریق محمد بن سلیمان بن مسمول اس سند سے دوسری حدیث نقل کی ہے۔ اس کا متن یہ ہے: ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بنو مصطلق میں جہاد کیا، ہمیں قیدی ملے، ہم نے رسول اللہ صلی اللہ علیہ وسلم سے عزل کے بارے میں پوچھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم چاہتے ہو تو کر لو، جو جان بھی قیامت تک آنے والی ہے وہ آکر رہے گی\"۔(4) محمد بن سلیمان ضعیف راوی ہیں، ابن قانع نے ذکر کیا ہے کہ ان کا نام مجید ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۶۸) استیعاب (۲۵۴۷) تجرید (۲/۵۱)\n(2) استیعاب (۴/۲۱)\n(3) تاریخ کبیر (۴/۵۵)\n(4) بخاری (۲۲۲۹) مسلم (۳۵۲۹) ابوداؤد (۲۱۷۲) جامع المسانید والسنن (۱۱/۸۴) اسد الغابہ (۴/۴۷)"}],[6359,"§۷۷۳۱ ۔ مجدی بن قیس اشعری(1)\nابو موسیٰ کے بھائی ہیں، ابن فتحون نے ذیل میں ان کا ذکر کیا ہے اور مغازی اموی کی طرف اس کی نسبت کی ہے کہ انہوں نے اس میں بحوالہ ابن اسحاق ذکر کیا ہے کہ وہ ان لوگوں میں سے تھے جو ابو موسیٰ کے ساتھ آئے تھے، جو ابن مندہ نے بحوالہ مغازی اموی نقل کیا ہے، وہ محمد بن قیس ہے، جیسا کہ ابو بردہ بن قیس اشعری کے سوانح میں آئے گا کہ ابو موسیٰ نکلے اور ان کے ساتھ ان کے دو بھائی ابو بردہ اور ابو رہم تھے، اگر مجدی محفوظ ہے تو احتمال ہے کہ وہ ابو رہم کا نام ہو۔\nمحمد بن قیس کے سوانح میں اس کے بارے میں مزید آئے گا، بقول بعض وہ ابو رہم کا نام ہے۔ ایک قول ہے کہ ان کا نام مجید ہے جو عظیم کے وزن پر ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۶۹) استیعاب (۲۵۴۸) تجرید (۲/۵۱)"}],[6360,"§۷۷۳۲ ۔ مجزأۃ بن ثور(1)\nابن صفیر بن زہیر بن عمرو بن کعب بن سدوس سدوسی، ابن مندہ کا قول ہے: بخاری رحمہ اللہ نے صحابہ میں ان کا ذکر کیا ہے، وہ ثابت نہیں، انہوں نے عبد الرحمن ابن ابی بکرہ سے روایت کیا۔ میں کہتا ہوں: یہ اطلاق غلط ہے، بروایت عبد الرحمن بن ابی بکرہ قصہ مذکورہ ہے، جس میں بحوالہ مجزأۃ بن ثور حدیث منقول ہے، ابن ابی شیبہ کا قول ہے: ہم سے ابو نوح نے بحوالہ عبد الرحمن بن ابی بکرہ نقل کیا، فرماتے ہیں: جب ابو موسیٰ لوگوں کو لے کر ہرمزان اور ان کے ساتھیوں کے پاس تستر میں ٹھہرے، لکھتے ہیں کہ یہ لوگ سال بھر ٹھہرے رہے اس تک پہنچنے نہ پاتے تھے، ہرمزان نے ان کا کوئی سوداگر قتل کر دیا تھا، ان کا بھائی ابو موسیٰ رضی اللہ عنہ کے پاس گیا اور آپ کو ان کے خفیہ ٹھکانوں کا رستہ بتا دیا۔ سیدنا ابو موسیٰ رضی اللہ عنہ نے ان کے ساتھ مجزأۃ بن ثور کو روانہ کیا، پھر وہ اس کاریز سے داخل ہوئے جس میں نہر کا پانی جاتا تھا۔ یہاں تک کہ مسلمان اس میں سے داخل ہوئے تو اللہ تعالیٰ نے انہیں فتح دی، قصہ طویل ہے، میں نے حرف جیم میں اس میں سے کچھ جہان میں ذکر کیا ہے۔ طبری(2) نے ذکر کیا ہے کہ ابو موسیٰ نے بہت بڑا لشکر بھیجا اور سہل بن عدی کو ان کا امیر بنایا، ان کے ساتھ براء بن مالک، مجزأۃ بن ثور کو صحابہ کی جماعت کے ساتھ بھیجا جن کے نام انہوں نے بیان کیے۔ ان کا آمنا سامنا ہوا، ہرمزان نے مجزأۃ اور براء کو شہید کر دیا۔ پھر قصہ ذکر کیا۔ قسم ثالث میں سیاہ کے سوانح میں ان کا ذکر گزر چکا ہے (ت ۳۷۲۷ ج اول)۔\nبخاری رحمہ اللہ(3) نے اپنی تاریخ میں فرمایا: ہم سے احمد بن یونس نے بحوالہ حمید نقل کیا ہے کہ سیدنا انس رضی اللہ عنہ نے فرمایا... پھر ہرمزان کا قصہ نقل کیا، اس میں ہے سیدنا عمر رضی اللہ عنہ نے فرمایا: اے انس! مجھے براء بن مالک اور مجزأۃ بن ثور کے قاتل سے حیا آتی ہے۔\nخالد بن معمر کے سوانح میں گزر چکا ہے کہ وہ بکر بن وائل کے امیر تھے۔ ان کے ساتھ مجزأۃ بن ثور تھے، مجزأۃ کا شفیق نامی بیٹا تھا جو خلافت عثمانی میں بکر بن وائل کا رئیس تھا، پھر سیدنا علی رضی اللہ عنہ نے انہیں وہاں سے ہٹا کر ابو ساسان، حصین بن منذر کی طرف بھیج دیا۔","",{"fn":"(1) اسد الغابہ (۴۶۷۱) تجرید (۲/۵۲)\n(2) تاریخ طبری (۲/۵۰۱)\n(3) تاریخ کبیر (۸/۳۹)"}],[6361,"§۷۷۳۳ ۔ مجرز مدلجی(1)\nوہ ابن اعور بن جعدہ بن معاذ بن عتوارہ بن عمرو بن مدلج کنانی ہیں، صحیحین میں بطریق زہری، بحوالہ عائشہ رضی اللہ عنہا مروی ہے، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم میرے پاس آئے، آپ کا چہرہ خوشی سے چمک رہا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: تمہیں معلوم ہے کہ مجرز مدلجی نے ابھی زید بن حارثہ اور اسامہ بن زید کو دیکھا اور کہا: \"یہ پاؤں ایک دوسرے سے تعلق رکھتے ہیں\"۔(2)\nابن قتیبہ کی روایت میں ہے، وہ سیدنا زید اور اسامہ کے پاس سے گزرے، دونوں نے اپنے سر ڈھانپے ہوئے تھے اور ان کے پاؤں کھلے تھے۔ قاسم بن ثابت نے دلائل میں بحوالہ مصعب زبیری نقل کیا ہے کہ ان کا نام مجزز نہیں تھا، ان کا یہ نام اس لیے پڑ گیا، کیونکہ جب وہ کسی کو قیدی بناتے تو اس کی پیشانی کے بال کاٹ دیتے، پھر اسے چھوڑ دیتے۔\nابن یونس نے تاریخ مصر میں ان کا ذکر کیا ہے، فرماتے ہیں: انہوں نے اپنی کتابوں میں یعنی فتح مصر میں شریک ہونے والوں کے بارے میں لکھی گئی کتابوں میں ان کا ذکر کیا ہے۔ فرماتے ہیں: مجھے ان کی کوئی روایت معلوم نہیں۔\nمیں کہتا ہوں: جمہور میں سے جنہوں نے صحابہ رضی اللہ عنہم کے بارے میں کتابیں لکھی ہیں انہوں نے ان کا ذکر نہیں کیا، لیکن ابو عمر(3) نے استیعاب میں ان کا ذکر کیا ہے۔ ابن اثیر(4) نے ذکر کیا ہے کہ ابو نعیم نے ان کا ذکر کیا ہے، ابن مندہ ان کے ذکر سے غافل ہو گئے، ابو موسیٰ نے اپنے استدراک میں ان کا ذکر نہیں کیا۔\nمیں کہتا ہوں: میں نے ابو نعیم کی کتاب معرفۃ الصحابہ کے اس نسخے میں جو میرے پاس ہے اس میں ان کا ذکر نہیں دیکھا، حالانکہ وہ معتبر نسخہ ہے۔ اگر انہوں نے ان کا ذکر کیا ہوتا تو ابو موسیٰ ان کا نام ترک نہ کرتے، جیسا کہ ابو نعیم کے اتباع میں ان کی عادت ہے ہم اس شخص کے بارے میں جس کا ذکر وہ ابن مندہ سے زائد کرتے ہیں۔ اگر ابن یونس یہ ذکر نہ کرتے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے بعد فتوحات میں شریک ہوئے تو جن لوگوں نے انہیں صحابہ رضی اللہ عنہم میں ذکر کیا ہے تو ان کے لیے ان کے مسلمان ہونے کی واضح دلیل بن جاتی۔ یہ بھی احتمال ہے کہ جو کچھ انہوں نے سیدنا زید اور اسامہ کے بارے میں کہا تھا وہ اپنے مسلمان ہونے سے پہلے کہا ہو۔ اور علم قیافہ نہ جاننے کی وجہ سے آپ نے ان کی بات کا اعتبار کر لیا ہو، لیکن نبی علیہ السلام کی رضا مندی اور آپ صلی اللہ علیہ وسلم کی قربت کے قرینے سے پتہ چلتا ہے کہ آپ علیہ السلام نے ان کی بات کا اعتماد کر لیا تھا۔ ورنہ اگر وہ کافر ہوتے تو آپ صلی اللہ علیہ وسلم کا شرعی حکم میں ان کی بات پر اعتماد نہ کرتے۔","",{"fn":"(1) اسد الغابہ (۴۶۷۲) استیعاب (۲۵۵۰) تجرید (۲/۵۲)\n(2) بخاری (۶۷۷۱) مسلم (۳۶۰۳) ترمذی (۲۱۲۹) ابوداؤد (۳۴۹۴) ابن ماجہ (۲۳۴۹)\n(3) استیعاب (۴/۲۳)\n(4) اسد الغابہ (۴/۴۸)"}],[6362,"§۷۷۳۴ ۔ مجضہ بن نعمان عتکی(1)\nازد کے شاعر تھے، نبی کریم صلی اللہ علیہ وسلم نے عمرو بن عاص کو ان پر امیر بنایا، جب آپ صلی اللہ علیہ وسلم کی وفات ہوئی اور عرب کے بعض قبائل مرتد ہو گئے تو سیدنا عمرو بن العاص کو ان کے مرتد ہونے کا خدشہ ہوا، انہوں نے ان سے مدینہ لوٹنے کی اجازت مانگی تو ان سے مجضہ نے کہا:\n\"اے عمرو! اگر محمد صلی اللہ علیہ وسلم واقعی نبی ہیں، اور انہیں ایسی چیز لائی ہے جسے روکا نہیں جا سکتا تو ہمارے دل زخمی اور ہماری آنکھوں سے آنسو جاری اور مخلوق کی گردنیں جھکی ہوئی ہیں، اے عمرو! ان کی حیات ہمارے درمیان ان کی وفات کی طرح ہے، جو وہ کہتے ہیں ہم اسے بصیرت سے دیکھتے اور سنتے ہیں، اے عمرو! تم قائم رہو اور ہماری واپسی کا خوف نہیں کرو گے یہی وہ غالب اور طاقت والی ذات ہے\"۔\nوثیمہ نے کتاب الردہ میں بحوالہ محمد بن اسحاق ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲/۵۲)"}],[6363,"§۷۷۳۵ ۔ مجمع بن جاریہ(1)\nابن عامر بن مجمع بن عطاف بن ضبیعہ بن زید بن مالک بن عوف بن عمرو بن عوف انصاری اوسی، سعید بن عبید بن قیس کے سوانح میں ان کا ذکر ہے، سنن میں ان کی تین احادیث مروی ہیں، ترمذی نے ان میں سے بعض کو صحیح قرار دیا ہے۔\nابن اسحاق(2) نے مغازی میں فرمایا: مجمع بن جاریہ بن عطاف نوجوان تھے، انہوں نے قرآن یاد کر لیا تھا، ان کے والد جاریہ نے مسجد ضرار بنائی، مجمع ان لوگوں کو اس میں نماز پڑھاتے تھے، پھر اسے جلا دیا گیا۔ جب سیدنا عمر بن خطاب رضی اللہ عنہ کا زمانہ آیا تو انہوں نے مجمع کے بارے میں بات کی کہ انہیں اپنی قوم کا امام بنا دیں۔ انہوں نے کہا: نہیں۔ کیا وہ مسجد ضرار میں منافقین کا امام نہیں تھا؟ انہوں نے کہا: اللہ کی قسم! جس کے سوا کوئی معبود نہیں، مجھے ان کے بارے میں کسی چیز کا علم نہیں۔ لوگوں نے خیال کیا کہ سیدنا عمر رضی اللہ عنہ نے انہیں نماز پڑھانے کی اجازت دے دی ہے۔ بقول بعض: سیدنا عمر رضی اللہ عنہ نے انہیں اہل کوفہ کی طرف بھیجا، تا کہ انہیں قرآن سکھائیں، تو انہوں نے ابن مسعود رضی اللہ عنہ سے قرآن سیکھا، انہوں نے انہیں قرآن سکھایا۔","",{"fn":"(1) اسد الغابہ (۴۶۷۳) استیعاب (۲۳۳۴) تجرید (۲/۵۲)\n(2) السیرۃ النبویۃ (۴/۱۳۶)"}],[6364,"§۷۷۳۶ ۔ مجمع بن یزید(1)\nابن جاریہ انصاری، پہلے والے کے بھتیجے ہیں۔ ابن حبان کا قول ہے: صحابی ہیں۔ بقول بعض: وہ دونوں ایک ہیں: ابن سکن وغیرہ نے ان دونوں کے درمیان فرق کیا ہے۔ مسند احمد(2) اور ابن ماجہ(3) میں ان کی حسن اسناد کی حدیث ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۷۴) استیعاب (۲۳۳۵) تجرید (۲/۵۲)\n(2) مسند احمد (۳/۴۱۰)\n(3) ابن ماجہ (۲۳۳۶)"}],[6365,"§۷۷۳۷ ۔ مجید\nمجدی میں ان کا ذکر آئے گا۔"],[6366,"§۷۷۳۸ ۔ محارب بن مزیدہ(1)\nابن مالک بن ہمام بن معاویہ بن شبابہ بن عامر بن حطمہ بن محارب بن عمرو بن ودیعہ بن لکیز بن امضی بن عبد القیس عبدی، پھر محاربی، ابن کلبی کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کے پاس وہ اور ان کے والد وفد میں آئے، وہ دونوں اسلام لائے، رشاطی کا قول ہے: ابن عمر اور ابن فتحون نے ان کا ذکر نہیں کیا۔\nدار قطنی رحمہ اللہ نے اور ابن ماکولا(2) نے بحوالہ ابن کلبی ان کا ذکر کیا ہے۔ ابن اثیر(3) نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۷۵) تجرید (۲/۵۲)\n(2) الإکمال (۳/۱۶۶)\n(3) اسد الغابہ (۴/۵۰)"}],[6367,"§۷۷۳۹ ۔ محتفر بن اوس(1)\nابن زیاد بن احم بن ربیعہ بن عدی بن ثعلبہ بن ذؤیب بن سعد مزنی، ابن حبان نے ان کے والد کی سوانح میں ان کا نسب بیان کیا ہے۔ حاکم نے تاریخ نیشا پور میں فرمایا: المحتفر بن اوس بن نصر بن زیاد، رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے ہیں، عباس بن مصعب نے ذکر کیا ہے کہ وہ خراسان آئے۔ احمد بن سنان کا قول ہے: مرو کو اپنا وطن بنا لیا، بشر بن محتفر نے ذکر کیا ہے کہ وہ خراسان میں اپنے والد کے ساتھ، عبد الرحمن ابن سمرہ کے لشکر میں تھے۔ پھر بطریق عیسیٰ بن موسیٰ غنجار، بحوالہ محتفر نقل کیا ہے کہ انہوں نے درخت کے نیچے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی تھی، انہوں نے سات افراد کی طرف سے اونٹ ذبح کیا تھا۔","",{"fn":"(1) اسد الغابہ (۴۶۷۶) تجرید (۲/۵۲)"}],[6368,"§۷۷۴۰ ۔ محجن بن ادرع اسلمی(1)\nمدنی۔ ابو عمر(2) کا قول ہے: قدیم الاسلام ہیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی، ان سے حنظلہ بن علی اسلمی، رجاء ابن ابی رجاء، عبد اللہ بن شقیق نے روایت کی، سکبہ اسلمی کی سوانح میں ان کا ذکر گزر چکا ہے، ابو احمد عسکری کے ہاں ہے کہ وہ سلمی ہیں، انہوں نے ان کا تعاقب کیا ہے، ابو عمر(3) کا قول ہے: بصرہ میں رہائش اختیار کی، یہ وہی ہیں جنہوں نے بصرہ کی مسجد کا نقشہ بنایا، انہوں نے طویل عمر پائی۔\nصحیح میں حدیث سلمہ بن اکوع میں ہے: تیراندازی کرو، میں ابن ادرع ہوں، بخاری نے ادب المفرد میں سنن ابوداؤد، نسائی اور صحیح ابن خزیمہ نے بطریق عبد اللہ بن بریدہ اسلمی، بحوالہ حنظلہ بن علی بن محجن بن ادرع نقل کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم مسجد میں داخل ہوئے تو وہاں ایک شخص تشہد میں بیٹھا اپنی نماز مکمل کرنے کو ہی تھا۔۔۔۔ (الحدیث)(4)\nابن اسحاق نے مغازی میں بحوالہ سفیان بن فروہ اسلمی، صحابہ میں سے اپنے شیوخ کے حوالے سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کا گزر ہوا، ہم تیراندازی کر رہے تھے، ہم میں محجن بن ادرع، قبیلہ اسلم کے ایک شخص کے ساتھ تیراندازی کر رہے تھے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"بنو اسماعیل تیراندازی کرو، تمہارا باپ تیر انداز تھا، تیراندازی کرو! میں ابن ادرع کے ساتھ ہوں\"۔ نضلہ نے اپنے ہاتھ سے کمان پھینک دی اور کہا: اللہ کی قسم! میں اس کے ساتھ تیر اندازی نہیں کروں گا جبکہ آپ اس کے ساتھ ہیں۔ جس کے ساتھ آپ ہوں وہ کیسے مغلوب ہو سکتا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تیراندازی کرو! میں تم سب کے ساتھ ہوں\"۔(5) ابو عمر کا قول ہے: بقول بعض: خلافت معاویہ رضی اللہ عنہ کے آخر میں وفات پائی۔","",{"fn":"(1) اسد الغابہ (۴۶۷۷) استیعاب (۲۳۳۶) تجرید (۲/۵۲)\n(2) استیعاب (۳/۴۱۹)\n(3) استیعاب (۳/۴۱۹)\n(4) ابوداؤد (۱۲۹۵، ۱۲۹۶) نسائی (۱۳۰۱)\n(5) بخاری (۲۸۹۹) مستدرک حاکم (۲/۹۴) معجم الکبیر (۶۲۹۲/۷) (۶۲۹۲/۳) مجمع الزوائد (۲۶۸۱۵) کنز العمال (۱۰۸۵۲)"}],[6369,"§۷۷۴۱ ۔ محجن بن ابی محجن دئلی(1)\nابو عمر(2) کا قول ہے: اہل مدینہ میں ان کا شمار ہے، ان سے ان کے بیٹے بسر نے روایت کی، مالک نے باء کے پیش اور سین کے سکون سے اور ثوری نے زیر اور شین کے ساتھ جاڑہ کی طرح نقل کیا ہے۔ ابو عمر کا قول ہے: اکثریت نے امام مالک کے قول کو لیا ہے۔\nموطا اور بخاری نے ادب المفرد میں اور نسائی، ابن خزیمہ، حاکم نے بروایت مالک، بحوالہ بسر بن محجن دئلی، عن ابیہ نقل کیا ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھے ہوئے تھے کہ نماز کے لیے اذان ہوئی، نبی کریم صلی اللہ علیہ وسلم تشریف لے گئے پھر واپس آئے، اور محجن اسی مجلس میں تھے۔ (الحدیث)(3)\nبقول بعض: مذکورہ محجن جمادی الاولیٰ ۶ھ میں جشمی کی طرف سریہ زید بن حارثہ میں تھے، ابن حذاء نے رجال موطا میں اس پر اعتماد کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۷۸) استیعاب (۲۳۳۷) تجرید (۲/۵۲)\n(2) استیعاب (۳/۴۹۹)\n(3) نسائی (۸۵۷) مسند احمد (۴/۳۴) مستدرک حاکم (۱/۲۴۴) صحیح ابن حبان (۲۴۰۵) طبرانی (۶۷۹/۲۶)"}],[6370,"§۷۷۴۲ ۔ مخدوج(1)\nابن زید ہذلی، قیس بن ربیع کوفی نے اپنی مسند میں ان کا ذکر کیا ہے، انہوں نے بحوالہ سعد اسکاف نقل کیا ہے کہ میں نے عطیہ سے ان کے حوالے سے سنا، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے نقل کیا ہے فرمایا: \"قیامت کے دن سب سے پہلے مجھے بلایا جائے گا\"۔ ہم سے ابو نعیم(2) نے نقل کیا ہے، فرماتے ہیں: ان کے صحابی ہونے میں اختلاف ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۷۹) تجرید (۲/۵۲)\n(2) جامع المسانید والسنن (۱۱/۱۰۱)"}],[6371,"§۷۷۴۳ ۔ محربہ\nمسلمہ کے وزن پر ہے، ابن رباب شنی۔ ابو فرج اصبہانی نے عبد یغوث بن حداد کی سوانح میں فرمایا: بقول بعض: وہ کہانت کیا کرتے تھے۔ ابو یقطان نے ذکر کیا کہ وہ جاہلیت میں نصرانی ہو گئے تھے، نبی کریم صلی اللہ علیہ وسلم کے مبعوث ہونے سے پہلے لوگوں نے رات کو ایک پکارنے والے کی آواز سنی: زمین پر تین لوگ بہترین ہیں: رباب شنی، بحیرا راہب اور ایک اور نام لیا، فرماتے ہیں: ان کی اولاد میں محربہ ہیں، ان کا نام اس لیے رکھا گیا، کیونکہ ہتھیاروں نے انہیں جنگجو بنا دیا تھا کیونکہ وہ اکثر مسلح رہتے، انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، آپ نے انہیں عمان کے حاکم ابن جلندی کی طرف بھیجا، ان کا بیٹا منی بن محربہ تھا جو مختار کا ساتھی تھا۔ اس نے انہیں لشکر دے کر بصرہ بھیجا، تا کہ اس پر قبضہ کر لے، عباد بن حصین نے اسے شکست دی۔"],[6372,"§۷۷۴۴ ۔ محرزہ بن عامر(1)\nابن مالک بن عدی بن عامر بن غنم بن عدی بن نجار انصاری بخاری، موسیٰ بن عقبہ، ابن اسحاق(2) اور کئی لوگوں نے بدر میں شریک ہونے والے صحابہ میں ان کا ذکر کیا ہے۔\nابن ماکولا(3) نے مہملات میں محمد کے وزن پر اسے لکھا ہے۔ دار قطنی نے ان لوگوں کے ناموں کے ساتھ ان کا ذکر کیا ہے جو تقبل کے وزن پر ہیں، ان لوگوں کے ناموں کی طرح جن کا ذکر ابھی ہوتا ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۸۲) الاستيعاب (۲۳۴۰)\n(2) السیرۃ النبویۃ (۲/۲۶۳)\n(3) الإکمال (۷/۱۶۷)"}],[6373,"§۷۷۴۵ ۔ محرز بن اسید\nابن انشن بن ریاح بن ابی خالد بن ربیعہ بن عمرو بن سلامہ باہلی، انہوں نے نبوت کا زمانہ پایا، ابو بشر دولانی نے کنیتوں میں ان کے بیٹے ادھم کی سوانح میں، بروایت ادھم ان کا ذکر کیا ہے، فرماتے ہیں: جمع میں داخل ہونے والا جھنڈا ان کا تھا، شہر کے گرد میسرہ بن مسروق کا جھنڈا گاڑا گیا، فرماتے ہیں: ابو امامہ کا ایک جھنڈا تھا، ابو محرز بن اسید کا ایک جھنڈا تھا، فرماتے ہیں: میرے والد پہلے مسلمان تھے جنہوں نے حمص میں کسی مشرک کو قتل کیا تھا، انہوں نے خضاب کے بارے میں کہا:\n\"جب میں نے دیکھا کہ سفید بالوں والے کے لیے کوئی چیز ہے تو میں نے سفید رنگ اختیار کر لیا اور جوانی کو ایک درہم کے بدلے خرید لیا\"۔\nادھم واقعہ عین الوردہ میں ہے شامی امراء میں سے تھے، انہوں نے فتح کی خوشخبری دی وہ پہلے ہیں حمص میں جن کی ولادت ہوئی، اور پہلے ہیں جن کا وہاں وظیفہ مقرر ہوا۔\nمیں کہتا ہوں: پہلے گزر چکا ہے کہ وہ فتوحات کے زمانے میں صرف صحابہ کو امیر بناتے تھے، تو محرز اس وجہ سے پہلی قسم میں سے ہوں گے، میں نے قسم رابع میں اس کی طرف اشارہ کر دیا ہے۔"],[6374,"§۷۷۴۶ ۔ محرز بن حارثہ(1)\nابن ربیعہ بن عبد العزی بن عبد شمس عبشمی، بخاری کا قول ہے: حارثہ بن محرز اور اس پر اضافہ نہیں کیا۔ فاکہی نے مکہ کے والیوں میں فرمایا: ان میں محرز ہیں پھر ان کا ذکر کیا، فرماتے ہیں: ایک قول ہے کہ سیدنا عمر رضی اللہ عنہ کے والی تھے، بلاذری کا قول ہے: حارثہ بن ربیعہ کے ہاں محرز یا حریز یا حزار پیدا ہوئے، عتاب بن اسید نے محرز کو کسی سفر میں مکہ کا نائب بنایا، ان کی اولاد میں سے علاء بن عبد الرحمن بن محرز ہیں، سیدنا ابن زبیر کے زمانے میں کوفہ کے چوتھائی حصے کے امیر تھے۔ ان کا بیٹا کوفہ میں جس گلی میں رہتا تھا، اسے کوچہ بنو گرز کہا جاتا ہے۔ ابن عبدالبر(2) کا قول ہے: سیدنا عمر رضی اللہ عنہ نے اپنی خلافت کی ابتداء میں مکہ کا امیر بنایا پھر معزول کر دیا، جمل کے واقعہ میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۴۶۸۰) استیعاب (۲۵۵۱) تجرید (۲/۵۲)\n(2) استیعاب (۴/۲۳)"}],[6375,"§۷۷۴۷ ۔ محرز بن زہیر(1)\nبقول بعض: ابن زہر اسلمی، بغوی نے صحابہ میں ان کا ذکر کیا ہے، بطریق سفیان بن حمزہ بحوالہ محرز بن زہر کی اُم ولد، جو قبیلہ اسلم کے ایک شخص تھے، نبی کریم صلی اللہ علیہ وسلم کے اصحاب میں سے ہیں، فرماتے ہیں: میں محرز کو یہ کہتے ہوئے سن رہا تھا: اے اللہ! میں جھوٹوں کے زمانے سے تیری پناہ چاہتا ہوں۔\nبخاری(2) کا قول ہے: محرز بن زہیر صحابی ہیں، اور یہ حدیث ذکر کی، دارقطنی، ابن مندہ اور ابن عبدالبر(3) نے ان کی متابعت کی ہے، ابو نعیم کا قول ہے: صحیح زہر ہے، راویوں میں ان کے والد کے نام کے بارے میں اختلاف ہے بحوالہ کثیر بن زید، فرماتے ہیں: عن سلیمان بن حمزہ، زہر ہے، عبد العزیز بن ابی حازم کا قول ہے: زہیر، اسی طرح مصعب زبیری نے بحوالہ ابن ابی حازم نقل کیا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۴۶۸۱) استیعاب (۲۳۳۹) تجرید (۲/۵۳)\n(2) بخاری تاریخ کبیر (۷/۴۳۲، ۴۳۳)\n(3) استیعاب (۳/۴۲۰)"}],[6376,"§۷۷۴۸ ۔ محرز بن نضلہ(1)\nابن عبد اللہ بن مرہ بن کثیر بن غنم بن دودان بن اسد بن خزیمہ اسدی، ابو نضلہ، اخرم کے نام سے مشہور ہیں، موسیٰ بن عقبہ اور ابن اسحاق(2) وغیرہ نے بدری صحابہ میں ان کا ذکر کیا ہے۔ سلمہ بن اکوع کی طویل حدیث میں ان کا ذکر ہے جو مسلم میں ہے، اس میں ہے: میں اپنی جگہ پر ٹھہرا رہا، یہاں تک کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے شہسواروں کو مسواک کرتے ہوئے دیکھا ان کے پہلے دستے کے امیر اخرم اسدی تھے اور ان کے پیچھے ابو قتادہ تھے۔ فرماتے ہیں: میں نے اخرم کے گھوڑے کی لگام پکڑی اور کہا: اے اخرم! ان سے ڈرو! تمہیں رسول اللہ صلی اللہ علیہ وسلم اور ان کے اصحاب کے ملنے سے پہلے قتل نہ کر دیں، انہوں نے کہا: اے سلمہ! اگر تم اللہ اور یوم آخرت پر ایمان رکھتے ہو اور تم جانتے ہو کہ جنت اور جہنم برحق ہیں تو میرے اور شہادت کے درمیان حائل نہ ہو۔ فرماتے ہیں: میں نے انہیں چھوڑ دیا، ان کا اور عبد الرحمن بن عیینہ فزاری کا آمنا سامنا ہوا، عبد الرحمن نے ان کے گھوڑے کی ٹانگیں کاٹ ڈالیں، عبد الرحمن نے اسے نیزہ مارا تو وہ گر گیا، وہ عبد اللہ کے گھوڑے پر بیٹھ گیا، ابو قتادہ نے عبد الرحمن کے ساتھ مل کر پیچھے سے اسے نیزہ مارا اور قتل کر دیا، میں کہتا ہوں یہ غزوہ ذی قرد کا واقعہ ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۸۵) استیعاب (۲۳۴۲) تجرید (۲/۵۳)\n(2) السیرۃ النبویۃ (۲/۸۷، ۸۸)"}],[6377,"§۷۷۴۹ ۔ محرز (بے نسبت)(1)\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق ابراہیم بن محمد بن ثابت، بحوالہ عکرمہ بن خالد نقل کیا ہے کہ میرے پاس ایک رات محرز آئے اور ہمیں رات کے کھانے کی دعوت دی، انہوں نے کہا: کیا تمہارے پاس مسواک ہے، انہوں نے کہا: تم اس وقت اس کا کیا کرو گے۔ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم مسواک کئے بغیر نہیں سوتے تھے۔","",{"fn":"(1) اسد الغابہ (۴۶۸۶)"}],[6378,"§۷۷۵۰ ۔ محرش(1)\nابن ماکولا(2) نے ہشام بن یوسف اور یحییٰ بن معین کی پیروی کرتے ہوئے اسے ضبط کیا ہے۔ ابن سکن نے ابن مدینی کی پیروی سے اسے درست قرار دیا ہے وہ ابن سوید بن عبد اللہ بن مرہ خزاعی کتھی ہیں، اہل مکہ میں ان کا شمار ہے۔\nعمرو بن علی فلاس کا قول ہے: وہ مکہ میں سالم نامی شیخ سے ملے، جس سے منی تک جانے کے لیے کرائے پر اونٹ لیا۔ اس سے سنا کہ وہ حدیث محرش نقل کر رہے تھے، انہوں نے کہا: وہ میرے دادا ہیں، وہ محرش بن عبد اللہ کتھی ہیں، میں نے ان سے کہا: آپ نے کس سے سنا؟ انہوں نے کہا: مجھ سے میرے والد اور ہمارے گھر والوں نے نقل کیا، ابوداؤد، نسائی وغیرہ کے پاس ان کی حدیث حسن سند سے ہیں۔ اس کے الفاظ نسائی کے ہیں بروایت اسماعیل بن ابو امیہ بحوالہ محرش کتھی کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو جعرانہ سے رات کے وقت نکلتے ہوئے دیکھا، میں نے آپ صلی اللہ علیہ وسلم کی کمر مبارک کو دیکھا گویا وہ چاندی کا ڈلا ہے، آپ صلی اللہ علیہ وسلم نے عمرہ کیا، اور یہاں رات ایسے جیسے کوئی کسی کے ہاں رات رہتا ہے۔\nترمذی رحمہ اللہ نے اسے ابن جریج کی روایت سے بحوالہ مزاحم نقل کرنے کے بعد فرمایا: اس کے الفاظ یہ ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جعرانہ سے رات کے وقت عمرہ کا احرام باندھے، نکلے اور مکہ میں رات کے وقت داخل ہوئے، اپنا عمرہ پورا کیا، پھر رات کے وقت وہاں سے تشریف لائے اور جعرانہ میں صبح کی جیسا کہ کوئی رات گزارتا ہے جب اگلے دن کا سورج غروب ہوا تو بطن سرف سے نکلے یہاں تک کہ مزدلفہ کے ساتھ ساتھ میدان سرف کے وسط تک پہنچ گئے۔ اس وجہ سے لوگوں کے لیے آپ کا عمرہ پوشیدہ رہا۔ ترمذی(3) کا قول ہے: یہ حدیث حسن غریب ہے، محرش کی نبی کریم صلی اللہ علیہ وسلم سے اس کے علاوہ کوئی حدیث مروی نہیں۔","",{"fn":"(1) اسد الغابہ (۴۶۸۷) استیعاب (۲۵۵۹) تجرید (۲/۵۳)\n(2) الاکمال (۲/۲۴۸)\n(3) ابوداؤد (۱۹۹۶) ترمذی (۹۳۵) نسائی (۲۸۶۳) مسند احمد (۳/۳۲۶) بیہقی (۴/۳۵۷) طبرانی (۷۷۱، ۲۰/۷۷۰)"}],[6379,"§۷۷۵۱ ۔ محصن بن ابو قیس(1)\nابن اسلت انصاری، طبری نے ان کا ذکر کیا ہے، ابن سعد کا قول ہے: ہمیں واقدی نے بحوالہ محصن بن قیس بن ابو اسلت خبر دی۔","",{"fn":"(1) تجرید (۲/۵۴)"}],[6380,"§۷۷۵۲ ۔ محصن بن زرارہ(1)\nابو سعید نقاش نے موضوعات میں حدیث ابن عباس سے نقل کیا ہے، فرماتے ہیں: محصن بن زرارہ نے عرض کیا: یا رسول اللہ! میں سچا مومن ہوں۔۔۔۔ (الحدیث) یہ قصہ حارث بن مالک کے لیے معروف ہے، تعدد کا احتمال ہے، اسی طرح سیدنا معاذ بن جبل سے بھی مروی ہے۔","",{"fn":"(1) ابن ماجہ (۳۹۳۰) قرطبی (۵/۳۳۶) در المنثور (۱/۵۳۷)"}],[6381,"§۷۷۵۳ ۔ محصن بن وحوح(1)\nابن اسلت بن جشم بن وائل بن زید انصاری اوسی، ابن کلبی کا قول ہے: وہ اور ان کے بھائی حصین واقعہ قادسیہ میں غدیر پر قتل ہوئے، ان دونوں کا صحابی ہونا ثابت نہیں۔","",{"fn":"(1) اسد الغابہ (۴۶۹۰) تجرید (۲/۵۴)"}],[6382,"§۷۷۵۴ ۔ محلم بن جثامہ لیثی(1)\nصعب بن جثامہ کے بھائی ہیں، ان کے بھائی کی سوانح میں ان کا ذکر گزر چکا ہے، اور ان کا ذکر عبد اللہ بن ابو حدرد کی سوانح میں گزر چکا ہے، اور مکتیل لیثی کی سوانح میں آئے گا۔\nابن عبدالبر(2) کا قول ہے، بعض نے کہا: یہ وہی ہیں جنہوں نے عامر بن اضبط کو قتل کیا، بعض نے کہا: محلم نے قتل نہیں کیا۔\nوہ حمص میں اترے اور ابن زبیر کے زمانے میں یہاں وفات پا گئے۔ بعض کا قول ہے، یہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں وفات پا گئے اور دفن کئے گئے۔\nمیں کہتا ہوں: ابن سکن نے پہلے پر یقین کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۹۱) استیعاب (۲۵۵۲) تجرید (۲/۵۴)\n(2) استیعاب (۴/۲۳)"}],[6383,"§۷۷۵۵ ۔ معلم (دوسرے)\nپہلے والے میں ان کا ذکر ہے۔"],[6384,"§۷۷۵۶ ۔ معلم ابو سکینہ\nکنیتوں میں آئیں گے۔"],[6385,"§۷۷۵۷ ۔ محمد بن اسود(1)(3)\nابن خلف بن بیاضہ خزاعی، خلیفہ بن خیاط نے ان کا ذکر کیا ہے اور ان کی حدیث روایت کی ہے۔ \"ہر اونٹ کی کوہان پر شیطان ہوتا ہے۔\" بغوی(2) کا قول ہے: بعض نے صحابہ میں ان کا ذکر کیا ہے۔ ان کا صحابی ہونا معلوم نہیں، اور انہیں روایت کرنے کا شرف حاصل نہیں۔ اس سے ان کی مراد ابن ابو داؤد ہے۔\nابن مندہ، ابو نعیم نے بھی صحابہ میں ان کا ذکر کیا ہے۔ ابن فتحون نے استیعاب پر اپنے استدراک میں ان کا ذکر کیا ہے۔ بخاری، ابن حبان نے تابعین میں ان کا ذکر کیا ہے۔ لیکن بخاری رحمہ اللہ نے اپنی تاریخ میں ذکر کیا ہے جس کا تقاضا ہے کہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں بالغ ہوں پھر ابن مبارک کے طریق سے نقل کیا ہے، ہمیں ابو عمر مولی بنی امیہ نے بحوالہ محمد بن اسود بن خلف بن بیاضہ خزاعی بیان کیا، فرماتے ہیں: ہم سے عمرو بن العاص نے یرموک کے دن فرمایا پھر قصہ ذکر کیا۔ بخاری رحمہ اللہ کا قول ہے: بعض نے کہا: یرموک کا واقعہ ۱۵ ھ میں ہوا۔","",{"fn":"(1) اسد الغابہ (۴۶۹۶) تجرید (۲/۵۴)\n(2) معرفۃ الصحابہ (۲/۷۲)\n(3) تاریخ کبیر (۱/۲۹)"}],[6386,"§۷۷۵۸ ۔ محمد بن اسود(1)\nابن خلف بن عبد یغوث قرشی، بغوی کا قول ہے، بعض نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ میں نے انہیں ان کے والد سے روایت کرتے ہوئے پایا۔ بخاری رحمہ اللہ(2) کا قول ہے: ابن فلیح نے بحوالہ محمد بن اسود بن خلف انہوں نے نبی کریم صلی اللہ علیہ وسلم سے قریش کے بارے میں روایت کیا۔ گویا انہوں نے اس طرف اشارہ کیا ہے جسے باوردی نے اس طریق سے ان سے روایت کیا ہے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے نقل کیا ہے کہ وہ حضرت عثمان بن عبد اللہ کے پاس سامنے سے آتے ہوئے گزرے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ اس پر لعنت کرے، وہ قریش سے بغض رکھتا تھا\"۔ ان کے والد کا ذکر اور ان سے روایت گزر چکی ہے۔","",{"fn":"(1) اسد الغابہ (۴۶۹۸) استیعاب (۲۳۴۵) تجرید (۲/۵۴)\n(2) تاریخ کبیر (۱/۱۶)"}],[6387,"§۷۷۵۹ ۔ محمد بن انس\nابن فضالہ بن عبید بن یزید بن قیس بن صبیحہ بن اصرم بن... انصاری اوسی۔ بخاری(1) نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ فرماتے ہیں: مجھ سے یحییٰ بن موسیٰ نے بحوالہ اور لین بن محمد بن یونس بن محمد بن انس ظفری فرمایا، وہ اپنے دادا سے، وہ اپنے والد سے روایت کرتے ہیں، وہ فرماتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم مدینہ تشریف لائے اور میری عمر دو ہفتے تھی، مجھے آپ صلی اللہ علیہ وسلم کے پاس لایا گیا، آپ صلی اللہ علیہ وسلم نے میرے سر پر ہاتھ پھیرا اور مجھے اپنے ساتھ حج پر لے گئے اور میں دس برس کا تھا۔ فرماتے ہیں: آپ صلی اللہ علیہ وسلم نے میرے لیے برکت کی دعا کی، اور فرمایا: \"میرے نام پر اس کا نام رکھو اور میری کنیت پر اس کی کنیت نہ رکھو۔\"(1)\nیونس کا قول ہے: میرے والد کی اتنی عمر ہوئی یہاں تک کہ پھر دوبارہ جوان ہونے لگے، ان کے سرے نبی کریم صلی اللہ علیہ وسلم کے ہاتھ کی جگہ کے بال سفید نہیں ہوئے۔\nاسی طرح اسے مطین نے بحوالہ یعقوب بن محمد نقل کیا ہے، وہ زہری ہیں۔\nابن ابو حاتم نے اسے مختصر کیا ہے۔ فرماتے ہیں: محمد بن انس بن فضالہ، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم مدینہ تشریف لائے اور میں دو ہفتے کا تھا۔ اسے ابو علی بن سکن نے طویل دوسرے طریق سے بحوالہ یعقوب بن محمد اس سند سے نقل کیا ہے، لیکن فرمایا محمد بن فضالہ، محمد اپنے دادا کی طرف منسوب ہیں۔\nابن شاہین کا قول ہے: میں نے عبد اللہ بن سلیمان بن اشعث کو کہتے ہوئے سنا: محمد بن انس بن فضالہ، یہ وہ صحابی تھے جو اپنے اس مال سے نبی کریم صلی اللہ علیہ وسلم کو ہدیہ دیا کرتے تھے جو بنو ظفر میں تھا۔ اس کی طرف اشارہ ہے جو ابن ابو داؤد، ابن مندہ نے بطریق سفیان بن حمزہ بحوالہ عمرو بن ابی فردہ، اپنے گھر والوں میں سے ایک شیخ سے نقل کیا، فرماتے ہیں: انس بن فضالہ اُحد کے دن شہید\nہو گئے، نبی کریم صلی اللہ علیہ وسلم کے پاس محمد بن انس بن فضالہ لائے گئے آپ نے انہیں ایسی کھجور کا درخت بطور صدقہ دیا جو نہ بیچا جائے اور نہ ہبہ کیا جائے۔ ابن مندہ کا قول ہے: اس سند کے علاوہ ان سے مروی نہیں۔\nبخاری رحمہ اللہ نے بھی اس طرح نقل کیا ہے۔ ابو کامل نے فرمایا: بحوالہ یونس بن محمد بن انس بن فضالہ، انہوں نے اپنے والد سے، ان کے والد اور ان کے دادا صحابی ہیں، نبی کریم صلی اللہ علیہ وسلم کے پاس بنو ظفر میں آئے۔\nاسے بغوی رحمہ اللہ نے بحوالہ ابو کامل موصولاً نقل کیا ہے۔ وہ فضیل بن حسین، صلت بن مسعود ہیں، دونوں نے بحوالہ فضیل بن سلیمان اس سند سے روایت کیا ہے، اور یہ اضافہ کیا ہے: وہ ایک چٹان پر بیٹھ گئے، ان کے ساتھ مسعود اور معاذ تھے، رسول اللہ صلی اللہ علیہ وسلم نے ایک قرآن پڑھنے والے کو کہا، اس نے قرآن پڑھا، یہاں تک کہ جب اس آیت پر پہنچا(2) اس وقت کیا حال ہوگا جب ہم ہر امت سے ایک گواہی لائیں گے اور (اے محمد صلی اللہ علیہ وسلم) تمہیں ان پر گواہ بنا کر لائیں گے(2)۔ تو آپ صلی اللہ علیہ وسلم رونے لگے یہاں تک کہ آپ کی ریش مبارک تر ہوگئی۔ آپ صلی اللہ علیہ وسلم فرمانے لگے: \"اے رب! ان کی گواہی تو میں دے دوں گا، جنہیں میں نے دیکھا نہیں ان کی گواہی کیسے دوں گا؟\"\nاسی طرح ابن شاہین نے بحوالہ بغوی نقل کیا ہے۔ فرماتے ہیں: بغوی کا قول ہے: مجھے معلوم نہیں کہ محمد بن فضالہ نے اس حدیث کے علاوہ روایت کی ہو۔ بغوی، ابن شاہین، ابن قانع وغیرہ نے محمد بن انس بن فضالہ اور محمد بن فضالہ کے درمیان فرق کیا ہے۔ راجح یہ ہے کہ وہ دونوں ایک ہیں، لیکن ابن شاہین کا قول ہے: میں نے عبد اللہ بن سلیمان سے سنا، یعنی ابن ابو داؤد سے، انہوں نے کہا: محمد بن انس بن فضالہ فتح مکہ اور اس کے بعد غزوات میں شریک ہوئے۔ واللہ اعلم!","",{"fn":"(1) المعجم الکبیر (۱۹/۵۴۶) مجمع الزوائد (۷/۴) کنز العمال (۳۷۵۳۱) اسد الغابہ (۴/۵۹)\n(2) سورة النساء الآية (۴۱)"}],[6388,"§۷۷۶۰ ۔ محمد بن بدیل\nابن ورقاء خزاعی۔ ان کے والد کی سوانح میں ان کا نسب گزر چکا ہے۔ مقدمہ تاریخ میں ان کی حدیث نقل کی ہے، بطریق اصلح بن عبد اللہ کہ میں نے زید بن علی، عبد اللہ بن حسن، جعفر بن محمد سے سنا، ان میں سے ہر ایک نے اپنے والد اور اپنے گھر والوں سے ذکر کیا۔ دوسرے راویوں نے اصحاب رسول اللہ صلی اللہ علیہ وسلم میں جو سیدنا علی رضی اللہ عنہ کے ساتھ موجود تھے، ان میں نام لیا ہے۔ یہاں تک کہ فرمایا: عبد اللہ بن بدیل بن ورقاء، محمد بن بدیل بن ورقاء خزاعی ہیں دونوں صفین میں شہید ہوئے۔ وہ دونوں اہل یمن کی طرف رسول اللہ صلی اللہ علیہ وسلم کے قاصد تھے۔\nمیں کہتا ہوں: اصلح سے روایت کرنے والے غیاث بن ابراہیم ہیں، وہ ساقط راوی ہیں، حدیث وضع کرنے کی طرف منسوب ہیں۔"],[6389,"§۷۷۶۱ ۔ محمد بن بشر انصاری\nبعد والے میں آئیں گے۔"],[6390,"§۷۷۶۲ ۔ محمد بن بشیر انصاری(1)\nبخاری رحمہ اللہ(2) نے صحابہ میں ان کا ذکر کیا ہے۔ زخر بن حسن کے طریق سے بحوالہ خریم بن حارثہ بن لام طائی نقل کیا ہے، فرماتے ہیں: ہم نے حرہ کے دن لڑائی کی، سب سے پہلے مجھے شیما بنت بقیلہ ازدیہ ملی، تو میں اس سے چمٹ گیا اور کہنے لگا: یہ تو رسول اللہ صلی اللہ علیہ وسلم نے مجھے دے دی ہے، یہ ایسی ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سیدنا خالد نے مجھ سے اس بارے میں گواہی مانگی، میں اس پر گواہ لایا، وہ محمد بن سلمہ اور محمد بن بشیر انصاری ہیں۔ آپ نے اسے میرے سپرد کر دیا۔ اسے ابن مندہ نے اس طریق سے طویل حدیث کے ساتھ نقل کیا ہے۔ فرماتے ہیں: صرف اس سند سے معروف ہیں، زکریا بن یحییٰ بحوالہ زخر اس کی روایت میں متفرد ہیں۔\nمیں کہتا ہوں: یہ طویل روایت خریم بن اوس کی سوانح میں گزر چکی ہے۔ بغوی، ابن شاہین، ابن یونس اور ابن مندہ نے بطریق سلمہ بن شریح، بحوالہ یحییٰ بن محمد بن بشیر انصاری، انہوں نے اپنے والد سے نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ جب کسی بندے کو رسوا کرنا چاہتا ہے تو وہ اپنا مال عمارتیں بنانے میں صرف کرتا ہے\"۔(3)\nفرماتے ہیں: مجھے معلوم نہیں کہ محمد بن بشیر سے کسی اور نے روایت کی ہو۔ اسے ابن حبان نے اس طریق سے نقل کیا ہے، فرماتے ہیں: یہ مرسل ہے، ابن یونس کو ان کے صحابی ہونے میں شک ہے، فرماتے ہیں: بعض نے کہا: انہیں شرف صحابیت حاصل ہے۔\nاہل مصر میں ان کا ذکر ہے۔ وہ ان میں معروف نہیں۔ ان کی اہل مصر کے ہاں حدیث ہے، پھر حدیث کا ذکر کیا، محمد بن ربیع جیزی نے صحابہ میں ان کا ذکر کیا ہے جو مصر میں داخل ہوئے، ان کی حدیث مذکور نہیں۔ ابن عبدالبر نے ان کا ذکر کیا ہے۔ فرماتے ہیں: محمد بن بشیر انصاری، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی، ان سے ان کے بیٹے یحییٰ نے روایت کی، بعض کا خیال ہے کہ ان کی حدیث مرسل ہے، اسی طرح محمد بن بشیر نے ان کا ذکر کیا ہے، اور ابن ابو حاتم نے ان کی پیروی کی ہے۔ انہوں نے ان صحابہ میں محمد بن بشر عبدی کے ساتھ ان کا ذکر کیا ہے، جن کے والد کا نام بشر ہے، لیکن عظیم کے وزن پر ان کا ذکر کیا ہے۔ ان سب کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۰۴) استیعاب (۲۳۴۷) تجرید (۲/۵۵)\n(2) تاریخ کبیر (۱/۱۸) (۱/۴۵)\n(3) مجمع الزوائد (۴/۷۰) الکامل فی الضعفاء (۳/۱۰۷۱) الترغیب والترہیب (۳/۱۰۷) (۳/۲۱) معرفۃ الصحابہ (۲/۸۸) جمع الجوامع (۱/۳۷) جامع المسانید (۱۱/۱۱۷)"}],[6391,"§۷۷۶۳ ۔ محمد بن جابر(1)\nابن عراب بن عوف بن ذوالہ بن شبوہ بن ثوبان بن عبس بن غالب عکی، رسول اللہ صلی اللہ علیہ وسلم کے ساتھ وفد میں آئے، مصر کی فتح میں شریک تھے، انہوں نے اپنی کتابوں میں ان کا ذکر کیا ہے۔ ابن یونس نے ان کا ذکر کیا ہے۔ ابن مندہ نے ان سے مختصر روایت کی ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۰۶) تجرید (۲/۵۵)"}],[6392,"§۷۷۶۴ ۔ محمد بن جدہ(1)\nابن قیس انصاری، ابن قداح نے ان کا ذکر کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے ان کا نام محمد رکھا، فتح مکہ میں شریک تھے، ابن ابو داؤد نے ان سے روایت کی ہے، اسے ابن ابو داؤد نے ان سے روایت کیا ہے، اسے ابن شاہین نے نقل کیا ہے۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ محمد بن حبیب نے اپنی کتاب المحبر میں ذکر کیا ہے کہ وہ پہلے ہیں جن کا زمانہ اسلام میں انصار میں سے محمد نام رکھا گیا۔\nحاکم کی اکلیل میں ہے کہ معاذ بن جبل بن سعد بن علی بن اسد بن ساردہ میں سے تھے، وہ بنو سلمہ میں اس لئے شامل ہو گئے، کیونکہ فلاں بن محمد بن جد بن قیس (جو بنو سلمہ میں سے ہے) وہ ان کا ماں شریک بھائی تھا۔ یہ محمد بن جد بن قیس کے قدیم زمانے والے ہونے پر دلالت کرتا ہے تو قداح کے قول کی تائید ہوتی ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۰۷) تجرید (۲/۵۵)"}],[6393,"§۷۷۶۵ ۔ محمد بن حارثہ\nابن حبان نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، فرماتے ہیں: بعض کا قول ہے: انہیں شرف صحابیت حاصل ہے۔"],[6394,"§۷۷۶۶ ۔ محمد بن جعفر بن ابی طالب(1)\nابن ہاشم ہاشمی، عبد اللہ اور عون کے بھائی ہیں۔ ابن حبان، بغوی، ابن شاہین، ابن حبان وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔\nمحمد بن حبیب نے محبر میں فرمایا: یہ پہلے ہیں جن کا مہاجرین میں سے اسلام میں محمد نام رکھا گیا۔\nدار قطنی کا قول ہے: حبشہ کی سرزمین میں ولادت ہوئی، ابن مندہ اور ابن عبدالبر(2) کا قول ہے کہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں پیدا ہوئے۔ ابو عمر نے ذکر کیا ہے بحوالہ واقدی کہ ان کی کنیت ابو القاسم ہے، ان کا نکاح سیدنا عمر رضی اللہ عنہ کے بعد ام کلثوم بنت علی سے ہوا، فرماتے ہیں: تستر کے مقام پر شہید ہوئے، بعض نے کہا: وہ صفین میں سیدنا علی رضی اللہ عنہ کے ساتھ شریک ہونے تک زندہ رہے۔ دار قطنی نے کتاب الاخوۃ میں فرمایا: بعض نے کہا ہے وہ صفین میں شہید ہوئے۔ وہ اور عبید اللہ بن عمر بن خطاب آمنے سامنے تھے، ان میں سے ہر ایک نے دوسرے کو قتل کیا۔\nمرزبانی نے معجم الشعراء میں ذکر کیا ہے کہ وہ اپنے بھائی محمد بن ابو بکر کے ساتھ مصر میں تھے۔ جب قتل ہو گئے تو محمد بن جعفر چھپ گئے۔ تک اور غافق کے رہنے والے ایک شخص نے ان کا پتہ بتایا تو وہ فلسطین کی طرف بھاگ گئے، پھر شم سے اپنے ماموں کے خاندان کے ایک شخص کے پاس آئے، اس نے معاویہ کے پاس جانے سے منع کر دیا، انہوں نے اس بارے میں شعر کہا۔ یہ تحقیق واقدی کے قول کا رد کرتی ہے کہ وہ تستر میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۴۷۰۸) استیعاب (۲۳۵۰) تجرید (۲/۵۵)\n(2) استیعاب (۳/۴۲۳)"}],[6395,"§۷۷۶۷ ۔ محمد بن حاطب(1)\nابن حارث بن معمر بن حبیب بن وہب بن حذافہ بن مجح، ابو قاسم قرشی نجمی، بعض نے کہا: ابو ابراہیم یا ابو وہب، ان کی والدہ ام جمیل بنت مجلل عامریہ ہیں، بعض نے کہا: وہ حبشہ کی سرزمین میں پیدا ہوئے، ان کے والدین نے ہجرت کی، ان کے والد یہاں فوت ہو گئے۔ ان کی والدہ انہیں لے کر کشتی والوں کے ساتھ مدینہ آئی، عبد اللہ بن حارث بن محمد بن حاطب نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کی ہے۔ فرماتے ہیں: جب ہم ارض حبشہ سے آئے، میری والدہ مجھے لے کر نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: یا رسول اللہ! یہ آپ کا بھتیجا ہے، یہ آگ سے جل گیا ہے، اللہ تعالیٰ سے اس کے لئے دعا کیجئے(2)۔۔۔۔۔۔\nاسے عبد الرحمن بن عثمان بن محمد حاطبی نے بھی بحوالہ اپنے والد انہوں نے اپنے دادا سے روایت کیا ہے، اسے احمد، ابن ابو خیثمہ، بغوی نے نقل کیا ہے، اس میں ہے، ان کی والدہ نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! یہ محمد بن حاطب ہیں، یہ پہلے ہیں جنہوں نے آپ سے سنا، وہ کہنے لگیں: پھر تمہارے سر پر ہاتھ پھیرا، تمہارے منہ میں لعاب دہن ڈالا اور تمہارے لئے برکت کی دعا کی، ابن ابی خیثمہ نے بحوالہ محمد بن سلام تھی نقل کیا ہے، فرماتے ہیں: مجھ سے ہمارے بعض ساتھیوں نے نقل کیا کہ وہ پہلے ہیں اسلام میں جن کا نام محمد رکھا گیا۔\nحبشہ کی سرزمین میں پیدا ہوئے۔ اسماء بنت عمیس کے ہاں ان کے بیٹے عبد اللہ بن جعفر کے ساتھ ولادت ہوئی۔ ام محمد نے عبد اللہ بن جعفر کو دودھ پلایا، اس رشتے کو انہوں نے مرتے دم تک قائم رکھا، یہاں تک کہ دونوں وفات پا گئے۔\nابن شاہین کا قول ہے: میں نے بغوی کو فرماتے ہوئے سنا: وہ اسلام میں پہلے ہیں جن کا نام محمد رکھا گیا فرماتے ہیں: ان کی کنیت ابو قاسم تھی، ابن سعد نے یہ یقین کیا ہے کہ ان کی کنیت ابو ابراہیم تھی، پیشم کا قول ہے، عراق پر بشر کی حکومت میں وفات پا گئے، دوسرے راویوں کا قول ہے: ۷۴ ھ میں وفات پائی۔\nبطریق ابو مالک الجھی نقل کیا ہے، فرماتے ہیں: مجھ سے ابن حاطب نے فرمایا: حاطب اور جعفر نجاشی کی طرف گئے، میرے ہاں اس کشتی(3) میں بچہ پیدا ہوا۔\nمیں کہتا ہوں: جو مشہور ہے کہ وہ حبشہ کی سرزمین میں پیدا ہوئے۔ مجاز پر محمول ہے، کیونکہ وہ حبشہ پہنچنے سے پہلے پیدا ہوئے۔ محمد بن حاطب نے بحوالہ نبی کریم صلی اللہ علیہ وسلم روایت کیا ہے، انہوں نے اپنی والدہ اور سیدنا علی رضی اللہ عنہ سے روایت کیا۔\nان سے ان کی اولاد، ابراہیم، عمر، حارث، ابو لج، ابو مالک الجھی اور وہ ابن محمد ہیں، سماک بن حرب وغیرہ نے روایت کیا ہے۔ بعض کا قول ہے: ۸۶ ھ میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۴۷۱۰) استیعاب (۲۳۵۲) تجرید (۲/۵۵)\n(2) مسند احمد (۳/۴۱۸)، المعجم الکبیر (۹/۴۱۵)\n(3) المعجم الکبیر (۱۹/۲۴۱)، مجمع الزوائد (۶/۲۷)"}],[6396,"§۷۷۶۸ ۔ محمد بن حبیب نضری(1)\nبعض نے کہا: معری، وہ مشہور ہے، ابو عمر(2) کے ہاں میم کے پیش اور ضاء کے فتحہ کے ساتھ ہے۔\nابن مندہ کا قول ہے: شامیوں اور مصریوں میں معروف نہیں، صحابہ میں ان کا ذکر ہے۔ بغوی وغیرہ نے بطریق ولید بن سلمان۔ انہوں نے محمد بن حبیب سے نقل کیا ہے۔ فرماتے ہیں: ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور ہم نے کہا: یا رسول اللہ! لوگ کہہ رہے ہیں: ہجرت ختم ہو گئی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تک کفار سے جنگ رہے گی ہجرت ختم نہیں ہو سکتی\"۔(3)\nبغوی کا قول ہے: اسے کئی لوگوں نے بحوالہ عبد اللہ بن سعدی روایت کیا ہے کہ نسائی نے اسے بطریق ابو ادریس بحوالہ عبد اللہ بن سعدی نقل کیا ہے۔ اس میں محمد بن حبیب نہیں۔","",{"fn":"(1) اسد الغابہ (۴۷۱۱)، استیعاب (۲۳۵۳) تجرید (۲/۵۶)\n(2) الاستیعاب (۳/۴۲۵)\n(3) نسائی (۴۱۸۳)، بخاری (۵/۲۸)، معرفۃ الصحابہ (۲/۱۰۲)"}],[6397,"§۷۷۶۹ ۔ محمد بن ابی حذیفہ(1)\nابن عقبہ بن ربیعہ بن عبد شمس بن عبد مناف، عبشمی، ابو قاسم، حبشہ کی سرزمین میں پیدا ہوئے، ان کے والد سابقین اولین میں سے تھے، وہ اپنی کنیت سے مشہور ہیں، ان کے نام میں اختلاف ہے۔ جیسا کہ کنیتوں میں آئے گا، ان کی والدہ سہلہ بنت سہیل بن عمرو عامریہ ہیں۔\nابن لہیعہ نے بحوالہ عروہ فرمایا: محمد بن ابی حذیفہ حبشہ کی سرزمین میں پیدا ہوئے، اسی طرح ابن اسحاق، واقدی، ابن سعد کا قول ہے، واقدی نے ابو قاسم کنیت رکھنے والوں میں ان کا ذکر کیا ہے، ان کا نام محمد ہے، صحابہ میں سے ہیں۔(2)\nان کے والد ابو حذیفہ یمامہ میں شہید ہوئے، سیدنا عثمان رضی اللہ عنہ نے اس محمد کو اپنے پاس رکھ لیا اور ان کی پرورش کی، جب وہ بڑے ہوئے اور عثمان رضی اللہ عنہ خلیفہ بنے تو انہوں نے ان سے مصر جانے کی اجازت طلب کی، انہوں نے اجازت دے دی، وہ لوگوں میں سب سے زیادہ سیدنا عثمان رضی اللہ عنہ کے خلاف سخت ثابت ہوئے۔ ابو عمر کندی نے مصر کے امراء میں ذکر کیا ہے کہ عبد اللہ بن سعد سیدنا عثمان رضی اللہ عنہ کی طرف سے مصر کے امیر تھے۔ جب لوگ سیدنا عثمان رضی اللہ عنہ کے خلاف جمع ہونے لگے تو آپ سیدنا عثمان رضی اللہ عنہ کی طرف روانہ ہوئے، شہروں کے گورنروں کو طلب کیا تو وہ ان کے پاس پہنچ گئے، یہ رجب ۳۵ ھ کا واقعہ ہے۔ اور عقبہ بن عامر کو اپنا نائب مقرر کر گئے، ابن مالک کے نسخے میں ہے کہ محمد بن ابی حذیفہ نے عقبہ پر حملہ کر کے انہیں مصر سے اسی سال کے شوال میں نکال دیا اور لوگوں کو سیدنا عثمان رضی اللہ عنہ سے دستبردار ہونے کی دعوت دینے لگے۔ شہروں میں آگ بھڑکا دی اور لوگوں کو سیدنا عثمان رضی اللہ عنہ کے خلاف کر دیا، بطریق لیث عبد الکریم بن حارث حضرمی سے روایت کی ہے کہ ابن ابی حذیفہ امہات المؤمنین کی زبانی سیدنا عثمان رضی اللہ عنہ کے خلاف طعن آمیز خطوط لکھا کرتا تھا۔ اور قافلوں کو پکڑ کر روک لیتا پھر ان مردوں کو گرفتار کر لیتا جنہیں وہ یہ دے کر بھیجتا، پھر انہیں گھروں کی چھتوں پر دھوپ میں ڈال دیتا، وہ سورج کی طرف اپنا چہرہ کر لیتے تاکہ مسافر کی طرح اشارہ کریں۔ پھر انہیں مدینہ کے راستے جانے کا حکم دیتا، پھر وہ لوگ قاصد بھیجتے، تاکہ ان کے آنے کی خبر لائیں، تو یہ لوگوں کو ان سے ملنے کا حکم دیتا، جب لوگ ان سے ملتے، پوچھتے کیا بات ہے، تو مقامی لوگ کہتے ہمیں کچھ پتہ نہیں جو کچھ ہے خطوط میں ہے، تو ابن ابی حذیفہ لوگوں کے ساتھ مل کر ان سے ملاقات کرتا، قاصد ان سے کہتے، آپ لوگ مسجد میں چلیں، پھر امہات المؤمنین کی طرف سے ان کے سامنے خطوط پڑھے جاتے، جس میں لکھا ہوتا، اے اہل اسلام! ہم تم لوگوں سے فلاں فلاں بات کی شکایت کرتی ہیں، جس میں سیدنا عثمان رضی اللہ عنہ پر طعن و تشنیع ہوتی تو مسجد کا بھرا ہوا مجمع چیخنے چلانے اور دعا میں مصروف ہو جاتا، پھر انہوں نے بطریق ابن لہیعہ یزید بن ابی حبیب سے روایت کی ہے کہ مصر والوں نے محمد بن ابی حذیفہ کے ہاتھ پر امارت کی بیعت کر لی، صرف تھوڑے لوگوں نے بیعت نہیں کی جس میں معاویہ بن خدیج، بسر بن ارطاۃ شامل ہیں، ادھر سے عبد اللہ بن سعد آ گئے جب وہ مقام قلزم پر پہنچے تو وہاں ابن ابی حذیفہ کا لشکر پایا ان لوگوں نے انہیں شہر میں داخل ہونے سے منع کر دیا، وہ عسقلان لوٹ گئے پھر ابن ابی حذیفہ نے ان لوگوں کو تیار کیا جنہوں نے سیدنا عثمان رضی اللہ عنہ کے خلاف شورش کی تھی اور آپ کا محاصرہ کیا تھا یہاں تک کہ آپ کو شہید کر دیا، جب یہ بات ان لوگوں کو معلوم ہوئی جو ابن ابی حذیفہ کی بیعت سے باز رہے تھے، سب نے اکٹھے ہو کر سیدنا عثمان رضی اللہ عنہ کے خون کے مطالبے کی بیعت کر لی، جنہیں لے کر معاویہ بن خدیج صعید مصر تک پہنچے تو ابن ابی حذیفہ نے ان کی طرف دوسرا لشکر بھیج دیا، آپس میں جنگ ہوئی، لشکر کا قائد مارا گیا، پھر جب سیدنا امیر معاویہ نے صفین جانا چاہا تو آپ مصر کی طرف روانہ ہو گئے، آپ نے مناسب سمجھا کہ اپنے پیچھے اہل مصر کو ابن ابی حذیفہ کے ساتھ نہ چھوڑیں۔ آپ ان لوگوں کی طرف بھاری لشکر لے کر روانہ ہوئے، ان کے مقابلے میں ابن ابی حذیفہ مصریوں کو لے کر روانہ ہوا، لوگوں نے اسے فسطاط میں داخل ہونے سے منع کیا، آپ نے ان کی طرف پیغام بھیجا، ہم کسی سے جنگ کرنا نہیں چاہتے، ہمیں تو قاتلین عثمان کی تلاش ہے، آخر یہ بات ٹھہری کہ مصر سے رخصت ہوں۔ چنانچہ ابن ابی حذیفہ نے مصر پر حکم بن صلت بن مخرمہ بن مطلب بن عبد مناف کو اپنا نائب بنایا اور ایک جماعت کے ساتھ روانہ ہو گئے، جن میں عبد الرحمن بن عدیس، کنانہ بن بشر، ابو ثمر بن ابرہہ بن صباح تھے۔ جب یہ لوگ اسے لے کر پہنچے تو امیر معاویہ کے لشکر نے ان سے غداری کر لی اور ان سب کو گرفتار کر کے قتل کر دیا۔\nحاکم کا بیان ہے کہ جب ابن ابی حذیفہ نے مصر پر قبضہ کر لیا، امیر معاویہ صفین جانا چاہتے تھے تو آپ نے پہلے مصر کے معاملے کو نمٹایا۔ عریش مقام پر محمد بن حذیفہ آڑے آیا، یہاں تک کہ دونوں نے صلح کر لی، امیر معاویہ نے اس سے کچھ لوگوں کو طلب کیا، جو ان کے ماتحت رہن رہیں گے تاکہ جب صفین جائیں تو ان کی طرف سے مطمئن رہیں، چنانچہ محمد نے بطور رہن تین آدمی باہر نکالے جن میں وہ خود بھی شامل تھا، وہاں ان لوگوں کا گھیراؤ کر لیا گیا اور قید میں ڈال دیا گیا۔\nحاکم لکھتے ہیں: امیر معاویہ نے محمد بن ابی حذیفہ کو چکمہ دیا یہاں تک کہ وہ عریش تک تین آدمیوں کے ساتھ آ گیا، آپ نے ان کا محاصرہ کیا اور اس کے خلاف تحقیق نصب کی، یہاں تک کہ وہ صلح پر مجبور ہو گیا۔ پھر قید ہو کر قتل کیا گیا۔ ابن عائذ کی روایت ہے کہ امیر معاویہ نے لوگوں کو صفین میں تقسیم کر دیا، اور ابن ابی حذیفہ اور اس کے ساتھیوں کو دمشق کی جیل میں اور ابن حدیس میں اور باقی لوگوں کو بعلبک کی جیل میں بند کر دیا۔ یعقوب بن سفیان اپنی تعریف میں لکھتے ہیں کہ عبد الملک سلیحی فرماتے ہیں: میں سیدنا عقبہ بن عامر کے پاس منبر کے قریب تھا، اتنے میں ابن ابی حذیفہ آیا، لوگوں سے خطاب کرنے لگا، وہ قرآن کا قاری تھا۔ کوئی صورت اس نے پڑھی، عقبہ کہنے لگے: اللہ کے رسول نے فرمایا:\n\"کچھ لوگ قرآن پڑھیں گے لیکن قرآن ان کی ہنسی سے آگے نہیں جائے گا\"۔(3)\nابن ابی حذیفہ بن کر کہنے لگا: اگر تم یہ کہتے ہو تو تم انہی لوگوں سے ہو۔ بغوی وغیرہ کی روایت ہے، صحابہ میں سے کچھ لوگ آپس میں یہ حدیث بیان کر رہے تھے: \"جبل و خلیل اور نظر ان کے مقام پر میرے صحابہ یا میری امت کے کچھ لوگ قتل ہوں گے\"۔(4) تو وہ لوگ یہی تھے جو محمد بن ابی حذیفہ کے ساتھ وہاں مارے گئے۔\nیہی روایت ابو عمر الکندی نے دوسری سند سے نقل کی ہے کہ محمد بن ابی حذیفہ نے کہا: یہ وہی رات ہے جس میں عثمان (رضی اللہ عنہ) قتل ہوئے تھے، اگر قصاص عثمان ہے تو قاتل کل قتل ہو جائے گا، چنانچہ وہ کل قتل ہو گیا۔ خلیفہ اپنی تاریخ میں لکھتے ہیں: جب سیدنا علی رضی اللہ عنہ خلیفہ بنے تو محمد بن ابی حذیفہ کو مصر کی گورنری پر قائم رکھا، پھر محمد بن ابی بکر(5) کو مقرر کر دیا۔ اس کی وفات میں اختلاف ہے۔ بقول ابن قتیبہ، رشید بن مولا معاویہ کے ہاتھوں قتل ہوا۔ ابن کلبی لکھتے ہیں: مالک بن ہبیرہ سکونی نے اسے قتل کیا۔","",{"fn":"(1) اسد الغابہ (۴۷۱۳)، الاستيعاب (۲۳۵۴) تجرید (۲/۵۶)\n(2) تاریخ طبری (۵/۱۰۵)، مختصر تاریخ دمشق (۲۲/۸۵) (۸۶) طبقات الكبرى (۴/۸۶) (۴/۸۴)\n(3) مجمع الزوائد (۱۰/۴۲۷) کنز العمال (۳۱۶۰۶)\n(4) کنز العمال (۳۱۱۶۹) مختصر تاریخ دمشق (۲۲/۸۷)\n(5) معرفۃ الصحابہ (۲/۹۸)"}],[6398,"§۷۷۷۰ ۔ محمد بن حزم انصاری(1)\nبغوی نے ان کا ذکر کیا ہے اور فرمایا: بخاری رحمہ اللہ نے نبی کریم صلی اللہ علیہ وسلم سے روایت کرنے والوں میں ان کا ذکر کیا ہے، معروف نہیں، اسی طرح ابن شاہین کا قول ہے، اس پر اضافہ نہیں کیا۔\nابو قتیبہ کا قول ہے: ابو عباس ہروی نے صحابہ میں سے محمد نام رکھنے والوں میں ان کا ذکر کیا ہے، اور ان کی نبی کریم صلی اللہ علیہ وسلم سے روایت کا ذکر کیا، فرماتے ہیں: \"تا کہ میری امت قیامت کے روز ستر امتوں کی تکمیل کرے ہم ان میں آخری اور بہتر ہیں\"۔(2)\nابن مندہ کا قول ہے: محمد بن حزم تابعی ہیں، ان سے قتادہ نے روایت کی، معروف نہیں، ابن اثیر(3) کا قول ہے: جو معروف نہیں محمد بن عمرو بن حزم ہیں، ان کا ذکر آ رہا ہے۔ شاید وہ اپنے دادا کی طرف منسوب ہیں۔","",{"fn":"(1) اسد الغابہ (۴۷۱۴) تجرید (۲/۵۶)\n(2) معرفۃ الصحابہ (۲/۱۳۴) جمع الجوامع (۱/۸۵۷)\n(3) اسد الغابہ (۴/۵۹)"}],[6399,"§۷۷۷۱ ۔ محمد بن حطاب(1)\nابن حارث بن معمری، محمد بن حطاب کا چچا زاد ہے۔ قریب میں ان کا نسب گزر چکا ہے۔ ابن عبد البر(2) کا قول ہے: وہ بھی حبشہ کی سرزمین میں پیدا ہوئے، وہ محمد بن حاطب سے عمر میں بڑے ہیں۔ جیسا کہ قول ہے۔ پہلے گزر چکا ہے کہ محمد بن حاطب پہلے ہیں جن کا اسلام میں مہاجرین میں محمد نام رکھا گیا، وہ ان سے بڑے ہیں۔\nاحمد نے بطریق عثمان بن محمد، بحوالہ محمد بن حطاب نقل کیا ہے کہ جب وہ نبی کریم صلی اللہ علیہ وسلم کے پاس اپنے بیٹے کو لے کر آئیں، تو کہنے لگیں: یہ محمد بن حطاب ہیں، یہ پہلے ہیں جن کا نام آپ کے نام پر رکھا گیا۔ محمد بن حاطب کی سوانح میں گزر چکا ہے۔\nابو الفرج اصبہانی نے دو طریق سے بحوالہ عبد الملک بن عمیر نقل کیا، فرماتے ہیں: سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس جوڑے لائے گئے۔ آپ نے فرمایا: میرے پاس محمد نامی لوگوں کو لے آؤ، تو محمد بن ابی بکر، محمد بن جعفر، محمد بن طلحہ، محمد بن عمرو بن حزم، محمد بن حاطب، ان کے چچا زاد محمد بن حطاب آئے، ان سب کا نام نبی کریم صلی اللہ علیہ وسلم نے محمد رکھا تھا، پھر ان کا قصہ ذکر کیا، اگر یہ روایت محفوظ ہے تو مجاز پر محمول ہے، یعنی نبی کریم صلی اللہ علیہ وسلم نے انہیں اسی پر برقرار رکھا۔","",{"fn":"(1) اسد الغابہ (۴۷۱۵) استیعاب (۲۳۵۵) تجرید (۲/۵۶)\n(2) استیعاب (۳/۴۲)"}],[6400,"§۷۷۷۲ ۔ محمد بن خلیفہ(1)\nبن عامر۔ ابن قداح کا قول ہے: فتح میں شریک تھے۔ ان کا نام عبد مناۃ تھا، نبی کریم صلی اللہ علیہ وسلم نے ان کا نام محمد رکھا۔ اسے ابن شاہین نے بحوالہ ابن ابو داؤد ان سے نقل کیا ہے۔","",{"fn":"(1) تجرید (۲/۵۶)"}],[6401,"§۷۷۷۳ ۔ محمد بن ابو درہ انصاری(1)\nابن قداح کا قول ہے، نبی کریم صلی اللہ علیہ وسلم کے صحابی ہیں، اور فتح مکہ میں شریک تھے، ابن شاہین نے ان کا ذکر بھی بحوالہ ابو داؤد ان سے نقل کیا ہے۔","",{"fn":"(1) تجرید (۲/۵۷)"}],[6402,"§۷۷۷۴ ۔ محمد بن رکانہ(1)\nابن عبد یزید مطلبی قرشی، آخری قسم میں ان کا ذکر آئے گا۔","",{"fn":"(1) اسد الغابہ (۴۷۱۵) استیعاب (۲۳۵۸)"}],[6403,"§۷۷۷۵ ۔ محمد بن زید\nابن مندہ کا قول ہے: اسے ابو حاتم رازی نے وحدان میں نقل کیا ہے، اور وہ وہم ہے۔ پھر ان کے طریق سے ان کی سند سے جسے وہ محمد بن عبد الرحمن بن ابی لیلیٰ تک لے گئے ہیں۔ بحوالہ عطاء، انہوں نے محمد بن زید سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کو شکار کا گوشت پیش کیا گیا، آپ صلی اللہ علیہ وسلم نے اسے کھانے سے انکار کیا۔(1) فرماتے ہیں: اس روایت کو قیس بن سعد نے بحوالہ ابن عباس روایت کیا ہے۔\nمیں کہتا ہوں: اسے ابو داؤد، نسائی نے بطریق حماد بن سلمہ، بحوالہ زید بن اسلم نقل کیا ہے۔ طبرانی نے سب سے زیادہ اس کے طرق کی تخریج کی ہے۔\nابن ابی حاتم کا قول ہے: بحوالہ اپنے والد، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، پھر یہ حدیث ذکر کی۔ ان سے عطاء بن ابو رباح نے روایت کی، اسی طرح ابن عبد البر(2) نے نقل کیا ہے۔ ایک لمحہ اتحال کی بنا پر ہے کہ واقعہ متعدد ہو، جس کا قریب یہ ہے کہ محمد بن عبد الرحمن کی غلطیاں بہت زیادہ ہیں۔","",{"fn":"(1) مسلم (۲۸۴۲) ابوداؤد (۱۸۵۰) نسائی (۲۸۲۱) مسند احمد (۴/۳۳۷) معرفۃ الصحابہ (۲/۱۰۷) الجرح والتعدیل (۷/۲۵۵) اسد الغابہ (۴/۶۷)\n(2) استیعاب (۳/۴۲۷)"}],[6404,"§۷۷۷۶ ۔ محمد بن ابو سفیان(1)\nداربین کی طرف نبی کریم صلی اللہ علیہ وسلم کے خط میں ان کا ذکر ہے۔ ابن مندہ نے سعید بن زیاد کی روایت سے بحوالہ ان کے آباء، انہوں نے ابو ہند داری سے ان کا اسلام لانے کا قصہ ذکر کیا ہے۔ نبی کریم صلی اللہ علیہ وسلم سے جس تحریر کا مطالبہ کیا تھا آپ نے فرمایا کہ وہ لکھ لو، اس میں ابو بکر، عمر، عثمان، علی، محمد بن ابی سفیان کی گواہی کا ذکر کیا۔ الہیثم(2) نے ان کا تعاقب کیا ہے کہ اس روایت میں صحیح یہ ہے کہ وہ معاویہ بن ابی سفیان ہیں، محمد نہیں۔\nمیں کہتا ہوں: اس کا بھی احتمال ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۲۸) تجرید (۲/۵۸)\n(2) معرفۃ الصحابہ (۲/۱۱۴)"}],[6405,"§۷۷۷۷ ۔ محمد بن ابی سلمہ(1)\nابن عبد اسد مخزومی۔ ابن حبان کا قول ہے، انہیں شرف صحابیت حاصل ہے۔ بغوی کا قول ہے: جن لوگوں نے صحابہ کے بارے میں تالیفات کی ہیں، انہوں نے ان کا ذکر کیا ہے۔ اس کا انکار کیا ہے، اسے ابن شاہین نے بغوی سے روایت کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۲۹) تجرید (۲/۵۸)"}],[6406,"§۷۷۷۸ ۔ محمد بن سلیمان\nابن رفاعہ بن خلیفہ بن ابی کعب، ابن قداح کا قول ہے، احد اور عراق کی فتح میں شریک تھے، صفین کے دن شہید ہوئے، ابن شاہین نے بحوالہ ابن قداح ان کا ذکر کیا ہے۔"],[6407,"§۷۷۷۹ ۔ محمد بن صفوان انصاری(1)\nبنو مالک بن اوس سے ہیں، عسکری نے یہ ذکر کیا ہے، بعض کا قول ہے: اس میں ہے صفوان بن محمد، پہلا قول زیادہ صحیح ہے۔\nاحمد اور اصحاب سنن نے اسے نقل کیا ہے۔ ابن حبان اور حاکم نے اپنی صحیح میں اسے بطریق داؤد بن ابی ہند، بحوالہ شعثی ان سے نقل کیا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس دو خرگوش لے کر آئے جو انہوں نے کائی سے شکار کے ساتھ ذبح کئے تھے۔(2)\nاسے علی بن عبد العزیز نے اپنی مسند میں حماد بن سلمہ کی روایت سے بحوالہ داؤد نقل کیا ہے۔ فرماتے ہیں: بحوالہ محمد بن صفوان یقین سے اسی طرح اسے بغوی نے شعبہ کے طریق سے اور عبدہ بن سلیمان کے طریق سے نقل کیا ہے۔ ابن شاہین نے بحوالہ بغوی روایت کیا ہے کہ وہ راجح ہے۔ فرماتے ہیں: مجھے معلوم نہیں کہ محمد بن صفوان کی ان کے علاوہ کسی سے حدیث مروی ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۲۴) استیعاب (۲۳۵۹) تجرید (۲/۵۸)\n(2) ابوداؤد (۲۸۲۲) نسائی (۲۴۱۳) ابن ماجہ (۳۲۴۴) احمد (۴/۴۷)"}],[6408,"§۷۷۸۰ ۔ محمد بن صیفی بن امیہ(1)\nابن عابد بن عبد اللہ بن عمر بن مخزوم، ابن قداح کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ ابن شاہین نے بحوالہ ابو داؤد ان کا ذکر کیا ہے۔ ابو عمر(2) کا قول ہے: انہیں دیدار حاصل نہیں اور ان کے صحابی ہونے میں تردد ہے، وہ سیدہ خدیجہ بنت خویلد رضی اللہ عنہا کے پوتے ہیں، ان کی والدہ ہند بنت عتیق بن عامر بن عبد اللہ بن عمر بن مخزوم ہیں، ان کی والدہ خدیجہ ہیں۔\nمیں کہتا ہوں: زبیر بن بکار کی روایت سے ابن قداح کے قول کو تقویت ملتی ہے کیونکہ جب انہوں نے ان کے والد کا ذکر کیا تو کہا: ان کا بیٹا رافعہ ہے، جس پر ان کی کنیت ہے۔ صیفی بن امیہ بدر کے دن قتل ہوا، جس کا باپ بدر میں قتل ہوا اور یہ ہجرہ کے دوسرے برس تھا۔ تو اس نے عہد نبوی میں آٹھ سال یا اس سے زیادہ پائے ہوں گے، اور محمد نام اسی کا رکھا جا سکتا ہے جس کے والد اور والدہ اسلام لا چکے ہوں، ہو سکتا ہے کہ وہ اپنے والد کے قتل ہونے کے بعد پیدا ہوئے ہوں اور ان کی والدہ اسلام لے آئی ہوں اور ان کا نام محمد رکھا ہو یا ان کی والدہ ان کا نام رکھنے سے پہلے فوت ہو گئی ہوں اور ان کے کسی گھر والے نے ان کا نام محمد رکھا ہو۔","",{"fn":"(1) اسد الغابہ (۴۷۳۵) استیعاب (۲۳۶۰) تجرید (۲/۵۹)\n(2) استیعاب (۳/۴۲۷)"}],[6409,"§۷۷۸۱ ۔ محمد بن صیفی بن سہل(1)\nابن حارث خطی انصاری۔ ہشیم نے اپنی روایت میں، بحوالہ شعثی ان کا نسب بیان کیا ہے، ان سے یوم عاشوراء(2) کے روزے کے بارے میں مرفوع حدیث مروی ہے، بعض کا قول ہے وہ کوفہ میں اترے۔ ان کی حدیث احمد، نسائی، ابن ماجہ نے، ابن خزیمہ اور حاکم نے اپنی صحیح میں بطریق حسین، بحوالہ شعثی انہوں نے محمد بن صیفی سے یوم عاشوراء کے روزے کے بارے میں نقل کیا ہے، اس کی سند صحیح ہے۔ بغوی نے انعش وغیرہ کے طریق سے، بحوالہ محمد بن صیفی نقل کیا ہے۔ فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس دو خرگوش لے کر آیا۔۔۔۔۔ (الحدیث)\nبغوی کا قول ہے: یہ وہم ہے، صحیح محمد بن صفوان ہیں یعنی جیسا کہ پہلے والے حالات میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۳۶) استیعاب (۲۳۶۱) تجرید (۲/۵۹)\n(2) مسند احمد (۴/۳۸۸)"}],[6410,"§۷۷۸۲ ۔ محمد بن ضمرہ(1)\nابن اسود بن عباد بن غنم بن سواد، ابن قداح نے ذکر کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان کا نام محمد رکھا، فتح مکہ(2) کے موقع پر حاضر تھے، اسے ابن شاہین نے بحوالہ ابو داؤد انہوں نے ان کے حوالے سے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۳۷) تجرید (۲/۵۹)\n(2) اسد الغابہ (۲/۷۲)"}],[6411,"§۷۷۸۳ ۔ محمد بن طلحہ\nابن عبد اللہ قرشی تیمی، ان کے والد کے جو عشرہ مبشرہ میں سے ہیں، سوانح میں ان کا نسب گزر چکا ہے، بخاری رحمہ اللہ نے صحابہ میں ان کا ذکر کیا ہے۔ وہ کہتے ہیں: نبی کریم صلی اللہ علیہ وسلم کے زمانے میں ان کی ولادت ہوئی۔ بخاری،(1) بغوی، طبرانی وغیرہ نے بلال و زدان کے طریق سے، بحوالہ عبد الرحمن بن ابی لیلیٰ نقل کیا ہے۔ فرماتے ہیں: سیدنا عمر رضی اللہ عنہ نے عبد الحمید یعنی زید بن خطاب کے بیٹے کو دیکھا، ان کا نام محمد تھا، ایک شخص ان سے کہہ رہا تھا: اے محمد! اللہ تیرے ساتھ تیرا ایسا کرے، تو ان سے سیدنا عمر رضی اللہ عنہ نے کہا: میں نہ دیکھوں کہ محمد نام کو تمہاری وجہ سے گالی دی جائے اللہ کی قسم! جب تک میں زندہ ہوں تمہیں محمد نام سے نہ پکارا جائے، پھر ان کا نام عبد الرحمن رکھ دیا، اور بنو ظہیر کی طرف ان کا نام بدلنے کے لیے پیغام بھیجا، وہ سات تھے، ان کا سردار اور سب سے بڑے کا نام محمد تھا، آپ صلی اللہ علیہ وسلم سے ان محمد نے کہا: اے امیر المؤمنین! میں آپ کو اللہ کی قسم دیتا ہوں، اللہ کی قسم! محمد صلی اللہ علیہ وسلم نے میرا نام محمد رکھا، سیدنا عمر رضی اللہ عنہ نے فرمایا: تم لوگ اٹھ جاؤ، جو نام رسول اللہ صلی اللہ علیہ وسلم نے رکھ دیا، اسے تبدیل کرنے کی ضرورت نہیں ہے۔(2)\nابن مندہ نے یوسف بن ابراہیم کی کے طریق سے، بحوالہ اپنے والد ابراہیم بن محمد روایت کیا ہے کہ سیدنا طلحہ رضی اللہ عنہ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے میرے بیٹے کا نام محمد رکھا اور اس کی کنیت ابو القاسم رکھی۔\nزبیر بن بکار نے بطریق راشد بن حفص زبیری نقل کیا ہے، فرماتے ہیں کہ میں نے صحابہ رضی اللہ عنہم کے چار بیٹوں کو دیکھا ان میں سے ہر ایک کا نام محمد اور کنیت ابو القاسم تھی، وہ یہ ہیں: ابن ابی بکر، ابن علی، ابن سعد اور ابن طلحہ۔\nابن قانع، ابن مکن، اور ابن شاہین نے بطریق محمد بن عبد الرحمن بن ابی لیلیٰ، بحوالہ ابراہیم بن محمد بن طلحہ، انہوں نے محمد بن طلحہ کے رضاعی والد سے نقل کیا ہے، فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس محمد بن طلحہ کو لے کر آیا جس وقت ان کی ولادت ہوئی، تاکہ ان کو گھٹی ڈالیں اور ان کے لیے دعا کریں۔ آپ صلی اللہ علیہ وسلم بچوں کے ساتھ اسی طرح کرتے تھے۔ آپ صلی اللہ علیہ وسلم نے سیدہ عائشہ رضی اللہ عنہا سے پوچھا: \"یہ کون ہے؟\" انہوں نے عرض کیا: محمد بن طلحہ ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ میرا نام ہے، یہ ابو القاسم ہیں\"۔\nمحمد بن زید بن مہاجر کے طریق سے، بحوالہ ابراہیم بن محمد بن طلحہ مروی ہے، فرماتے ہیں: جب حمزہ بنت جحش کے ہاں محمد بن طلحہ کی ولادت ہوئی تو وہ انہیں لے کر نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں، آپ صلی اللہ علیہ وسلم نے ان کا نام محمد اور کنیت ابو سلیمان رکھی۔ اسے ابن مندہ نے دوسرے طریق سے، بحوالہ ابراہیم بن محمد، انہوں نے طلحہ سے، انہوں نے اپنے والد سے نقل کیا ہے کہ ان کی جب ولادت ہوئی تو ان کے والد انہیں نبی کریم صلی اللہ علیہ وسلم کے پاس لے گئے، آپ صلی اللہ علیہ وسلم نے ان کا نام محمد رکھا اور فرمایا: \"یہ ابو سلیمان ہیں میں اپنے نام اور کنیت کو جمع نہیں کرتا\"۔(3)\nابن مندہ کا قول ہے: پہلا قول مشہور ہے، محمد بہت عبادت گزار تھے، انہیں سجاد کہا جاتا تھا۔\nبغوی نے حسین بن عبد الرحمن کے طریق سے، بحوالہ ابو جعیلہ طبری نقل کیا ہے، فرماتے ہیں: جب جمل کا دن ہوا تو محمد بن طلحہ نے سیدہ عائشہ رضی اللہ عنہا سے کہا: انہوں نے کہا: حضرت آدم علیہ السلام کے دو بیٹوں میں سے بہترین کی طرح ہو جاؤ، فرماتے ہیں: انہوں نے اپنی تلوار نیام میں رکھ لی، وہ اسے سوتے ہوئے تھے، پھر چلے گئے یہاں تک کہ شہید کر دیئے گئے۔ بغوی کا قول ہے: بعض کا قول ہے، انہیں شریح بن اوفیٰ نے قتل کیا۔ سیدنا علی رضی اللہ عنہ ان کے پاس سے گزرے۔ فرمایا: یہ سجاد ہیں، انہیں اپنے والد کے ساتھ حسن سلوک کرنے نے قتل کیا۔ یہ ۳۶ھ کا واقعہ ہے۔ ان کے قاتل کے نام میں اختلاف ہے۔ امام بخاری رحمہ اللہ کا بیان ہے، سورہ غافر کی تفسیر میں جو روایت تعلیقاً ذکر کی ہے اس سے بغوی کے اس قول کی تائید ہوتی ہے کہ ان کے قاتل کا نام شریح بن ابی اوفیٰ ہے: \"وہ مجھے سورہ حم پڑھ کر سناتا ہے جب کہ نیزے بلند ہو چکے ہیں جنگ میں قدم رکھنے سے پہلے کیوں نہیں تم پڑھاتی\"۔\nیہ ان اشعار میں سے ہے جن کا مطلع شعر ہے: طہ\n\"وہ پراگندہ بالوں والا جو اپنے رب کی آیات کو قائم رکھنے والا ہے نظر جسے دیکھتی ہے، وہ بہت کم تکلیف دینے والا مسلمان ہے\"۔\nابن عبد البر(4) کا قول ہے، بعض نے کہا: ان کے قاتل کا نام کعب بن مدیح ہے، یا شداد بن معاویہ یا عصام بن منقعر یا اشتر یا عبد اللہ بن مکبر ہے بعض کا قول ہے کہ کوئی اور ہے، میں نے فتح الباری میں یہ قول بحوالہ اس کے قاتل کے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۳۸) استیعاب (۲۳۶۲) تجرید (۲/۵۹) فتح الباری (۸/۵۵۴)\n(2) مسند احمد (۴/۲۱۶) المعجم الكبير (۱۹/۲۴۲) تاریخ کبیر (۱/۱۶)\n(3) معرفۃ الصحابہ (۲/۵۸) اسد الغابہ (۴/۷۳)\n(4) استیعاب (۳/۴۲۸)"}],[6412,"§۷۷۸۴ ۔ محمد بن عاصم(1)\nابن ثابت بن ابو اقلح انصاری، ابن مندہ کا قول ہے: حدیث میں ان کا ذکر ہے ان کے والد مشہور صحابی ہیں جو بئر معونہ کے واقعے میں شہید ہوئے۔ ابن قداح نے ذکر کیا ہے کہ وہ بیعت رضوان اور اس کے بعد والے واقعات میں شریک تھے۔ ابن مندہ نے اپنی سند سے نقل کیا ہے کہ ابن عمران کے جنازے میں حاضر تھے، ان کے چار پائی کے دو بانسوں کے درمیان تھے۔\nابن شاہین نے بحوالہ ابن ابو داؤد بیعت رضوان میں شریک ہونے والوں میں ان کا ذکر کیا ہے۔\nمیں کہتا ہوں: یہ نبی کریم صلی اللہ علیہ وسلم کی وفات سے چھ(۶) برس پہلے کا واقعہ ہے، گویا وہ ان ابو داؤد کے کلام سے واقف نہیں۔\nبیعت رضوان ہجرت کے سال ہوئی تھی، کم سے کم یہ ہے کہ جو اس بیعت میں شریک ہوا ان کی عمر پندرہ سال سے زیادہ ہو، وہ لازمی صحابی ہے، اگر چہ بیعت رضوان میں ان کا حاضر ہونا ثابت نہ ہو یہ ان کے والد کی تاریخ وفات کی وجہ ہے، انہوں نے نبی کریم صلی اللہ علیہ وسلم کی زندگی میں سے چھ(۶) یا اس سے زائد سال پائے۔\nابن مندہ کا کبھی یہی قول ہے: ان کی حدیث میں ذکر ہے، پھر عثمان بن عقبہ بن عویم بن ساعدہ کے طریق سے نقل کیا ہے، فرماتے ہیں: عبد اللہ بن عمر، محمد بن عاصم بن ثابت بن ابی اقلح کے جنازے میں ان کی چار پائی کے دونوں بانسوں کو اٹھائے ہوئے تھے، مجھے اب بھی ان کی داڑھی کی زردی نظر آ رہی ہے۔\nمیں کہتا ہوں: ابن اثیر(2) نے فرمایا: ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے جبکہ ابن مندہ نے ان کا ذکر کیا ہے، لہذا انہیں اپنے استدراک میں ذکر کرنے کی کوئی وجہ نہیں بنتی۔\nمیں کہتا ہوں: انہوں نے تو ان پانچ افراد کے ساتھ ملا کر ان کا ذکر کیا ہے، جن کا نام محمد ہے۔ ابن شاہین نے ان سب کا ذکر کیا ہے، چنانچہ ابو موسیٰ نے ان کا کلام نقل کیا ہے، لیکن اس بات سے خبردار نہیں کیا کہ ابن عاصم ان کے استدراک میں داخل نہیں ہیں۔","",{"fn":"(1) اسد الغابہ (۴۷۳۹) تجرید (۲/۵۹)\n(2) اسد الغابہ (۴/۷۴)"}],[6413,"§۷۷۸۵ ۔ محمد بن عباس بن فضلہ\nان کا نسب ان کے والد کے حالات میں گزر چکا ہے، ابن القداح کا قول ہے: نبی کریم صلی اللہ علیہ وسلم نے ان کا نام محمد رکھا تھا۔ فتح مکہ میں شریک تھے، ابن شاہین نے ابن ابو داؤد سے، بحوالہ ان کے ان کی حدیث نقل کی ہے۔"],[6414,"§۷۷۸۶ ۔ محمد بن عبد اللہ(1)\nابن ابی انصاری خزرجی، خزرج کے سردار جو نفاق میں مشہور تھا، اس کے بیٹے ہیں۔ ان کا نسب ان کے بھائی عبد اللہ بن عبد اللہ کے حالات میں گزر چکا ہے۔ ابن مندہ نے صحابہ میں ان کا ذکر کیا ہے۔ اور بطریق راشد المحمانی عن ثابت البنانی عن محمد بن عبد اللہ بن ابی ابن سلول روایت کی ہے کہ ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم تشریف لائے، فرمانے لگے: \"اے جماعت انصار! اللہ تعالیٰ نے تمہاری پاکیزگی کی تعریف کی ہے تم لوگ کیسے طہارت حاصل کرتے ہو؟\" ہم نے عرض کی: اللہ کے رسول! ہمارے درمیان اہل کتاب رہتے تھے، ان میں سے جب کوئی شخص پاخانے سے ہو کر آتا تو وہ پانی سے استنجا کرتا تھا، تو ہم نے بھی ایسا کرنا شروع کر دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے تمہاری بہت تعریف کی ہے۔۔۔۔۔\"۔ (الحدیث)(2)\nابن مندہ فرماتے ہیں: یہ غریب حدیث ہے جو صرف حدیث جعفر بن عبد اللہ السالمی عن ربیع بن بدر عن جعفر مشہور ہے۔ اور یہ تینوں ضعیف راوی ہیں۔ فرماتے ہیں: حدیث عبد اللہ بن سلام اور حدیث محمد بن عبد اللہ بن سلام سے بھی مروی ہے، الہیثم نے اس روایت کو راجح قرار دیا ہے، وہ فرماتے ہیں: اس میں جعفر کو وہم ہوا ہے، صحیح یوں ہے: محمد بن عبد اللہ بن سلام۔\nمیں کہتا ہوں: یہ اس احتمال پر ہے کہ واقعہ متعدد ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۴۰) استیعاب (۲۳۶۴) معرفۃ الصحابہ (ج ۱ ص ۱۲۱، ۱۳۱)\n(2) اسد الغابہ (۴۷۴۱) استیعاب (۲۳۶۳) التاریخ الکبیر (۱/۱۲)"}],[6415,"§۷۷۸۷ ۔ محمد بن عبد اللہ بن جحش اسدی(1)\nان کا نسب ان کے والد کے حالات میں گزر چکا ہے۔ یہ امام المؤمنین سیدہ زینب رضی اللہ عنہا کے بھتیجے ہیں، ان کی والدہ سیدہ فاطمہ بنت ابی حبیش بھی صحابیہ ہیں۔\nواقدی رحمہ اللہ کا بیان ہے: ہجرت سے پانچ سال پہلے پیدا ہوئے۔ طبری رحمہ اللہ نے یہ قول نقل کر کے فرمایا ہے، بقول بعض امام بخاری رحمہ اللہ انہیں شرف صحابیت حاصل ہے۔ ابن حبان کا قول ہے، انہوں نے نبی علیہ السلام سے سماع کیا ہے۔\nزبیر بن بکار نے بطریق محمد بن ابی یحییٰ روایت کی ہے، انہوں نے فرمایا: مجھ سے ابو کثیر مولیٰ محمد بن عبد اللہ بن جحش نے بیان کیا کہ میں نے محمد بن عبد اللہ بن جحش (جنہیں شرف صحابیت حاصل ہے) فرماتے سنا، پھر قرض میں تھی(2) اور جہاد کی فضیلت کے بارے میں وارد حدیث ذکر کی، اسی حدیث کو امام احمد، ابن ابی خیثمہ اور بغوی رحمہ اللہ وغیرہ نے نقل کیا ہے۔ ان میں سے کسی کی روایت میں ہے، ہم لوگ جنازہ گاہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھے ہوئے تھے اور بعض نے ان کے اس قول کی صراحت کی ہے، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا، بہر کیف اس کا مدار علاء بن عبد الرحمن عن ابی کثیر مولیٰ محمد بن عبد اللہ بن جحش، بحوالہ ان کے مردوی سند پر ہے، سیر عورت(3) کے بارے میں ان کی حدیث امام احمد، نسائی، ابن ماجہ اور امام بخاری رحمہ اللہ نے تعلیقاً نقل کی ہے اور حاکم نے اسے صحیح قرار دیا ہے۔ ابن سعد کا قول ہے ان کی کنیت ابو عبد اللہ تھی، ان کے والد احد میں شہید ہو گئے تھے۔ نبی کریم صلی اللہ علیہ وسلم کو اپنے بیٹے کے بارے میں وصیت کر گئے تھے۔ آپ صلی اللہ علیہ وسلم نے ان کے لیے خیبر میں مال خریدا اور مدینے میں انہیں جائیداد دی۔ بغوی رحمہ اللہ نے بطریق علی ابن زید عن انس عن سعید بن مسیب روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ نے ان مہاجرین کے بیٹوں کے بارے میں چار ہزار کا وظیفہ لکھا جو بدر میں شریک ہوئے تھے، ان میں محمد بن عبد اللہ بن جحش بھی تھے۔","",{"fn":"(1) اسد الغابہ (۴۷۴۱) استیعاب (۲۳۶۳) التاریخ الکبیر (۱/۱۲)\n(2) مسند احمد (۴/۳۵۰) استیعاب (۳/۳۵۰) معرفۃ الصحابہ (۲/۴۸)\n(3) مسند احمد (۴/۳۵۰) مستدرک (۴/۱۸۰)"}],[6416,"§۷۷۸۸ ۔ محمد بن عبد اللہ بن ابی سعد(1)\nمدحجی، ثم حکمی۔ زبیر بن بکار کا بیان ہے کہ سیدنا عثمان رضی اللہ عنہ کی بہن سیدہ آمنہ بنت عفان کی باندی اور ان کی والدہ ارویٰ بنت کریز ایک سال مسلمان ہوئی تھیں۔ عنقریب ان کا تذکرہ ہوگا۔ مؤرخین نے صحابہ رضی اللہ عنہم میں عبد اللہ کا ذکر نہیں کیا، شاید وہ فتح مکہ سے پہلے فوت ہو گئے ہوں اور ان کے یہ بیٹے اس قسم یا بعد والے قسم میں سے شمار ہوں گے۔","",{"fn":"(1) اسد الغابہ (۴۷۴۲) استیعاب (۲۳۶۵) تجرید (۲/۵۹)"}],[6417,"§۷۷۸۹ ۔ محمد بن عبد اللہ بن سلام\nابن حارث اسرائیلی، بخاری رحمہ اللہ نے صحابہ میں ان کا ذکر کیا ہے۔ ابن حبان کا قول ہے، بعض نے کہا کہ انہیں شرف صحابیت حاصل ہے۔ ابن شاہین کا قول ہے: ابو داؤد نے کہا: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے ایک حدیث روایت کی۔ ابن مندہ کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم کا دیدار کیا اور آپ صلی اللہ علیہ وسلم سے حدیث سنی۔ ابو عمر(1) کا قول ہے: انہیں رؤیت حاصل ہے اور ان کی روایت کتابوں میں محفوظ ہے۔\nامام احمد رحمہ اللہ نے اور امام بخاری رحمہ اللہ نے اپنی تاریخ میں اور ابو بکر بن ابی شیبہ، ابن قانع، بغوی، طبرانی، ابن مندہ نے بطریق مالک بن مغول، بحوالہ محمد بن عبد اللہ بن سلام روایت کیا ہے۔ فرماتے ہیں: ہمارے پاس نبی کریم صلی اللہ علیہ وسلم تشریف لائے اور فرمایا: اللہ تعالیٰ نے کس وجہ سے ہماری تعریف بیان کی(2) اس میں ایسے مرد رہتے ہیں، جو پاکیزگی کو پسند کرتے ہیں(2) انہوں نے کہا: \"ہم پانی سے استنجا کرتے ہیں\"۔(2)\nاسے بغوی نے بحوالہ مالک بن مغول اسی طرح روایت کیا ہے، لیکن فرماتے ہیں: اس میں ہے: میں اسے ان کے والد کے حوالے کے علاوہ نہیں جانتا۔ ابو ہشام کا قول ہے: میں نے اسے یحییٰ بن آدم کی اصل کتاب سے لکھا ہے، اس میں یہ نہیں ہے، بحوالہ ان کے والد۔\nبغوی کا قول ہے: اسے فریابی رحمہ اللہ نے بحوالہ شہر، انہوں نے محمد سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ہے، ان کے والد کا ذکر نہیں کیا۔ ابن مندہ کا قول ہے: اسے داؤد بن ابی ہند نے، بحوالہ شہر مرسل روایت کیا ہے، اور ان کے والد کا ذکر نہیں کیا۔ اسے مسلم بن رجا نے بحوالہ مالک بن مغول روایت کیا ہے، اس میں یہ اضافہ کیا ہے: بحوالہ ان کے والد۔ ابو زہرہ رازی کا قول ہے: ہمارے نزدیک صحیح یہ ہے: بحوالہ محمد، اس میں یہ نہیں ہے: بحوالہ ان کے والد، واللہ اعلم","",{"fn":"(1) استیعاب (۳/۴۲۰) سورۃ التوبۃ الآیۃ (۱۰۸)\n(2) مسند احمد (۲۶۱) مصنف ابن ابوشیبہ (۱/۲۱۳) معرفۃ الصحابہ (۲/۷۹) تاریخ کبیر (۱/۱۸) جامع البیان (۱۱/۲۲) سیوطی فی الدر المنثور (۲/۲۸۷)"}],[6418,"§۷۷۹۰ ۔ محمد بن عبد اللہ (بے نسبت)\nباوردی نے ان کا ذکر کیا ہے، اور بطریق حماد بن سلمہ، بحوالہ محمد بن عبد اللہ ان کی حدیث نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک عورت کو اپنے بائیں ہاتھ سے کھاتے ہوئے دیکھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس ہاتھ سے نہ کھا، ذا اس ہاتھ سے پڑا\"۔(1)\nاحتمال ہے کہ وہ ابن سلام کے بیٹے ہوں۔","",{"fn":"(1) طبرانی (۲۲/۲۳) تجرید (۲/۶۰)"}],[6419,"§۷۷۹۱ ۔ محمد بن عبد اللہ(1)\nابن عبدہ انصاری، ابن قداح نے ذکر کیا ہے کہ وہ بیعت رضوان اور اس کے بعد کے واقعات میں شریک تھے۔ بنو قریظہ کے دن پہرے میں تھے، ابن شاہین نے، بحوالہ ابن ابو داؤد، ان کے حوالے سے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۴۷) تجرید (۲/۶۰)"}],[6420,"§۷۷۹۲ ۔ محمد بن ابو عبس(1)\nابن جبر انصاری، ان کے والد صحابہ میں مشہور ہیں۔ رہے وہ تو ابن مندہ نے ان کا ذکر کیا ہے۔ فرماتے ہیں: ابن متیع نے ان کا ذکر کیا ہے۔ حدیث ان کے والد کے حوالے سے ہے، اسی طرح اسے مختصر ذکر کیا ہے۔ اور جو کچھ بغوی نے نقل کیا ہے، اس کی طرح اشارہ کیا ہے۔ بطریق محمد بن طلحہ تیمی، بحوالہ محمد بن ابی عبس بن جبر، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ابن اشرف سے میرا بچاؤ کون کرے گا\"۔ محمد بن مسلمہ نے کہا: \"میں\"۔۔۔۔۔ (الحدیث)\nیہ کعب بن اشرف کے قصے کے بارے میں ہے۔\nابن مندہ نے اشارہ کیا ہے کہ ضمیر عن جدہ میں ابو عبس بن محمد ہیں، تو حدیث ابو عبس بن جبر کی ہوگی، ان کے بیٹے محمد کی نہیں۔ لیکن ابن شاہین نے، بحوالہ ابن قداح ذکر کیا ہے کہ محمد بیعت رضوان اور اس کے بعد کے مواقع میں شریک تھے۔","",{"fn":"(1) مستدرک حاکم (۳/۴۲۴) دلائل النبوۃ (۳/۱۹۹)"}],[6421,"§۷۷۹۳ ۔ محمد بن عبیدہ\nابن حارث بن مطلب بن عبد مناف، قرشی مطلبی، ان کے والد سابقین میں سے ہیں، یہ پہلے گزر چکا ہے۔ وہ ان تین لوگوں میں سے ہے جنہوں نے بدر کے دن مبارزت کی تھی۔ وہ اس دن کے وار سے شہید ہو گئے تھے۔ رہے محمد تو بلاذری وغیرہ نے عبیدہ کی اولاد میں ان کا ذکر کیا ہے۔"],[6422,"§۷۷۹۴ ۔ محمد بن عثمان\nابن بشر بن عبید بن دہمان بن یار بن مالک بن حطیط ثقفی۔ زبیر بن بکار نے ذکر کیا ہے کہ ان کی والدہ ریحانہ بنت ابی عاص بن امیہ بن اخت حکم ہیں جو مردان کے والد ہیں۔ میں نے ان کے والد کا صحابہ رضی اللہ عنہم میں ذکر نہیں دیکھا۔ گویا وہ فتح سے پہلے وفات پا گئے۔ ان کی والدہ اسلام لائیں، اس وجہ سے ان کا نام محمد رکھا۔\nمحمد بن عبد اللہ بن ابو سعد مدنی کا ذکر پہلے گزر چکا ہے، ان کا قصہ اس قصے سے ملتا جلتا ہے۔ ان کی والدہ ان کی والدہ کی خالہ ہیں۔"],[6423,"§۷۷۹۵ ۔ محمد بن عدی(1)\nابن ربیعہ بن سواوہ بن جشم بن سعد منقری، ابن سعد، بغوی، باوردی، ابن سکن وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابن سعد کا قول ہے: اہل کوفہ میں ان کا شمار ہے، ابن شاہین کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ بطریق علامہ بن فضل بن ابی سوید معتری نقل کیا ہے کہ مجھ سے ابو فضل بن عبد الملک نے، بحوالہ خلیفہ بن عبدہ معتری نقل کیا ہے، فرماتے ہیں: میں نے محمد بن عدی بن ربیعہ سے سوال کیا، آپ کے والد نے جاہلیت میں آپ کا نام محمد کیسے رکھ دیا؟ انہوں نے کہا: میں نے اپنے والد سے بھی سوال کیا تھا، انہوں نے کہا: ہم بخیم کے چار افراد نکلے جن میں سے ایک میں، سفیان بن مجاشع، یزید بن عمرو بن ربیعہ بن جرتوحص بن مازن اور اسامہ بن مالک بن جندب بن نمیر تھے۔ ہم شام میں ابن جفہ غسانی کے ارادے سے نکلے تھے۔ جب ہم شام پہنچے اور ایک تالاب کے پاس فرود کش ہوئے جہاں لیکر کے درخت تھے، اس کے قریب ایک راہب کھڑا تھا، جب اس نے ہماری گفتگو سنی تو کہنے لگا: ہم نے کہا تھا اگر ہم اس پانی سے غسل کر لیں اور تیل لگا کے اپنے کپڑے پہن کر اپنے ساتھی کے پاس جائیں تو زیادہ بہتر رہے گا۔ چنانچہ ہم نے ایسا ہی کیا۔ وہ راہب کہنے لگا: یہ تو ایسی قوم کی زبان ہے جو یہاں کے لوگوں کی زبان نہیں۔ ہم نے اس سے کہا: ہم معدی کی قوم ہیں۔ اس نے کہا: کون سے معدی؟ ہم نے کہا: جذف۔ وہ کہنے لگا: عنقریب تم میں سے ایک نبی مبعوث ہوگا، اس کی طرف جلدی جانا اور اس کی صحبت سے فیض اٹھانا، ہدایت پا ؤ گے، کیونکہ وہ خاتم النبیین ہے۔ ہم نے اس سے پوچھا: اس کا نام کیا ہے؟ وہ کہنے لگا: محمد۔ جب ہم ابن جفہ کے پاس سے واپس آئے تو ہم میں سے ہر ایک کے ہاں لڑکا پیدا ہوا جس کا نام اس بشارت کی وجہ سے محمد رکھا۔ ابو نعیم(2) نے یہ روایت بطریق ابی بکر بن خزیمہ، صالح بن مسمار سے املاء نقل کی ہے کہ ہم سے علامہ بن فضل نے روایت کی، ابو نعیم کا قول ہے: ہم نے طبرانی(2) کی عالی سند سے اسے روایت کیا ہے، ہم سے علامہ نے روایت کیا ہے۔\nمیں کہتا ہوں: وہ محمد اوسط میں ہے۔ اسے محمد کبیر میں ذکر نہیں کیا۔\nابن اثیر(2) نے ابن مندہ پر صحابہ میں محمد بن عدی کا تذکرہ کرنے کی وجہ سے تکبیر کی ہے۔ جبکہ تکبیر کی کوئی وجہ نہیں۔ کیونکہ اس روایت کے سیاق سے محمد بن عدی کا صحابی ہونا معلوم ہوتا ہے۔ بخلاف محمد بن سفیان بن مجاشع، چنانچہ ابو موسیٰ نے ابو نعیم پر ان کے ذکر کی وجہ سے تکبیر کی ہے اور ان پر لازم قرار دیا ہے کہ وہ محمد بن اسامہ اور محمد بن یزید بن ربیعہ کا بھی تذکرہ کرتے۔ اس لیے کہ ان میں سے کسی کی حدیث میں یہ بات نہیں کہ وہ عہد نبوی تک زندہ رہے۔","",{"fn":"(1) اسد الغابہ (۴۷۴۸) تجرید (۲/۶۰) معرفۃ الصحابہ (۲/۸۲)\n(2) معجم کبیر (۱۷/۲۷۲) اسد الغابہ (۴/۷۷)"}],[6424,"§۷۷۹۶ ۔ محمد بن عقبہ\nابن احیم انصاری۔ بلاذری نے ان لوگوں میں ان کا ذکر کیا ہے جن کا نام جاہلیت میں محمد رکھا گیا۔ ابو موسیٰ نے بعض حفاظ سے ذکر کیا ہے کہ انہوں نے بعثت سے پہلے محمد نامی لوگوں میں انہیں شمار کیا ہے۔ محمد بن احیم کا ذکر گزر چکا ہے۔ مجھے معلوم نہیں کہ وہ یہی ہیں یا ان کے چچا ہیں۔\nپھر میں نے ابو عبد اللہ محمد بن یحییٰ بن حذاق کی کتاب \"رجال الموطا\" میں ان سے احیم بن جلاح کے حالات میں نقل کرنے کے بعد دیکھا، فرماتے ہیں: احیم کا ایک عقبہ نامی بیٹا تھا اور عقبہ کا محمد نامی بیٹا تھا اور محمد کی ایک بیٹی تھی جو مشہور صحابی فضالہ بن عبید کی والدہ ہیں، اور محمد کا ایک بیٹا مندر تھا جو بئر معونہ کے دن شہید ہوئے، اس سے ظاہر ہے کہ محمد بن عقبہ اسلام سے پہلے فوت ہوئے۔ واللہ اعلم"],[6425,"§۷۷۹۷ ۔ محمد بن علبہ قرشی(1)\nعبد الغنی بن سعید نے ان کا ذکر کیا ہے، فرماتے ہیں: انہیں شرف صحابیت حاصل ہے، ان کے والد کے نام کو مہملہ کے پیش اور زلام کے سکون کے ساتھ نقل کیا ہے۔ ابن ماکولا(2) نے ان کی پیروی کی ہے۔ ابن مندہ نے بطریق عمرو بن حارث، بحوالہ حبیب بن مغفل کہ انہوں نے محمد بن علبہ قرشی کو دیکھا کہ اپنا تہبند کھینچ رہے تھے، انہیں حبیب نے دیکھا تو فرمایا: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے نہیں سنا: \"(وضو میں خشک) ٹخنوں کے لیے آگ کی ہلاکت ہے\"۔\nاس حدیث کی سند صحیح ہے، اور حبیب اس حدیث کو روایت کرنے والے مشہور صحابی ہیں۔\nاسے احمد نے اس طریق سے نقل کیا ہے، لیکن اس کے الفاظ ہیں۔ بحوالہ حبیب کہ انہوں نے محمد قرشی کی تہبند کھینچتے ہوئے دیکھا، انہوں نے انہیں دیکھا اور فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے۔۔۔۔۔ (الحدیث) اسی طرح ان کی کتاب میں لفظ سمعت ہے، ان کا اس میں قصہ ہے۔\nاسے ابن یونس نے دوسرے طریق سے بحوالہ ابو یزید روایت کیا ہے کہ ابو عمران نے انہیں بتایا، فرماتے ہیں: مجھے سلمہ بن ملحج نے صاحب حبشہ کی طرف بھیجا، جب میں دروازے پر پہنچا، میں نے صحابی سیدنا حبیب بن مغفل کو اور محمد بن علبہ قرشی کو پایا، محمد کو اجازت مل گئی، وہ اپنے تہبند کو کھینچتے ہوئے اٹھے، انہیں حبیب نے دیکھا تو فرمایا: میں نے سنا۔۔۔۔ پھر اسے ذکر کیا۔\nاسی طرح نسائی نے دوسرے طریق سے بحوالہ یزید اس حدیث کو قصے کے بغیر ذکر کیا، میں نے کسی کو نہیں پایا کہ انہوں نے لفظ آما سمعت کے ساتھ نقل کیا ہو، یعنی آما کے اضافے کے ساتھ جو استفہام کے لیے ہے اور سمعت کے ساتھ، صحابہ رضی اللہ عنہم کے بارے میں لکھنے والے بعض مؤلفین نے اسے جائز کہا ہے کہ یہ آما کے بجائے آتا ہے۔ ابن مندہ نے اس روایت پر اعتماد کیا ہے جوان کے پاس لکھی ہے، اس لیے انہوں نے صحابہ رضی اللہ عنہم میں محمد بن علبہ کا ذکر کیا ہے اور شاید یہی عبد الغنی بن سعید کی دلیل ہے، ابو نعیم نے یہ حدیث بطریق مسند احمد نقل کی ہے کہ مسافرین میں سے کسی کا گمان ہے کہ حبیب کا محمد کو ذکر کرنا ان کے صحابی ہونے کا تقاضا کرتا ہے۔ اگر ایسا ہو جائے کہ جو شخص صحابہ کے پاس بیٹھتا ہو یا صحابہ رضی اللہ عنہم اس سے میل جول رکھتے ہوں تو اسے صحابی شمار کر لیا جائے تو یہ قسم بہت زیادہ بڑھ جائے گی۔ ابن اثیر(3) نے ان کا تعاقب کیا ہے، اور ابن مندہ کے عذر کو برقرار رکھا ہے۔\nمیں کہتا ہوں: ابو نعیم نے ابن مندہ کے سیاق میں غور نہیں کیا جوان سے منقول ہے کہ محمد صحابی ہیں اور اس سیاق پر کلام کر دیا جو انہوں نے مسند احمد سے لیا ہے، وہ اس کا تقاضا نہیں کرتا۔","",{"fn":"(1) اسد الغابہ (۴۷۵۰) استیعاب (۲۳۶۶) تجرید (۲/۶۰)\n(2) اکمال (۲/۱۴۵)\n(3) اسد الغابہ (۴/۷۸)"}],[6426,"§۷۷۹۸ ۔ محمد بن عمرو بن عاص(1)\nابن وائل قرشی سہمی۔ ان کے بھائی عبد اللہ اور والد عمرو کے سوانح میں ان کا نسب گزر چکا ہے۔ عدوی نے انساب میں ذکر کیا ہے کہ محمد کو نبی کریم صلی اللہ علیہ وسلم کا صحابی ہونے کا شرف حاصل ہے، وہ کم عمر تھے، ابن سعد کا قول ہے: ان کی والدہ بلبویہ ہیں۔ ابن برقی کا قول ہے: ان کا نام خولہ بنت حمزہ بن سلیل ہے، ابن سعد نے، بحوالہ واقدی رحمہ اللہ ان کی اسناد سے ذکر کیا ہے کہ جب سیدنا عثمان رضی اللہ عنہ نے سیدنا عمرو بن العاص کو مصر سے معزول کر دیا تو وہ مدینہ آئے اور سیدنا عثمان رضی اللہ عنہ پر اعتراض کرنے لگے۔ سیدنا عثمان رضی اللہ عنہ کو معلوم ہوا تو آپ نے انہیں ڈانٹ پلائی۔ تو وہ فلسطین میں اپنی جائیداد کی طرف چلے گئے اور وہاں مقیم ہو گئے یہاں تک کہ انہیں سیدنا عثمان رضی اللہ عنہ کی شہادت، سیدنا علی رضی اللہ عنہ کی بیعت پھر جب جمل اور امیر معاویہ رضی اللہ عنہ کی مخالفت کی خبریں ملنے لگیں، تو انہوں نے سیدنا علی رضی اللہ عنہ سے ملنا چاہا باوجودیکہ انہیں معلوم ہوا کہ سیدنا علی رضی اللہ عنہ انہیں اپنے کام میں شریک نہیں کریں گے۔\nانہوں نے اپنے دونوں بیٹوں عبد اللہ اور محمد سے مشورہ لیا، تو عبد اللہ نے آپ کو مشورہ دیا کہ وہ انتظار کریں یہاں تک کہ کوئی فیصلہ ہو جائے اور محمد نے کہا: عربی اشعار میں آپ کی شہسواری کا ذکر ہے۔ میں نہیں سمجھتا کہ جب تک اس میں آپ کا ذکر نہیں ہوگا تو کوئی فیصلہ نہیں ہوگا۔ تو آپ نے عبد اللہ سے فرمایا: تم نے مجھے وہ مشورہ دیا جو میرے لیے آخرت میں بہتر ہے۔ اور محمد سے فرمایا: تم نے مجھے وہ مشورہ دیا جو میرے لیے دنیا میں خبرداری کا ذریعہ ہے، اور امیر معاویہ کی طرف کوچ کر گئے، قصہ لمبا ہے۔ اس سے معلوم ہوتا ہے کہ محمد اس وقت سیدنا عمرو کے نزدیک اتنے ہوشیار تھے کہ آپ نے انہیں مشورے کا اہل سمجھا۔\nواقدی رحمہ اللہ اور زبیر بن بکار کا قول ہے کہ جنگ صفین میں اپنے والد کے ساتھ شریک ہوئے، جنگ میں بڑے جوہر دکھائے\nوہی یہ شعر کہتے ہیں: \"اگر میری جگہ اور مقام پر جنگ صفین میں ایک دن بھی اونٹ شریک ہوتے تو ان کے سر کے بال سفید ہو جاتے جو بقول بعض ان کے بھائی عبد اللہ کے اشعار ہیں\"۔\nحافظ ابن عساکر نے زبیر تک اپنی سند پھر ان کی ابن شہاب تک کی سند سے یہ واقعہ نقل کیا ہے کہ محمد بن عمرو بن العاص جنگ صفین کی لڑائی میں شریک ہوئے۔ پھر ایک واقعہ ذکر کیا جس میں یہی اشعار ہیں، یہی واقعہ بطریق نضر بن مزاحم عن عمرو بن سعد عن محمد ابن عمرو اور دوسری سند سے عبد اللہ بن عمرو کے حالات سے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۵۲) استیعاب (۲۳۶۸) تجرید (۲/۶۰)"}],[6427,"§۷۷۹۹ ۔ محمد بن عمرو\nابن مغفل، حبیب غفاری کے والد، مؤرخین نے انہیں ذکر نہیں کیا۔ باوجودیکہ یہ اس شخص کی شرط کے مطابق ہیں جس نے عنقریب ہی محمد بن عقبہ کا ذکر کیا ہے۔"],[6428,"§۷۸۰۰ ۔ محمد بن ابو عمیرہ مزنی(1)\nبخاری(2) نے ان کا ذکر کیا ہے۔ فرماتے ہیں: انہیں شرف صحابیت حاصل ہے۔ شامیوں میں ان کا شمار ہے، پھر بطریق ابن مبارک، بحوالہ محمد بن ابو عمیرہ، جو اصحاب نبی صلی اللہ علیہ وسلم میں سے ہیں ان کی حدیث نقل کی ہے، فرماتے ہیں: \"اگر کوئی بندہ پیدائش سے لے کر بڑھاپے تک اللہ کی عبادت میں سجدہ ریز رہے تو وہ اس دن کو کم سمجھے گا، اور اس کی خواہش ہوگی کہ کاش اس کی عمر بڑھتی، تاکہ وہ زیادہ اجر و ثواب حاصل کرتا\"۔(3)\nاس کی سند قوی ہے، اسے ابن مبارک نے کتاب الزہد میں نقل کیا ہے، ابن شاہین نے اسے اپنے طریق سے نقل کیا ہے، لیکن ان کی کتاب میں محمد بن عمیرہ لکھا ہے۔\nاسے ابن ابو عاصم اور بغوی نے بطریق ولید بن مسلم، بحوالہ ثور موقوفاً نقل کیا ہے، لیکن ابن مندہ نے ذکر کیا ہے کہ ابن ابو عاصم کی روایت ہے، میرے خیال میں انہوں نے یہ بات نبی کریم صلی اللہ علیہ وسلم کے حوالے سے ذکر کی ہے۔\nاسے ابن مندہ نے بروایت محمد بن شعیب، بحوالہ ثور موقوفاً نقل کیا ہے اور بروایت معاویہ بن صالح، بحوالہ ان کے بعض شیوخ، انہوں نے خالد بن معدان سے اسی طرح نقل کیا ہے۔\nاسے عیسیٰ بن یونس نے، بحوالہ ثور پہلی روایت کی طرح نقل کیا ہے۔ اسے احمد نے بطریق بقیہ، بحوالہ بجیر بن سعد، انہوں نے خالد بن معدان سے، انہوں نے عقبہ بن عبد سلمی سے مرفوعاً روایت کیا ہے۔\nابن سکن اور ابن شاہین نے صحیح سند سے جو بقیہ تک پہنچتی ہے۔ بحوالہ ابن ابی عمیرہ نقل کیا ہے۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے نقل کیا ہے کہ انہوں نے فرمایا: \"اے لوگو! ہر متنفس دنیا میں آنے کی آرزو کرے گا\"۔\nپھر ابن سکن کا قول ہے: بعض نے کہا: ابن ابی عمیرہ، ان کا نام محمد ہے، نسائی نے ان کی حدیث نقل کی ہے، فرماتے ہیں: ابن ابی عمیرہ، انہوں نے بھی ان کا نام نہیں لیا۔ اسے بغوی نے محمد کے سوانح میں پہلی حدیث کے بعد نقل کیا ہے، فرماتے ہیں: مجھے معلوم نہیں کہ انہوں نے ان دو حدیثوں کے علاوہ کوئی روایت کی ہو۔","",{"fn":"(1) اسد الغابہ (۴۷۵۴) استیعاب (۲۳۶۹) تجرید (۲/۶۰)\n(2) تاریخ کبیر (۱/۱۵)\n(3) مسند احمد (۴/۱۸۵) المعجم الکبیر (۱۹/۲۴۹) تاریخ کبیر (۱/۵۱) الآحاد والمثانی (۳/۲۵۲)"}],[6429,"§۷۸۰۱ ۔ محمد بن عیاض زہری(1)\nمتدرک حاکم میں ان کا ذکر ہے، پھر بطریق ابن لہیعہ، بحوالہ محمد بن عیاض زہری روایت کیا ہے، فرماتے ہیں: بچپن میں مجھے نبی علیہ السلام کی خدمت میں پیش کیا گیا میں ایک کپڑے میں لپٹا ہوا تھا، میری شرمگاہ کھل گئی تو آپ صلی اللہ علیہ وسلم نے فرمایا: اس کا ستر ڈھانپو کیونکہ مجھے بالغ کی شرمگاہ دیکھنا حرام ہے، ایسے ہی بچے کی شرمگاہ دیکھنا حرام ہے، اور اللہ تعالیٰ اس شخص کی طرف (نظر رحمت سے) نہیں دیکھتے جو (بلا وجہ) اپنی شرمگاہ کھلی رکھے\"۔(2)\nسند میں ابن لہیعہ کے ساتھ کئی ضعیف راوی ہیں۔","",{"fn":"(1) تجرید (۲/۶۱)\n(2) مستدرک (۲/۲۵۷) کنز العمال (۱۹۱۱۱) تجرید (۲/۶۱)"}],[6430,"§۷۸۰۲ ۔ محمد بن فضالہ(1)\nوہ ابن انس بن فضالہ ہیں، اسی طرح گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۵۶) تجرید (۲/۶۱)"}],[6431,"§۷۸۰۳ ۔ محمد بن قیس\nابن شر حبیل بن ہاشم بن عبد مناف بن عبد دار قرشی عبدری، ابن قداح نے ذکر کیا ہے کہ انہوں نے حبشہ کی طرف ہجرت کی، اسے ابن شاہین نے، ابن ابو داؤد سے، بحوالہ ابن قداح نقل کیا ہے۔"],[6432,"§۷۸۰۴ ۔ محمد بن قیس اشعری\nابو موسیٰ اشعری کے بھائی ہیں، ابن مندہ نے ان کا ذکر کیا ہے، اور بطریق طلحہ بن یحییٰ نقل کیا ہے کہ ہم سے ابو بردہ بن ابو موسیٰ نے، بحوالہ اپنے والد نقل کیا ہے، فرماتے ہیں: ہم سمندر کے راستے رسول اللہ صلی اللہ علیہ وسلم کے پاس مکہ آئے، میں اور تمہارا بھائی، میرے ساتھ ابو عامر بن قیس، ابو برہم، محمد بن قیس، ابو بردہ اور پچاس اشعری تھے۔ چھٹک قبیلے سے تھے۔ پھر ہم نے سمندر کے راستے سے ہجرت کی اور مدینہ آ گئے۔ رسول اللہ صلی اللہ علیہ وسلم فرما رہے تھے: \"لوگوں کے لیے ایک ہجرت ہے اور تمہارے لیے دو ہجرتیں ہیں\"۔(1)\nابن مندہ کا قول ہے: اسے یزید بن عبد اللہ بن ابو بردہ نے اپنے آباؤ اجداد کے حوالے سے نقل کیا ہے، اور محمد کا ذکر نہیں کیا۔\nمیں کہتا ہوں: ان کی روایت میں نہیں ہے کہ انہوں نے مدینہ کی طرف ہجرت کرنے سے پہلے، مکہ کی طرف ہجرت کی، اس کے الفاظ صحیح میں ہیں: میں اور میرے بھائی ہجرت کر کے نبی کریم صلی اللہ علیہ وسلم کے پاس گئے، میں ان میں سب سے چھوٹا تھا، ان میں سے ایک ابو بردہ ہیں، اور دوسرے ابو برہم ہیں، یہ ۵۵ آدمی تھے۔\nابو عمر(2) نے ابو برہم کے سوانح میں ذکر کیا ہے کہ ابو موسیٰ اور ان کے بھائی ابو عامر اور ان کے بھائی ابو برہم، اور ان کے بھائی مہدی نے ہجرت کی۔ بعض کا قول ہے: ابو برہم مہدی ہیں۔ ابن فتوح نے مہدی بن قیس کا اپنے استدراک میں ذکر کیا ہے، اور اس کی نسبت ابن عبد البر کے اس بیان کی طرف کر دی جو ابو برہم محمد بن قیس کے حالات میں ذکر کیا ہے۔ اور یہ بھی بن طلحہ بن یحییٰ کی روایت کی طرف نسبت کی ہے، لگتا ہے، اس میں مجدی، محمد کی جگہ لکھا ہے۔ البتہ ابن حبان نے کتاب اصحاب میں یقین سے لکھا ہے کہ ابو برہم کا نام محمد بن قیس ہے۔ ابن قانع فرماتے ہیں: مجھے کوفہ کے ان اشعری کاتبوں نے بتایا جنہوں نے ابو موسیٰ اور ان کے گھرانے کا نسب لکھا ہے کہ ابو برہم کا نام محمد ہے۔ یعنی دال سے پہلے کی۔ حافظ ابن عساکر سکن میں فرماتے ہیں: یہ بات کتابوں میں محفوظ نہیں کہ ابو موسیٰ وشیخہ کا کوئی محمد نامی بھائی ہو، یہ صرف اسی حدیث میں ہے، بقول بعض یہ روایت محفوظ نہیں۔","",{"fn":"(1) صحیح ابن حبان (۷۱۹۴) معرفۃ الصحابہ (۲/۱۱۸)\n(2) استیعاب (۳/۴۳۲)"}],[6433,"§۷۸۰۵ ۔ محمد بن کعب(1)\nابن مالک انصاری، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ بغوی، باوردی، ابن سکن، ابن شاہین، ابن مندہ وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق عکرمہ بن عمار، بحوالہ طارق بن عبد الرحمن نقل کیا ہے کہ میں نے عبد اللہ بن کعب سے سنا اور آپ کے بھائی محمد بن کعب اس ستون کے پاس بیٹھے ہوئے تھے اور مسجد کے ایک ستون کی طرف اشارہ کیا، ہم نے ایک ایسے شخص کا ذکر کیا جو دوسرے کے مال پر قسم کھا رہا تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n\"جو شخص اپنے بھائی کے مال پر اس کا مال ہتھورنے کے لیے جھوٹی قسم کھائے تو اس سے (اللہ کا) ذمہ بری ہے اور اس کے لیے جہنم واجب ہے\"۔\nمحمد بن کعب عرض کرنے لگے: اللہ کے رسول اگر چہ وہ تھوڑا ہو تو آپ صلی اللہ علیہ وسلم کی انگلیوں میں ایک مسواک تھی، آپ نے اسے پلٹ کر فرمایا: \"اگر چہ یہ لکی مسواک ہی ہو\"۔(2)\nابو نعیم کا قول ہے، محمد بن کعب کے کلام کا اس حدیث میں ذکر وہم ہے، اسے ولید بن کثیر نے، بحوالہ محمد بن کعب نقل کیا ہے، انہوں نے اپنے بھائی عبد اللہ بن کعب سے، بحوالہ ابو امامہ سنا۔\nمیں کہتا ہوں: ولید کی حدیث صحیح مسلم میں ہے، میں ایسی بات سے واقف ہوا ہوں جو دلالت کرتی ہے کہ کعب بن مالک کے دو بیٹے ہیں، ان میں سے ہر ایک کا نام محمد ہے۔ میں نے حافظ جمال الدین مزنی کی تحریر سے تہذیب الکمال میں پڑھا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۵۸) استیعاب (۲۳۷۰) تجرید (۱/۲۲۷)\n(2) مسلم کتاب الایمان (۵۴۳۴) نسائی (۵۴۱۹) مسند احمد (۵/۲۶۱)"}],[6434,"§۷۸۰۶ ۔ محمد بن کعب انصاری\nاصغر، انہوں نے اپنے بھائی عبد اللہ بن کعب سے روایت کیا، ان سے ولید بن کثیر نے روایت کیا، فرماتے ہیں: محمد بن کعب بڑے ہیں۔ نبی کریم صلی اللہ علیہ وسلم کی حیات مبارکہ میں فوت ہوئے۔ یہ بڑے پتے کی بات ہے جس سے ابو نعیم کی تردید ہوتی ہے اور عکرمہ ابن عمار کی حدیث کی تقویت ہوتی ہے۔ اس کو بطور دلیل پیش کیا جا سکتا ہے کہ انہوں نے اس حدیث میں محمد بن کعب کا ذکر یاد رکھا ہے۔ وہ اور محمد ہیں ان کے علاوہ ہیں جو عبد اللہ بن کعب سے روایت کرتے ہیں اور اس سے یہ نقطہ بھی سمجھ آتا ہے کہ عبد اللہ بن کعب اپنے بھائی محمد بن کعب اکبر سے روایت کرتے ہیں، اور ان سے ان کے بھائی محمد بن کعب اصغر روایت کرتے ہیں۔"],[6435,"§۷۸۰۷ ۔ محمد بن مخلد(1)\nابن حکیم بن مستورد بن عامر بن عدی بن کعب بن حارث بن خزرج انصاری اوسی، ابن قداح نے ذکر کیا ہے کہ وہ عہد نبوی صلی اللہ علیہ وسلم میں پیدا ہوئے۔ یہ وہی ہیں کہ آپ صلی اللہ علیہ وسلم نے ان کا نام محمد رکھا وہ فتح مکہ میں شریک تھے، اسے ابن شاہین نے، بحوالہ ابن ابو داؤد ان کے حوالے سے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۶۰) تجرید (۲/۶۱)"}],[6436,"§۷۸۰۸ ۔ محمد بن مسلمہ(1)(4)\nابن سلمہ بن خالد بن عدی بن مجدعہ بن حارثہ بن خزرج بن عمرو بن مالک اوسی انصاری اوسی حارثی، ابو عبد الرحمن مدنی، بنو عبد اشہل کے حلیف ہیں۔ بعثت سے بائیس(۲۲) برس قبل پیدا ہوئے۔ جیسا کہ واقدی رحمہ اللہ کا قول ہے، ان لوگوں میں سے ہیں جن کا نام جاہلیت میں محمد رکھا گیا، بعض کا قول ہے: ان کی کنیت ابو عبد اللہ اور ابو سعید ہے، اکثر کے نزدیک پہلا قول ہے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے کئی احادیث روایت کیں۔\nابن عبد البر(2) نے ان کے نسب کے بارے میں کہا: ان سے ان کے بیٹے محمود، ذؤیب، مسعود بن مخزمہ، سہل بن ابی حثیمہ، ابو بردہ بن ابی موسیٰ، عروہ، اعرج، قیقبہ بن حصن اور دوسرے لوگوں نے روایت کی۔\nابن شاہین کا قول ہے: ہم سے عبد اللہ بن سلیمان بن اشعث نے روایت کیا کہ وہ بدر میں شریک تھے۔ وہ اور ان کی اولاد جعفر، عبد اللہ، سعد، عبد الرحمن اور عمر اصحاب نبی صلی اللہ علیہ وسلم میں سے تھے، فرماتے ہیں: میں نے انہیں فرماتے ہوئے سنا: اہل شام نے انہیں قتل کیا، پھر ہشام(3) کے طریق سے، بحوالہ حسن نقل کیا ہے کہ محمد بن مسلمہ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے مجھے تلوار عطا فرمائی، فرمایا:\n\"جب تک مشرکین جنگ کرتے رہیں تم اس سے انہیں قتل کرو، اور جب تم دیکھو کہ میری اُمت ایک دوسرے کی گردنیں اڑا رہی ہے تو اسے کسی کے پاس لاکر مارنا یہاں تک کہ ٹوٹ جائے۔ پھر اپنے گھر بیٹھ جانا یہاں تک کہ تمہارے پاس کوئی خطا کار ہاتھ پہنچ جائے، یا تمہیں موت آ جائے\"۔(5)\nانہوں نے ایسا ہی کیا۔\nمیں کہتا ہوں: اس سند کے رجال ثقہ ہیں، سوائے اس کے کہ حسن نے محمد بن مسلمہ سے نہیں سنا۔\nابن سعد(6) کا قول ہے: اسلام کے ابتدائی دور میں سیدنا سعد بن معاذ رضی اللہ عنہ سے پہلے سیدنا مصعب بن عمیر کے ہاتھ پر اسلام لائے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کے اور ابو عبیدہ کے درمیان بھائی چارہ قائم کیا، غزوہ بدر اور اس کے بعد سوائے غزوہ تبوک کے تمام غزوات میں شریک ہوئے، کیونکہ وہ نبی علیہ السلام کی اجازت سے مدینہ میں ٹھہرنے کے لیے پیچھے رہ گئے تھے، اور وہ ان لوگوں میں سے تھے جو کعب بن اشرف اور ابن ابو حقیق کو قتل کرنے گئے۔\nابن عبد البر(7) کا قول ہے: صاحب فضیلت صحابہ میں سے تھے، بعض غزوات میں نبی کریم صلی اللہ علیہ وسلم نے انہیں اپنے پیچھے مدینے میں چھوڑ گئے تھے، یہ ان لوگوں میں سے تھے جو فتنے سے علیحدہ رہے اور جمل اور صفین میں شریک نہ ہوئے۔\nسیدنا حذیفہ نے ان کے بارے میں فرمایا: میں ایک ایسے شخص کو جانتا ہوں جسے فتنہ کوئی نقصان نہیں پہنچا سکتا۔ ان کا ذکر کیا اور نبی صلی اللہ علیہ وسلم سے اس بات کے سامع کی صراحت کی ہے۔ اسے بغوی وغیرہ نے ذکر کیا ہے، ابن کلبی رحمہ اللہ فرماتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے انہیں بھیجنے کی زکوٰۃ وصولی پر مقرر کیا، جبکہ اور وں کا کہنا ہے کہ وہ سیدنا عمر رضی اللہ عنہ کے ہاں شہروں کے مشکل معاملات کو سلجھانے کے لیے مقرر تھے، کوفہ میں سیدنا سعد بن ابی وقاص نے محل تعمیر کیا تو اس کی چھان بین کے لیے سیدنا عمر رضی اللہ عنہ کے یہی قاصد تھے۔\nیہی قاصد تھے۔ ابن مبارک کتاب الزہد میں فرماتے ہیں: ہمیں ابن عیینہ نے عمرو بن سعید نے، بحوالہ عبایہ بن رفاعہ روایت کی ہے کہ سیدنا عمر بن خطاب رضی اللہ عنہ کو معلوم ہوا کہ سیدنا سعد بن ابی وقاص نے ایک محل بنایا ہے جس کا دروازہ دکھا ہے۔ فرماتے ہیں: آواز وہاں تک نہیں پہنچتی، چنانچہ آپ نے محمد بن مسلمہ کو روانہ کیا اور سیدنا عمر رضی اللہ عنہ کی عادت تھی کہ جب وہ حسب منشا کوئی کام کرنا چاہتے تھے تو انہیں کو روانہ کرتے تھے۔ آپ نے ان سے فرمایا: سعد کے پاس پہنچ کر اس کا دروازہ جلا دینا۔ چنانچہ وہ کوفہ آئے، جب دروازے پر پہنچے تو چقماق نکالی، آگ سلگائی پھر دروازے کو جلا دیا۔ سیدنا سعد رضی اللہ عنہ کو معلوم ہوا۔ وہ باہر تشریف لائے، پھر قصہ ذکر کیا۔ ابن شاہین کا قول ہے: کہ قدیم صحابہ میں سے ہیں، مدینہ رہائش تھی پھر ربذہ یعنی سیدنا عثمان رضی اللہ عنہ کی شہادت کے بعد وہاں رہنے لگے۔\nواقدی رحمہ اللہ کا قول ہے: صفر ۴۳ھ میں مدینہ میں وفات پائی۔ ان کی عمر ستر(۷۰) برس تھی، مدائنی نے ان کی وفات کا سال ۴۳ھ بیان کیا ہے۔ ابن ابی داؤد کا قول ہے: اہل شام نے انہیں شہید کیا، اسی طرح یعقوب بن سفیان نے اپنی تاریخ میں فرمایا ہے، اہل شام میں سے اردن والوں میں سے ایک شخص ان کے پاس آیا وہ اپنے گھر میں تھے، اس نے آپ کو شہید کر دیا۔(8) محمد بن ربیع نے مصر کے صحابہ کا ذکر کرتے ہوئے فرمایا: سیدنا عمر رضی اللہ عنہ نے انہیں عمرو کے پاس مصر بھیجا، انہوں نے ان کا مال تقسیم کر دیا جس کا انہوں نے اپنی حدیث میں سنڈا ذکر کیا، پھر فرماتے ہیں: مدینہ میں ۴۳ھ میں وفات پائی۔ ان کی عمر ستر(۷۰) سال تھی۔ وہ دراز قد، مناسب اندام، سر کے گنجے تھے۔","",{"fn":"(1) اسد الغابہ (۴۷۶۱) استیعاب (۲۳۷۲) تجرید (۲/۶۲)\n(2) اسد الغابہ (۴۷۶۰) تجرید (۲/۶۱)\n(3) اسد الغابہ (۴۷۶۱) استیعاب (۲۳۷۲) تجرید (۲/۶۲)\n(4) السیرۃ النبویۃ (۲/۲۴۸)\n(5) مسند احمد (۴/۲۲۵) معجم کبیر (۱۹/۲۳۵) جامع المسانید والسنن (۱۱/۱۵۷) اسد الغابہ (۴/۸۲)\n(6) طبقات کبریٰ (۲/۱۸)\n(7) استیعاب (۳/۴۳۳)\n(8) ابوداؤد (۴۶۷۶) مسند احمد (۳/۴۹۳) مستدرک حاکم (۳/۴۲۴) طبرانی (۱۹/۴۹۷) معرفۃ الصحابہ (۳/۴۹۷)"}],[6437,"§۷۸۰۹ ۔ محمد بن نضلہ انصاری(1)\nابن مندہ نے ان کا ذکر کیا ہے۔ اور بطریق وہب بن جریر بن حازم، بحوالہ ان کے والد، انہوں نے محمد بن اسحاق(2) سے نقل کیا ہے، فرماتے ہیں: ان لوگوں میں سے ہیں جنہوں نے نبی کریم صلی اللہ علیہ وسلم کے ساتھ مدینہ ہجرت کی، یا ان کی طرف محمد اور عزز صاحبزادگان نضلہ نے ہجرت کی۔\nمیں کہتا ہوں: مخزم کا ذکر ہو چکا ہے کہ وہ اسدی ہیں، لیکن محمد کا نام مجھے صرف اسی طریق سے ملا ہے لگتا ہے ان کا \"انصاری\" کہنا وہم ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۶۴) تجرید (۲/۶۲)\n(2) السیرۃ النبویۃ (۲/۸۸)"}],[6438,"§۷۸۱۰ ۔ محمد بن ہشام(1)\nقاضی ابو احمد عسال نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابن مندہ نے ان کی حدیث نقل کی ہے بطریق ابن الحاد، بحوالہ محمد بن ہشام، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہاری آپس کی باتیں امانت ہوتی ہے، کسی مومن کے لیے حلال نہیں کہ دوسرے مسلمان کی پگڑی اچھالے\"۔(2)\nابو حسن بن براء کا قول ہے، میں نے علی بن مدینی کو فرماتے ہوئے سنا: یہ محمد بن ہشام مجہول ہیں، میں انہیں نہیں جانتا۔\nمیں کہتا ہوں: میں نے تاریخ بخاری میں ان سے روایت کرنے والے شخص کا ذکر نہیں دیکھا، گویا وہ راوی ہیں جنہوں نے اس حدیث کو مرسل روایت کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۶۵) تجرید (۲/۶۲)\n(2) اسد الغابہ (۴۷۶۵) تجرید (۲/۶۲)"}],[6439,"§۷۸۱۱ ۔ محمد بن ہلال(1)\nابن معطی، قداح نے ذکر کیا ہے کہ وہ فتح مکہ میں شریک تھے، اور یہ کہ نبی کریم صلی اللہ علیہ وسلم نے ان کا نام محمد رکھا تھا، اسے ابن شاہین نے، بحوالہ ابن ابی داؤد ان کے حوالے سے نقل کیا ہے۔","",{"fn":"(1) تجرید (۲/۶۲)"}],[6440,"§۷۸۱۲ ۔ محمد بن وحوح(1)\nابن اسلمت، ان کے بھائی حسین اور محصن میں ان کا نسب گزر چکا ہے۔ قداح نے ذکر کیا ہے کہ وہ فتح مصر میں شریک تھے، اور فتوح عراق میں بھی موجود تھے۔\nاسے ابن شاہین اور ابن ابی داؤد نے، بحوالہ قداح نقل کیا ہے، ابن کلبی رحمہ اللہ نے ذکر کیا ہے کہ حسین اور محصن قادسیہ میں شہید ہوئے، شاید یہ ان کے بھائی ہیں یا ان میں سے ایک کا نام محمد تھا۔","",{"fn":"(1) تجرید (۲/۶۲)"}],[6441,"§۷۸۱۳ ۔ محمد بن یغذیدویہ الہروی(1)\nالہروی۔ ابو اسحاق بن یاسین نے تاریخ ہرات میں ذکر کیا ہے۔ فرماتے ہیں: ہم سے ابراہیم بن علی بن بالویہ نے وہ فرماتے ہیں کہ ہم سے محمد بن مردان شاہ زنجانی نے روایت کیا، ان کا گمان ہے کہ وہ ثقہ ہیں، ان کی عمر ایک سو نو(۱۰۹) برس تھی۔ فرماتے ہیں کہ ہم سے احمد بن عبدہ جرجانی نے وہ فرماتے ہیں کہ ہم سے یفودان بن یغدیدویہ الہروی نے روایت کیا، فرماتے ہیں کہ میں نے اپنے شرک کی حالت میں رسول اللہ صلی اللہ علیہ وسلم سے جنگ کی تھی، اور پھر میں رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ پر مسلمان ہوا تو آپ صلی اللہ علیہ وسلم نے میرا نام محمد رکھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n\"جب دعا کم ہو جاتی ہے تو مصیبت نازل ہوتی ہے اور جب بادشاہ ظلم کرتا ہے تو آسمان سے بارش رک جاتی ہے۔۔۔۔ (الحدیث)\"۔(2)\nاسے ابو موسیٰ نے نقل کیا ہے اور مستغفری نے، بحوالہ محمد بن مردان شاہ نقل کیا ہے کہ ہم سے احمد بن عبدہ جرجانی نے اس سند سے مرفوعاً نقل کیا ہے:\n\"علم مومن کا دوست ہے اور عقل اس کی دلیل ہے\"۔(3)","",{"fn":"(1) اسد الغابہ (۴۷۶۷) تجرید (۲/۶۲)\n(2) لسان المیزان (۶/۱۱۲۳) جامع المسانید والسنن (۱۱/۲۶۷) اسد الغابہ (۴/۶۸)\n(3) کنز العمال (۲۸۶۶۳) اتحاف السادہ المتقین (۸/۴۹) مغنی عن حمل اسفار (۳/۱۸۲)"}],[6442,"§۷۸۱۴ ۔ محمد انصاری\nصحیح مسلم میں ان کا ذکر بروایت حماد بن سلمہ، بحوالہ سیدنا انس رضی اللہ عنہ مروی ہے، میں نے اس کے طرق سعد ودی کے سوانح میں، حرف سین میں نقل کیے ہیں۔ رباعیہ ابو عبیدہ رضی اللہ عنہ کا قول کہ ان کی حدیث کی سند ضعیف ہے، محمد نہیں۔"],[6443,"§۷۸۱۵ ۔ محمد دوسی\nان کے بارے میں تفصیل سعد دوسی کے سوانح میں گزر چکی ہے۔ ہو سکتا ہے کہ دونوں ناموں میں سے ایک ان کا لقب ہو، یا ایک نام دوسرے سے بدل گیا ہو۔"],[6444,"§۷۸۱۶ ۔ محمد ظفری\nابو حاتم کا قول: انہوں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا، بخاری رحمہ اللہ نے یقین سے لکھا ہے کہ وہ انس بن فضالہ ہیں۔"],[6445,"§۷۸۱۷ ۔ محمد مزنی(1)\nمہند کے والد ہیں، مطین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ نصر بن مزاحم نے، بحوالہ مہند بن محمد مزنی، انہوں نے اپنے والد کے حوالے سے نقل کیا ہے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دومرتبہ کا قرض ایک مرتبہ صدقے کی مانند ہے\"۔\nاسے باوردی نے، بحوالہ مطین نقل کیا ہے، اسی طرح ابو نعیم(2) کا قول ہے: ان کا صحابی ہونا صحیح سند سے ثابت نہیں، اور میرے خیال میں انہیں دیدار حاصل نہیں۔","",{"fn":"(1) تجرید (۲/۶۱)\n(2) معرفۃ الصحابہ (۲/۱۰۷)"}],[6446,"§۷۸۱۸ ۔ محمد (مولیٰ رسول اللہ صلی اللہ علیہ وسلم)(1)\nحاکم نے تاریخ نیسابور میں ان لوگوں میں ان کا ذکر کیا ہے جو خراسان آئے، فرماتے ہیں: مجھے علی بن احمد مروزی نے بحوالہ ابو عبد الرحمن عبد اللہ بن محمد بن مقاتل بن محمد بن موسیٰ بن محمد بن ابراہیم بن محمد، مولیٰ رسول اللہ صلی اللہ علیہ وسلم کہ مجھے میرے والد نے بحوالہ اپنے والد مقاتل بن محمد بتایا کہ ان کے والد محمد کا نام ماتا تھا، وہ مجوسی تھا، پھر جب انہوں نے نبی کریم صلی اللہ علیہ وسلم کا ذکر اور آپ صلی اللہ علیہ وسلم کا خطاب سنا تو وہ اپنے ساتھ تجارت کا سامان لے کر مدینہ آئے اور اسلام لے آئے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کا نام محمد رکھا، وہ مرو میں اپنے گھر ہو کر آئے، انہیں مولیٰ رسول اللہ صلی اللہ علیہ وسلم کہا جاتا تھا۔ فرماتے ہیں: مرو میں ان کا گھر جامع مسجد کے سامنے تھا، اسے ابو موسیٰ نے بطریق حاتم نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۲۳) تجرید (۲/۵۷)"}],[6447,"§۷۸۱۹ ۔ محمد (بے نسبت)(1)\nبغوی رحمہ اللہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، اور ابن شاہین نے ان کے حوالے سے بطریق سلام بن ابو صہباء، ثابت کے حوالے سے نقل کیا ہے۔ فرماتے ہیں: میں نے حج کیا، میں ایک ایسے حلقے میں گیا جس میں دو آدمی تھے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کا زمانہ پایا تھا، میرے خیال میں ان میں سے ایک آدمی کا نام محمد تھا، وہ وسوسے کے بارے میں حدیث بیان کر رہے تھے، ان دونوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے۔۔۔۔ پھر حدیث ذکر کی، اس میں ہے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ خالص ایمان ہے\"۔ ثابت کہنے لگے: میں نے کہا: اے کاش! اللہ تعالیٰ مجھے وہ خالص ایمان عطا فرمائیں۔ ان دونوں(2) نے مجھے ڈانٹا اور کہنے لگے: ہم تمہارے سامنے رسول اللہ صلی اللہ علیہ وسلم کی حدیث بیان کر رہے ہیں اور تم اس طرح کی بات کر رہے ہو؟ بغوی کا قول ہے، اس اسناد سے مجھے کوئی اور حدیث معلوم نہیں، یہ ترغیب حدیث ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۶۸)\n(2) مسند احمد (۶/۱۰۹) مسند ابو یعلیٰ (۸/۱۰۹) مجمع الزوائد (۱/۳۳)"}],[6448,"§۷۸۲۰ ۔ محمود بن ربیع(1)\nابن سراقہ بن عمرو بن زید بن عبدہ بن عامر بن عدی بن کعب بن حارث بن خزرج بن خزرج انصاری خزرجی۔ بعض نے کہا: وہ بنو حارث بن خزرج سے ہیں، بقول بعض: بنو سالم بن عوف سے ہیں، ابو عمر نے ان کے بارے میں انصاری خزرجی لکھنے کے بعد فرمایا: بنو عبد اشہل سے ہیں، وہ وہم ہے۔ کیونکہ بنو عبد اشہل اوس سے ہیں، ان کی کنیت کے بارے میں دو قول ہیں: ابو نعیم اور ابو محمد، دوسرا قول زیادہ ثابت ہے، معروف یہ ہے کہ ابو نعیم بن محمود بن ربیعہ کی کنیت ہے۔ بغوی رحمہ اللہ کا قول ہے: مدینہ کے رہائشی ہیں، ان سے مروی ہے کہ انہیں یاد ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے گھر میں ڈول سے پانی لے کر ان کے چہرے پر کلی کی تھی۔(2)\nاسے امام بخاری رحمہ اللہ نے کئی طرق سے، بحوالہ زہری رحمہ اللہ ان کے حوالے سے نقل کیا ہے، یہ روایت مسلم میں دو راوی حدیث ہے۔ اسے بغوی نے بطریق اوزاعی، بحوالہ زہری رحمہ اللہ، انہوں نے محمود سے روایت کیا ہے، فرماتے ہیں: مجھے وہ کلی بھولی نہیں جو رسول اللہ صلی اللہ علیہ وسلم نے ہمارے گھر کے کنوئیں سے میرے منہ پر کی تھی، بعض طرق سے مروی ہے: اور میں پانچ سال کا تھا۔ ابن حبان کا قول ہے: ان کی زیادہ تر روایات صحابہ رضی اللہ عنہم سے ہیں۔ ان کی والدہ جمیلہ بنت ابو صعصعہ ہیں، ابو سہر اور دوسرے راویوں کا قول ہے، محمود بن ربیع ۹۹ھ میں وفات پائی وہ تر انوے(۹۳) سال کے تھے۔ اسی طرح ابن حبان نے ان کی وفات کے بارے میں فرمایا، لیکن فرمایا: وہ چورانوے(۹۴) برس کے تھے، گویا وہ اس حدیث سے ماخوذ ہے، جسے طبرانی رحمہ اللہ نے بطریق محمود بن ربیع نقل کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم کی وفات ہوئی اور میں پانچ برس کا تھا۔","",{"fn":"(1) اسد الغابہ (۴۷۶۹) استیعاب (۲۳۷۳) تجرید (۲/۶۲)\n(2) بخاری (۷۷) ابن ماجہ (۷۵۴) مسند احمد (۵/۴۲۹)"}],[6449,"§۷۸۲۱ ۔ محمود بن ربیعہ(1)\nانصار کے ایک شخص ہیں، اہل مصر اور خراسان سے عورت کے بیعانے اور اس قرض کے بارے میں جو ادا نہ کیا جائے حدیث مروی ہے۔ اسی طرح ابن عبد البر(2) نے ان کا ذکر کیا ہے، اور اس پر اضافی نہیں کیا۔\nیہ میرے خیال میں محمود بن ربیع ہیں، دار قطنی رحمہ اللہ نے حدیث محکول کے بعض طرق میں، بحوالہ عبادہ بن صامت امام کے پیچھے قرأت کرنے کے بارے میں روایت نقل کی ہے، راوی اس میں فرماتے ہیں: بحوالہ محکول، انہوں نے نافع سے، انہوں نے محمود ابن ربیع سے، انہوں نے عبادہ بن صامت سے نقل کیا ہے۔ دوسری روایت میں ہے: بحوالہ نافع ہے، انہوں نے محمود بن ربیعہ سے نقل کیا ہے، اگر ایسا ہے تو یہ پہلے والے ہیں جیسا کہ احتمال ہے کہ وہ کوئی اور ہوں۔","",{"fn":"(1) اسد الغابہ (۴۷۷۰) استیعاب (۲۳۷۴) تجرید (۲/۶۲)\n(2) استیعاب (۳/۴۳۵)"}],[6450,"§۷۸۲۲ ۔ محمود بن عمیر(1)\nابن سعد انصاری۔ ابن شاہین وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق حجاج بن حجاج، بحوالہ محمود بن عمیر بن سعد روایت نقل کی ہے کہ عتبان بن مالک کی نبی کریم صلی اللہ علیہ وسلم کے زمانے میں نظر چلی گئی تھی، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی طرف پیغام بھیجا اور کہا: مجھے یہ پسند ہے کہ آپ میری نماز پڑھنے کی جگہ پر نماز ادا کریں، آپ اس جگہ آئے لوگوں نے مالک بن دخشم کا ذکر کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا وہ گواہی نہیں دیتا کہ اللہ کے سوا کوئی معبود نہیں اور یہ کہ محمد صلی اللہ علیہ وسلم اس کے بندے اور اس کے رسول ہیں؟\" لوگوں نے کہا: کیوں نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو بندہ بھی سچے دل سے ان دونوں کی گواہی دے اور اس پر فوت ہو، اللہ تعالیٰ اس پر آگ کو حرام کر دیئے ہیں۔\"(2) اس کے رجال ثقات ہیں۔ ابو نعیم کا قول ہے: اسے سعید بن بشیر نے، بحوالہ قتادہ روایت کیا ہے۔ اس کے آخر میں یہ اضافہ کیا ہے: \"اللہ تعالیٰ نے مجھ سے وعدہ کیا ہے کہ میری اُمت میں سے تین لاکھ افراد کو جنت میں داخل کریں گے۔۔۔۔\"۔ (الحدیث) اسے ابن مندہ نے سعید بن بشیر کی روایت سے، بحوالہ قتادہ فقط کے اضافے کے ساتھ نقل کیا ہے اور فرماتے ہیں: حجاج نے ان کی پیروی کی ہے اور ہشام نے ان دونوں کی مخالفت کی ہے۔ عمیر کی سوانح میں ہشام کی روایت گزر چکی ہے، وہ اس میں فرماتے ہیں: بحوالہ قتادہ، انہوں نے ابو بکر بن انس سے، انہوں نے ابو بکر بن عمیر سے، انہوں نے اپنے والد سے نقل کیا ہے۔ اسے طبرانی رحمہ اللہ نے دوسرے طریق سے، بحوالہ قتادہ نقل کیا ہے۔ فرماتے ہیں: بحوالہ نضر بن انس انہوں نے اپنے والد سے، انہوں نے عتبان سے نقل کیا ہے، دوسرے طریق سے ہے: بحوالہ ابو بکر بن انس، انہوں نے محمود بن ربیع سے، انہوں نے عتبان سے نقل کیا ہے، اس میں ہے کہ ابو بکر بن انس نے فرمایا: تو میں عتبان سے ملا، یہ سب زیادہ میں ہے، حدیث کا شروع حصہ زہری رحمہ اللہ کی روایت سے، بحوالہ محمود بن ربیع مروی ہے، انہوں نے عتبان سے روایت کی ہے، اسی طرح صحیحین میں منقول ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۷۲) تجرید (۲/۶۲)\n(2) مسند احمد (۳/۱۹۳) مجمع الزوائد (۱۰/۴۰۵)"}],[6451,"§۷۸۲۳ ۔ محمود بن لبید(1)\nابن رافع بن امری القیس بن زید بن عبد اشہل انصاری اوسی، اشہلی۔ امام بخاری رحمہ اللہ(2) کا قول ہے: انہیں شرف صحابیت حاصل ہے، پھر بطریق عاصم بن عمر بن قتادہ ان کے حوالے سے نقل کیا ہے، فرماتے ہیں: جس دن سیدنا سعد بن معاذ رضی اللہ عنہ کا انتقال ہوا تو آپ صلی اللہ علیہ وسلم نے اتنی جلدی کی کہ ہمارے جوتے تیز چلنے سے ٹوٹ گئے اس سے ظاہر ہوتا ہے کہ وہ اس میں حاضر تھے، یہ بھی احتمال ہے کہ انہیں مرسل نقل کیا ہو، ہمارے جوتوں سے مراد ان کی اس موقوف پر موجود لوگوں کے جوتے ہوں جو بنی عبد اشہل کے تھے، انہی سے سیدنا سعد بن معاذ رضی اللہ عنہ کا خاندان ہے۔\nامام احمد رحمہ اللہ(3) نے اپنی مسند میں بطریق محمد بن اسحاق ان کی حدیث نقل کی ہے کہ مجھ سے عاصم بن عمر بن قتادہ نے، بحوالہ محمود بن لبید نقل کیا ہے، فرماتے ہیں: ہمارے پاس نبی کریم صلی اللہ علیہ وسلم تشریف لائے اور ہمیں مسجد میں نماز پڑھائی۔ جب سلام پھیرا تو فرمایا: \"ان دو رکعتوں کو اپنے گھروں میں پڑھا کرو\"۔ یعنی صبح کی دو سنتیں اور مغرب کے بعد دو سنتیں۔\nابن عبد البر(3) کا قول ہے: محمود بن لبید، محمود بن ربیع سے بڑے ہیں، ابن خزیمہ نے ذکر کیا ہے کہ محمود بن ربیع ہی محمود بن لبید ہیں۔ کیونکہ محمود بن ربیع، لبید کے بیٹے ہیں، ان کے دادا کی طرف ان کی نسبت ہے، اس میں بعد ہے، خصوصاً اس وجہ سے کہ محمود ابن لبید اشہلی ہیں، اور اس قبیلے سے ہیں اور محمود بن ربیع خزرجی ہیں۔\nابن حبان رحمہ اللہ نے محمود بن لبید کا تابعین میں ذکر کیا ہے۔ فرماتے ہیں: مرسل احادیث روایت کرتے ہیں، پھر فرمایا: میں نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، کیونکہ انہیں دیدار حاصل ہے، اسی طرح فرمایا: بعض کا قول ہے کہ اس وجہ سے صحابہ رضی اللہ عنہم میں ان کا ذکر ہے کہ انہیں دیدار حاصل ہے۔ فرماتے ہیں: ان کی اکثر روایات صحابہ رضی اللہ عنہم سے مروی ہیں، اور پتے کی بات لکھی ہے کہ ان کی والدہ محمد بن سلمہ کی بیٹی ہیں۔","",{"fn":"(1) اسد الغابہ (۴۷۷۳) استیعاب (۲۳۷۴) تجرید (۲/۶۳)\n(2) التاریخ الکبیر (۷/۴۰۸)\n(3) مسند احمد (۵/۴۲۷) استیعاب (۳/۴۳۵)"}],[6452,"§۷۸۲۴ ۔ محمود بن مسلمہ(1)\nابن مسلمہ انصاری۔ محمد، جن کا تذکرہ ابھی گزرا ہے ان کے بھائی ہیں، ان کے بھائی کے سوانح میں قریب میں ان کا نسب گزر چکا ہے۔ انہوں نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ نبی کریم صلی اللہ علیہ وسلم کی حیاتِ مبارکہ میں شہید ہوئے۔ موسیٰ بن عقبہ نے مغازی میں، بحوالہ ابن شہاب یہ ذکر کیا ہے۔ اسی طرح ابو اسود نے، بحوالہ عمروہ نقل کیا ہے۔ اسی طرح محمد بن اسحاق وغیرہ نے ذکر کیا ہے، محمد بن اسحاق(2) خیبر کے قلعوں میں سے جو قلعہ سب سے پہلے فتح ہوا وہ قلعہ ناعم تھا۔ اس کے پاس محمود بن مسلمہ شہید ہوئے۔۔۔۔ چکی کا پاٹ ان پر گرا دیا گیا جس سے کچلے گئے۔ ابن کلبی رحمہ اللہ کا قول ہے: محمد بن مسلمہ پر قلعے سے ایک پتھر پھینکا گیا، جس سے ان کی آنکھیں غائب ہو گئیں، وہ پتھر مرحب نے پھینکا تھا۔ اس روح فرما منظر دیکھ کر آپ صلی اللہ علیہ وسلم ان کے بھائی کی طرف متوجہ ہوئے اور فرمایا: \"کل تمہارے بھائی کا قاتل قتل ہو جائے گا\"۔ چنانچہ ایسے ہی ہوا۔\nمغازی ابن عائذ وغیرہ میں ہے کہ نبی کریم صلی اللہ علیہ وسلم نے سیدنا زبیر بن عوام رضی اللہ عنہ کو حکم دیا، تو انہوں نے کتابت بن رافع بن ابی الحقیق بن محمد بن مسلمہ رحمہ اللہ کے حوالے کر دیا، انہوں نے انہیں قتل کر دیا۔ لوگوں کا کہنا ہے کہ کتابت نے محمود کو شہید کیا تھا۔ ابن سعد کا قول ہے: محمود اُحد، خندق، حدیبیہ اور خیبر میں شریک ہوئے اور اسی روز شہادت پائی، مرحب نے ان کے اوپر چکی کا پاٹ پھینکا تھا، جو ان کے سر پر لگا، جس سے ان کا سر کچل کر گیا اور ان کی پیشانی کٹ کے چہرے پر آ پڑی۔ اسی حالت میں رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچائے گئے، آپ صلی اللہ علیہ وسلم نے اس حصے کو واپس جوڑا تو وہ ویسا ہی ہو گیا جیسا تھا اور اوپر سے پٹی کر دی اس کے بعد محمد تین دن تک زندہ رہے پھر فوت ہوئے۔ محمد نے اسی دن جس میں محمود فوت ہوئے تھے مرحب کو قتل کیا تھا۔ سیدنا علی رضی اللہ عنہ محمد کی اس پر سترس کے بعد کھڑے رہے، محمود اور عامر بن اکوع کو ایک ہی قبر میں دفن کیا گیا۔(3)\nیونس بن بکیر کی زیادت مغازی میں حسین بن واقد سے، بحوالہ عبد اللہ بن بریدہ مروی ہے کہ مجھے میرے والد نے خبر دی، فرماتے ہیں: جب خیبر کا دن ہوا تو سیدنا ابو بکر رضی اللہ عنہ نے جھنڈا لیا اس کے بعد سیدنا عمر رضی اللہ عنہ نے لیا، لیکن ان کے ہاتھ پر فتح نہ ہوئیں محمود بن مسلمہ شہید ہوئے، یا امام احمد رحمہ اللہ کے نزدیک، بحوالہ زید بن حباب مروی ہے، انہوں نے حسین سے اسی مفہوم کی حدیث روایت کی ہے۔ اسے ابن مندہ نے عالی سند سے بطریق زید بن حباب نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۷۴) استیعاب (۲۳۷۶) تجرید (۲/۳۲)\n(2) ابن ہشام (۳/۲۵۷)\n(3) مسلم (۲۴۷۸) ابوداؤد (۲۹۸۵) نسائی (۲۶۱۸) المعجم الکبیر (۵/۴۰۶۶)"}],[6453,"§۷۸۲۵ ۔ محمدیہ(1)\nابن حمزہ بن عبد یغوث زبیدی، بنو تمیم کے حلیف ہیں، قریش سے ہیں، اسلام کے ابتدائی دور میں اسلام لائے اور حبشہ کی طرف ہجرت کی۔ نبی علیہ السلام کی طرف سے شمس وصول کرنے کے لیے مقرر تھے۔ صحیح مسلم میں اس سے ان کا ذکر حدیث عبد المطلب ابن ربیعہ بن حارث سے ثابت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم سے انہوں نے اور فضل بن عباس نے یہ عرض کی کہ انہیں صدقات کی وصولی پر مقرر کریں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ لوگوں کا میل کچیل ہے، میرے پاس محمد بن جزو کو بلاؤ\"۔ اور انہیں حکم دیا کہ وہ اپنی بیٹی کی شادی فضل بن عباس سے کر دیں اور انہیں حکم دیا کہ ان کی بیویوں کا مہر بھی ادا کریں۔۔۔۔ (الحدیث)(2) اس قصے کے ساتھ مغازی میں ہے: نبی کریم صلی اللہ علیہ وسلم نے ابو قتادہ سے خوبصورت لونڈی کا ہدیہ مانگا ہے اسے محمد بن جزو کو دے دیا۔ بعض کا قول ہے: وہ بدر میں شریک تھے، جیسا کہ ابن کلبی نے ذکر کیا، واقدی رحمہ اللہ کا قول ہے: سب سے پہلے غزوہ مریسیع میں شریک ہوئے۔ ابو سعید بن یونس کا قول ہے: مصر کی فتح میں شریک تھے۔ مجھے معلوم نہیں کہ انہیں دیدار حاصل ہو۔","",{"fn":"(1) اسد الغابہ (۴۷۷۶) استیعاب (۲۵۵۳) تجرید (۲/۶۳)\n(2) استیعاب (۴/۲۴) تجرید (۲/۶۳)"}],[6454,"§۷۸۲۶ ۔ محیریز بن جنادہ(1)\nابن وہب تجی، عبد اللہ کے والد ہیں۔ ذہبی رحمہ اللہ نے تجرید(2) میں اپنے استدراک میں ان کا ذکر کیا ہے۔ فرماتے ہیں:\nمیرے خیال میں مسلمانان فتح مکہ میں سے ہیں، تو ان کا بیٹا عبد اللہ کبار تابعین میں سے ہیں۔\nمیں کہتا ہوں: اذان کے بارے میں حدیث ابو محذورہ میں، میں نے اشارہ کیا ہے جو بروایت عبد اللہ بن محیریز مروی ہے کہ وہ یتیمی کی حالت میں سیدنا ابو محذورہ کی تربیت میں تھے جب وہ شام جانے لگے ابو محذورہ سے اذان کا طریقہ پوچھا.... اسے مسلم وغیرہ نے نقل کیا ہے۔ عبد اللہ بن محیریز فلسطین فروکش ہوئے۔ جب ان کے والد محیریز کا انتقال ہونے لگا تو ابو محذورہ کو ان کے بارے وصیت کر گئے۔ لیکن احتمال ہے کہ وہ اسلام لانے سے پہلے فوت ہوئے ہوں، اور عبد اللہ موجود ہوں یا ان کے بعد پیدا ہوئے ہوں اس لیے عبد اللہ قسم ثانی میں ہوئے۔ جس کسی نے بھی ان کے حالات لکھے ہیں کسی نے کوئی ایسی بات نہیں لکھی جس کا تقاضا ہو یہ عہد نبوی میں پیدا ہوئے اور ہم بار ہا نقل کر چکے ہیں کہ حجتہ الوداع کے موقع پر جو قریشی اور ثقفی زندہ رہا وہ اسلام لے آیا تھا اور اس میں شریک ہوا تھا لہذا اس کا تقاضا یہ ہے کہ محیریز اس قسم میں شامل ہوں۔","",{"fn":"(1) تجرید (۲/۶۳)\n(2) تجرید (۱۳۴)"}],[6455,"§۷۸۲۷ ۔ محیصہ بن مسعود انصاری اوسی(1)\nان کا ذکر اور نسب ان کے بھائی حویصہ کے حالات میں بیان ہو چکا ہے۔ محیصہ حویصہ سے چھوٹے تھے اور ان سے پہلے مسلمان ہوئے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲/۶۳)"}],[6456,"§۷۸۲۸ ۔ مخارق بن عبداللہ(1)\nبقول بعض: ابن سلیم الشیبانی، ابو قابوس کنیت تھی۔ اہل کوفہ میں شمار ہوتے ہیں۔ نبی صلی اللہ علیہ وسلم اور ابن مسعود اور ام الفضل بنت الحارث وغیرہ سے روایت کرتے ہیں۔\nجبکہ ان سے ان کے دونوں بیٹے قابوس اور عبد اللہ روایت کرتے ہیں۔(2) نسائی میں ان کی حدیث بروایت ابو الاحوص عن سماک بن حرب عن قابوس بحوالہ ان کے والد مروی ہے اور مسند حسن بن سفیان میں ان کی حدیث بطریق ابو بکر نہشلی عن سماک عن قابوس بن ابی المخارق بحوالہ ان کے والد منقول ہے اور ابو نعیم نے اسے کنیتوں میں ابو المخارق کے حالات میں نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۷۹) الاستیعاب (۲۵۵۵) تجرید اسماء الصحابہ (۲/۶۳)\n(2) نسائی، کتاب التحریم، باب ما یفعل من تعرض لمالہ (الحدیث: ۴۰۹۲)"}],[6457,"§۷۸۲۹ ۔ مخارق بن عبد اللہ البجلی(1)\nابو زکریا موصلی نے تاریخ موصل میں اور ابن الاثیر(2) رحمہ اللہ نے سابقہ لوگوں پر اپنے استدراک میں ان کا ذکر کیا ہے۔ اور بروایت ابو زکریا عن مغیرہ بن الخضر بن زیاد بن مغیرہ بن زیاد بجلی، انہوں نے اپنے والد سے بحوالہ اپنے بزرگوں سے روایت کی ہے کہ مخارق بن عبد اللہ جو مغیرہ بن زیاد کے دادا ہیں، سیدنا جریر بن عبد اللہ کے ساتھ ذی الخلصہ کی فتح میں شریک تھے۔ میں کہتا ہوں: فتح ذی الخلصہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں ہوئی۔ اس سند کے ساتھ اپنے شیوخ کے حوالے سے نقل کیا ہے کہ وہ کوفہ سے نکلیہ سے آنے والوں کے ساتھ موصل آئے یعنی موصل میں ٹھہرے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۷۷۸) تجرید اسماء الصحابہ (۲/۶۳)\n(2) اسد الغابہ (۴/۹۰)"}],[6458,"§۷۸۳۰ ۔ مخارق ہلالی(1)\nقبیصہ کے والد ہیں، علی بن سعید عسکری نے صحابہ میں ان کا ذکر کیا ہے۔ ابو موسیٰ نے ان کے حوالے سے اپنے استدراک میں ان کا ذکر کیا ہے کہ مجھے ابو اسحاق جریری نے بحوالہ حرب بن قبیصہ بن مخارق ہلالی، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم ان کے پاس سے گزرے اس وقت ان کی ران سے کپڑا ہٹا ہوا تھا: \"اپنی ران چھپاؤ، یہ ستر ہے۔\" سوار(2) اس روایت کے نقل کرنے میں متفرد ہیں، اسے علی بن سعید نے بحوالہ احمد بن اسحاق نقل کیا ہے، ہمیں یہ حدیث عالی سند کے موافق ملی ہے۔ علائی نے وحی میں فرمایا: مجھے صحابہ میں حرب کا ذکر نہیں ملا، شاید سوار کو اس میں وہم ہوا ہے۔ دارقطنی کا قول ہے: ان کی حدیث کی اتباع کوئی نہیں کرتا لیکن ابن معین نے اسے ثقہ کہا ہے۔ علائی نے وحی المعلم میں فرمایا: اس سے نقل کرنے والے راوی کو میں نہیں جانتا۔","",{"fn":"(1) اسد الغابہ (۴۷۸۰) تجرید (۲/۶۳)\n(2) مستدرک حاکم (۴/۱۸۰)"}],[6459,"§۷۸۳۱ ۔ مخاشن(1)\nحمیری، انصار کے حلیف ہیں۔ ابن عبد البر(2) نے ان کا ذکر کیا ہے، فرماتے ہیں: یمامہ کے دن شہید ہوئے۔ ابن فتحون نے یقین کیا ہے کہ وہ شخشی بن تمیر ہیں، جن کا ذکر آ رہا ہے، میرے نزدیک احتمال ہے کہ وہ کوئی اور ہیں۔","",{"fn":"(1) اسد الغابہ (۴۷۸۱) استیعاب (۲۵۵۶) تجرید (۲/۶۳)\n(2) استیعاب (۴/۲۶)"}],[6460,"§۷۸۳۲ ۔ مخبل سعدی\nربیع بن ربیعہ میں ان کا ذکر گزر چکا ہے، قسم ثالث میں بھی ان کا ذکر آئے گا۔"],[6461,"§۷۸۳۳ ۔ مختار بن حارثہ(1)\nانصاری سلمی، ابو بکر بن ابی علی ذکوانی نے ان کا ذکر کیا ہے، مغازی ابن اسحاق میں ان کا ذکر ہے، ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔\nمیں کہتا ہوں: عمر بن شبہ نے بنو سلمہ میں سے عقبہ میں حاضر ہونے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۸۳) تجرید (۲/۶۴)"}],[6462,"§۷۸۳۴ ۔ المختار بن عدی\nابن نوفل بن مناف، ماوردی نے ان کا ذکر کیا ہے۔ ان سے مرفوع حدیث مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان کا اور عمرو بن سمرہ کا چوری میں ہاتھ کاٹنے کا حکم دیا تھا۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے، خیار بن عدی کے بھائی ہیں، عبد اللہ کے بھائی ہیں جن کا حرف عین، قسم ثانی میں ذکر ہے۔"],[6463,"§۷۸۳۵ ۔ مختار بن قیس(1)\nابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے، فرماتے ہیں: وہ اس خط کے لکھنے کے وقت موجود تھے جو نبی علیہ السلام نے علاء بن حضرمی کو لکھوایا تھا۔\nمیں کہتا ہوں: مسند حارث بن ابو اسامہ میں، شعیب بن قرہ کے حالات میں اس خط کا ذکر گزر چکا ہے، اس کی سند بہت ضعیف ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۸۵) تجرید (۲/۴۶)"}],[6464,"§۷۸۳۶ ۔ مخربہ\nابن بشر، بنو عید بن صبرہ بن دکل بن قیس بن رئاب بن زید عبدی سے ہیں: ابو عبیدہ معمر بن مثنی کا قول ہے، جاہلیت میں شریف، شہسوار اور سخی تھے۔ ان کا نام مخربہ رکھا گیا کیونکہ جاہلیت میں ہتھیاروں نے انہیں خراب کر دیا تھا۔\nفرماتے ہیں: انہوں نے اسلام کا زمانہ پایا، وفد عبد القیس میں نبی کریم صلی اللہ علیہ وسلم کے پاس آئے، نبی کریم صلی اللہ علیہ وسلم نے ان سے عثمان کے بارے میں سوال کیا، آپ کو مخربہ نے بتایا کہ انہیں اس کے بارے میں علم ہے، اور کہا: اہل عمان خوشی سے اسلام لے آئے، اسے رشاطی نے انساب میں ابو فرج اصبہانی نے آغانی میں اسے نقل کیا ہے۔ وہ مخربہ کے علاوہ ہیں، جن کا ذکر بھی آئے گا۔"],[6465,"§۷۸۳۷ ۔ مخربہ بن عدی(1)\nحارثہ بن عدی کے بھائی ہیں، ان کے بھائی کا ذکر گزر چکا ہے۔ عبدان مروزی(2) رحمہ اللہ نے صحابہ میں ان کا ذکر کیا ہے، ابن فتحون نے ذیل میں بحوالہ مغازی ابن اسحاق، بروایت ابن ہشام اور اموی نے ان سے نقل کیا ہے۔ فرماتے ہیں: واقدی، طبری رحمہ اللہ نے ان کا ذکر کیا ہے، اور بطریق اسحاق بن سوید، بحوالہ جعفر بن عصیمہ بن کمیل بن وبرہ بن حارثہ بن امیہ سے مسند روایت کیا ہے کہ میں نے اپنے دادا عصمہ سے سنا وہ اپنے آباء واجداد سے بحوالہ حارثہ بن عدی نقل کرتے ہیں، فرماتے ہیں: میں اور میرا بھائی مخربہ بن عدی ان لوگوں میں تھے جو وفد میں نبی کریم صلی اللہ علیہ وسلم کے پاس گئے تھے، آپ علیہ السلام کے لشکر نے ہم پر حملہ کر دیا تھا تو ہم نے اپنی مصیبت کی آپ سے شکایت کی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جاؤ! اور جو تمہیں سب سے پہلے اپنا اونٹ ملے، اسے نحر کرو اور بسم اللہ کے ساتھ اللہ کا نام لو، جو اسے کھا لے، اسے آزاد کر دو۔\"\nابو موسیٰ نے ذیل میں فرمایا: ابن ماکولا(3) نے فرمایا: را کے ساتھ ہے، اور وہ راجح ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۸۵) تجرید (۲/۶۴)\n(2) اسد الغابہ (۴۷۸۶) استیعاب (۲۵۵۸) تجرید (۲/۶۴)\n(3) الاکمال (۷/۶۳)"}],[6466,"§۷۸۳۸ ۔ مخرش کعبی\nقریب میں گزر چکے ہیں۔"],[6467,"§۷۸۳۹ ۔ مخرقہ عبدی(1)\nابن حبان(2) کا قول ہے انہیں شرف صحابیت حاصل ہے۔\nمیں کہتا ہوں: حدیث سوید بن قیس میں ان کا ذکر گزر چکا ہے۔ فرماتے ہیں: میں اور مخرقہ یا مخرمہ عبدی(3)\nپھر حدیث ذکر کی اسے بغوی(4) نے نقل کیا ہے اور اسے ابن قانع نے اپنے طریق سے نقل کیا ہے، فرماتے ہیں: بحوالہ مخرمہ، دارقطنی رحمہ اللہ کا قول ہے: ایوب کو اس میں وہم ہوا ہے، ابن سکن رحمہ اللہ کا قول ہے، انہوں نے کچھ نہیں کیا، اسے ابن قانع نے اسی طرح نقل کیا ہے، بروایت سفیان، بحوالہ سماک، انہوں نے ان کے اور مخرمہ کے درمیان ملیح عنزی کا اضافہ کر دیا ہے، ان کی سند میں مسیب بن واضح ہیں۔ اس میں کلام ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۸۸) استیعاب (۲۵۶۰) تجرید (۲/۶۴)\n(2) صحیح ابن حبان (۵۱۴۷)\n(3) المعجم الکبیر (۲۰/۷۶۱)\n(4) ترمذی (۱۳۰۵) ابوداؤد (۳۳۳۶) نسائی (۴۶۰۶) ابن ماجہ (۲۲۲۰) مستدرک حاکم (۲/۳۰) سنن دارمی (۲/۷۱۲) المعجم الکبیر (۷/۴۶۶)"}],[6468,"§۷۸۴۰ ۔ مخرمہ بن شریح حضرمی\nشریح حضری کے تحت بیان ہو چکا ہے۔"],[6469,"§۷۸۴۱ ۔ مخرمہ بن قاسم(1)\nابن مخرمہ بن مطلب قرشی مطلبی، ابن اسحاق(2) نے مغازی میں ان کا ذکر کیا ہے، فرماتے ہیں: یہ ان لوگوں میں سے ہیں جنہیں نبی کریم صلی اللہ علیہ وسلم نے خیبر کی کھجوروں میں سے عطا کیا، فرماتے ہیں: ابن قاسم بن مخرمہ کو تیس(۳۰) وسق دیئے اور ان کا نام نہیں لیا۔ زبیر بن بکار نے ان کا نام لیا ہے، فرماتے ہیں: چالیس(۴۰) وسق دیئے۔","",{"fn":"(1) اسد الغابہ (۴۷۹۰) تجرید (۲/۶۴)\n(2) سیرۃ النبویہ (۳/۲۷۲)"}],[6470,"§۷۸۴۲ ۔ مخرمہ بن نوفل(1)\nابن اہیب بن عبد مناف بن زہرہ بن کلاب، ابو صفوان اور ابو مسور زہری، ان کی والدہ رقیقہ بنت ابو صیفی بن ہاشم بن عبد مناف بن زہرہ بن کلاب، مشہور صحابی مسور بن مخرمہ کے والد ہیں۔ زبیر بن بکار کا قول ہے۔ فتح مکہ کے موقع پر اسلام لائے، ان کی لمبی عمر تھی اور ان کے پاس علم الانساب تھا، لوگ ان سے یہ علم حاصل کرتے تھے۔(2)\nابن سعد نے اضافہ کیا ہے، انہیں حرم کی حدود پر رکھے پتھروں کا علم تھا، سیدنا عمر رضی اللہ عنہ نے انہیں سعید بن یربوع، ازہر بن عبد عوف، حویطب بن عبد العزی کو بھیجا، انہوں نے اس کی تجدید کی، اور یہ ذکر کیا ہے، انہیں سیدنا عثمان رضی اللہ عنہ نے بھی بھیجا تھا۔(3)\nاما زبیر بن بکار نے سیدنا ابن عباس رضی اللہ عنہما کی حدیث سے نقل کیا ہے کہ حضرت جبرائیل علیہ السلام نے حضرت ابراہیم علیہ السلام کو حرم کے پتھروں کے بارے میں بتایا تو انہوں نے وہ وہاں رکھ دیئے۔ پھر حضرت اسماعیل علیہ السلام نے اس کی تجدید کی، پھر قصی بن کلاب نے ان کی تجدید کی، پھر نبی کریم صلی اللہ علیہ وسلم نے اس کی تجدید کی، پھر سیدنا عمر رضی اللہ عنہ نے چار مذکورہ اشخاص کو بھیجا انہوں نے اس کی تجدید کی۔(4)\nاس حدیث کی سند میں عبد العزیز بن عمران ہے، اس میں ضعف ہے۔ ابو سعید بن اعرابی نے اپنے معجم میں بطریق عبد العزیز ابن عمران بحوالہ ابو حویصہ نقل کیا ہے، فرماتے ہیں: مخرمہ بن نوفل، اپنی والدہ رقیقہ بنت ابو صیفی جو عبد المطلب بن ہاشم کی ہم عمر تھیں سے نقل کرتے ہیں، فرماتے ہیں: قریش پر لگا تار کتنی قحط آئے، پھر عبد المطلب کے پانی طلب کرنے کا قصہ ذکر کیا، اس میں رقیقہ کے اشعار ہیں، جن کا مطلع یہ ہے: \"شیبہ الحمد کی وجہ سے اللہ تعالیٰ نے ہمیں سیراب کیا\"۔ ہمیں یہ قصہ ذکریا بن یحیی طائی کے قصے میں ان کی روایت سے بحوالہ ان کے والد کے چچا زحر بن حصن سے ملا ہے۔ انہوں نے اپنے دادا حمید بن منہب سے روایت کیا ہے کہ ہم سے میرے چچا عروہ بن مفرس نے بیان کیا فرماتے ہیں: مخرمہ بن نوفل نے ذکر کیا۔ پھر اسے طویل ذکر کیا.... ہم نے امالی ابو قاسم، عیسی بن علی بن جراح میں عالی سند سے یہ روایت ملی ہے، عباس دوری نے تاریخ یحیی بن معین میں اور طبرانی نے بطریق ابن لہیعہ بحوالہ مسور بن مخرمہ، انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم نے اسلام کا اظہار کیا تو تمام اہل مکہ اسلام لے آئے یہاں تک کہ اگر نبی کریم صلی اللہ علیہ وسلم آیت سجدہ پڑھتے تو تمام لوگ سجدہ کرتے، بعض لوگ ہجوم کی وجہ سے سجدہ نہ کر سکتے تھے یہاں تک کہ قریش کے رؤساء ابو جہل بن ہشام، اس کے چچا ولید بن مغیرہ وغیرہ آگئے، وہ لوگ طائف میں تھے، انہوں نے کہا: تم لوگ اپنے آباء کا دین چھوڑنے لگے ہو؟ تو انہوں نے دوبارہ کفر اختیار کر لیا۔\nابن اسحاق رحمہ اللہ نے مغازی میں فرمایا: مجھ سے عبد اللہ بن ابو بکر بن حزم وغیرہ نے بیان کیا، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے حنین کے غنائم میں سے قریش کے ایک شخص کو تالیف قلب کے لیے سو(۱۰۰) سے کم اونٹ دیئے، پھر انہوں نے ان میں مخرمہ بن نوفل کا ذکر کیا۔\nواقدی وغیرہ نے ذکر کیا ہے کہ آپ صلی اللہ علیہ وسلم نے انہیں پچاس اونٹ دیئے۔ بخاری رحمہ اللہ نے صحیح میں بطریق لیث بحوالہ ابن ابو ملیکہ سیدنا مسور بن مخرمہ سے نقل کیا ہے کہ ان کے والد نے ان سے فرمایا: اے بیٹے! مجھے معلوم ہوا ہے کہ نبی علیہ السلام کے پاس قبائیں آئی ہیں جنہیں آپ صلی اللہ علیہ وسلم تقسیم کر رہے ہیں۔ مجھے بھی لے چلو چنانچہ ہم چل پڑے، نبی علیہ السلام کو اپنے گھر پایا۔ مجھے کہنے لگے: بیٹا! رسول اللہ صلی اللہ علیہ وسلم کو میرے لیے بلا دو، مجھے یہ بات بڑی گراں گزری۔ میں نے کہا: ہیں! آپ کے لیے رسول اللہ صلی اللہ علیہ وسلم کو بلاؤں!؟ کہنے لگے: بیٹا! وہ سخت نہیں ہے۔ چنانچہ میں نے آپ صلی اللہ علیہ وسلم کو بلایا۔ آپ صلی اللہ علیہ وسلم باہر تشریف لائے، ریشمی قبازیب تن کر رکھی تھی جس میں سونے کے تار تھے۔ فرمانے لگے: بمخرمہ! ہم نے یہ تمہارے لیے چھپا رکھی تھی، چنانچہ پھر وہ انہیں عطا کر دی۔(5)\nاس حدیث کے ابن ابی ملیکہ سے مروی کئی طرق ہے۔ کسی میں ہے کہ انہوں نے نبی علیہ السلام سے کہا: مجھے یاد نہیں پڑتا کہ آپ نے قریش میں کوئی چیز تقسیم کی ہو اور مجھے محروم رکھا ہو۔ بغوی اور ابو یعلی نے دنیا کی کتابوں میں بطریق صالح بن حاتم بن مردان عن ابیہ عن ایوب عن ابن ابی ملیکہ پہلی حدیث کا مفہوم منقول ہے، اور یہ اضافہ نقل کیا ہے۔ میں نے حاتم سے کہا: آپ علیہ السلام نے ایسا کیوں کیا؟ کہنے لگے: آپ ان کی زبانی باتوں سے بچنا چاہتے تھے۔(6)\nزبیر بن بکار فرماتے ہیں کہ مجھ سے مصعب بن عثمان وغیرہ نے بیان کیا کہ مسور بن مخرمہ اپنے والد کے پاس سے گزرے تو وہ کسی شخص سے جھگڑ رہے وہ کہنے لگا ابو صفوان! لوگوں سے انصاف کرو، کہنے لگے: یہ کون ہے؟ کہا: جو تمہارا خیر خواہ ہے اور تمہیں دھوکا نہیں دے گا۔ مسور نے کہا: انہوں نے کہا: ٹھیک ہے، انہوں نے اپنے ہاتھ سے ان کے کپڑے سے اشارہ کیا اور کہا: مجھے مکہ لے جاؤ میں تمہیں اپنی والدہ کا گھر دکھاتا ہوں اور تم مجھے اپنی والدہ کا گھر دکھاؤ، یہ کہنے لگے: ابا جان! اللہ آپ کی بخشش کرے، میری عزت آپ کی عزت ہے۔\nمسور کی والدہ عاتکہ بنت عوف، عبد الرحمن کی بہن تھیں اور اسی سند سے فرماتے ہیں: جب مخرمہ کی وفات کا وقت ہوا تو ان کی بیٹی رو کر کہنے لگی: ہائے ابا جان! وہ نرم طبیعت انسان تھے، افاقہ ہوا تو کہنے لگے: نوحہ کون کر رہی تھی؟ لوگوں نے بتایا: آپ کی بیٹی! انہوں نے کہا: ادھر آؤ! کیا میرا بین اس طرح ہوگا؟ کہو ہائے ابا! وہ تیز خاطر اور دراز قد تھے۔ وہ نافرمان اور حکم عدول تھے۔ زبیر فرماتے ہیں: اور مجھ سے عبد الرحمن بن عبد نے بیان کیا ہے کہ زہری رحمہ اللہ نے فرمایا کہ سیدنا امیر معاویہ رضی اللہ عنہ فرماتے ہیں: مخرمہ بن نوفل سے مجھے کون بچائے گا، آئے دن وہ اپنی زبان سے میری توہین کرتا رہتا ہے؟ تو عبد الرحمن بن ازہر نے ان سے کہا: امیر المومنین! میں آپ کو اس کے شر سے بچانے کے لیے کافی ہوں۔ اور مخرمہ کو یہ بات معلوم ہوئی تو کہنے لگے: عبد الرحمن نے مجھے اپنی گود کا یتیم سمجھا ہوا ہے۔ اس کا خیال ہے کہ وہ معاویہ کے لیے میرے مقابلے میں کافی ہے تو ابن برصا علیہ السلام نے ان سے کہا: کہ وہ عبد الرحمن بن الازہر ہے۔ انہوں نے اپنے ہاتھ میں لیا ہوا ڈھال اس شخص کے سر پر مارا اور اس کا سر زخمی کر دیا اور کہنے لگے: جاہلیت میں ہمارے دشمن اور اسلام میں ہمارے حاسد ہیں۔ بغوی رحمہ اللہ کی روایت بطریق حماد بن سلمہ عن ایوب عن ابن ابی ملیکہ ہے۔ فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے مخرمہ بن نوفل سے فرمایا: اے ابو مسور!(7)\nابن سعد، خلیفہ، ابن برقی اور دوسرے راویوں نے کہا: ۵۴ھ میں وفات پائی۔ واقدی رحمہ اللہ کا قول ہے: ۵۵ھ میں وفات پائی، کہتے ہیں: ایک سو پندرہ(۱۱۵) برس زندہ رہے، نابینا تھے، نعیمان کے سوانح میں ان کا قصہ مذکور ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۹۱) استیعاب (۲۳۷۸) تجرید (۲/۶۴)\n(2) جامع المسانید والسنن (۱۱/۱۹۴، ۱۹۵)\n(3) المعجم الکبیر (۲۰/۶۰) طبقات الکبریٰ (۲/۱۵۳) مختصر تاریخ دمشق (۲۴/۱۴۰)\n(4) اسد الغابہ (۴/۹۳)\n(5) بخاری کتاب الہبہ (۲۵۹۹) مسلم کتاب الزکوۃ (۲۴۲۹) ابوداؤد کتاب اللباس (۴۰۲۸) ترمذی کتاب الادب (۲۸۱۸) نسائی کتاب الزینہ (۵۳۳۹) المستدرک (۳/۴۹۰)\n(6) المعجم الکبیر (۱/۲۰) جامع المسانید والسنن (۱۱/۱۹۵)\n(7) طبقات الکبریٰ (۲/۱۵۳) (۳/۲۹۵)"}],[6471,"§۷۸۴۳ ۔ مخشی(1)\nابن حمیر، اشجعی، مغازی ابن اسحاق میں غزوہ تبوک کے حوالے سے ان کا تذکرہ ہے۔ تفسیر ابن کلبی رحمہ اللہ میں ان کی سند سے مجھے وہ سیدنا ابن عباس رضی اللہ عنہما تک پہنچاتے ہیں، اور دوسری سند سے وہ ابن مسعود رضی اللہ عنہ تک پہنچاتے ہیں کہ وہ ان لوگوں میں سے ہیں جن کے بارے میں یہ آیت نازل ہوئی:\n﴿وَلَئِنْ سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ﴾(2)\nیعنی اگر آپ ان سے پوچھیں تو یہ یہی جواب دیں گے ہم تو بس ایسے ہی سخت مباحثہ اور ہنسی مذاق کی باتیں کر رہے تھے۔\nفرماتے ہیں: مخشی بن وبرہ ان لوگوں میں سے تھے جنہیں اللہ تعالیٰ نے معاف کیا، انہوں نے فرمایا: یا رسول اللہ صلی اللہ علیہ وسلم! میرا اور میرے والد کا نام بدل دیجئے، تو آپ صلی اللہ علیہ وسلم نے ان کا نام عبد اللہ بن عبد الرحمن رکھ دیا۔ مخشی نے اپنے رب سے دعا کی کہ وہ اس طرح شہید ہوں کہ ان کے بارے میں کچھ پتہ نہ چلے۔ وہ یمامہ میں شہید ہوئے، ان کا کسی کو نام و نشان نہ ملا۔(3)","",{"fn":"(1) اسد الغابہ (۴۷۹۲) استیعاب (۲۳۷۹) تجرید (۲/۶۴)\n(2) سورۃ التوبہ الآیۃ (۶۵)\n(3) اسد الغابہ (۴/۹۴)"}],[6472,"§۷۸۴۴ ۔ مخشی بن وبرہ(1)\nابن یحنس خزاعی۔ ابو عمر(2) کا قول ہے: رسول اللہ صلی اللہ علیہ وسلم نے انہیں یمن میں مقیم نوجوان کی طرف بھیجا۔ یمن میں وبرہ کے سوانح میں ان کا ذکر ہے کہ وہ قاصد تھے۔","",{"fn":"(1) اسد الغابہ (۴۷۹۳) استیعاب (۲۳۸۰) تجرید (۲/۶۴)\n(2) استیعاب (۳/۴۳۷)"}],[6473,"§۷۸۴۵ ۔ مخلد\nابن ثعلبہ بن صخر بن حبیب بن حارث بن ثعلبہ بن مازن بن نجار انصاری، اموی نے ان کا ذکر بحوالہ ابن اسحاق کیا ہے کہ بدر میں شریک تھے۔ بغوی رحمہ اللہ نے اسے بحوالہ اموی نقل کیا ہے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[6474,"§۷۸۴۶ ۔ مخلد بن عمرو\nابن جموح بن زید بن حرام بن کعب بن غنم بن کعب بن سلمہ بن سعد بن علی بن اسد بن ساردہ انصاری سلمی، ابن عساکر(1) نے اپنی تاریخ میں ان کا ذکر کیا ہے۔ فرماتے ہیں: غزوہ موتہ میں شریک تھے، پھر بطریق ابو بشر دولابی اپنی سند سے جسے وہ ابو طاہر عبد الملک بن محمد بن ابی بکر بن عمرو بن حزم تک پہنچاتے ہیں، انہوں نے اپنے چچا عبد اللہ بن ابی بکر سے نقل کیا ہے، فرماتے ہیں: موتہ کے دن شہید ہوئے، بنو سلمہ مخلد بن عمرو بن جموح سے ہیں، فرماتے ہیں: ان کی اولاد نہیں۔","",{"fn":"(1) مختصر تاریخ دمشق (۲۴/۱۴۵)"}],[6475,"§۷۸۴۷ ۔ مخلد غفاری(1)\nبغوی اور ابن ابی عاصم(2) وغیرہ نے ان کا ذکر کیا ہے۔ بغوی رحمہ اللہ کا قول ہے: مکہ میں رہائش اختیار کی، بخاری رحمہ اللہ(3) کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ ابن ابی حاتم(4) نے اس کا انکار کیا ہے۔ فرماتے ہیں: انہیں شرف صحابیت حاصل نہیں۔ میں کہتا ہوں: میں نے تاریخ میں انہیں تابعین کے ساتھ دیکھا ہے۔ عسکری نے نقل کیا ہے کہ اسے تشدید کے ساتھ لکھا گیا ہے۔ انہوں نے تخفیف کے ساتھ درست قرار دیا ہے۔ ابن ابی عاصم، بغوی، ابن قانع ہیں کہ ہم نے بطریق عمرو بن دینار عن حسن، عن محمد ابن حنفیہ، عن مخلد غفاری نقل کیا ہے کہ بنو غفار کے تین غلام رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بدر میں شریک تھے، سیدنا عمر رضی اللہ عنہ ہر سال ان میں سے ہر شخص کو تین ہزار عطا کرتے تھے۔ عمرو بن دینار کا قول ہے: میں نے مخلد کو دیکھا ہے۔(5)","",{"fn":"(1) اسد الغابہ (۴۷۹۴) استیعاب (۲۵۶۱) تجرید (۲/۶۴)\n(2) الاحاد والمثانی (۲/۲۵۶)\n(3) تاریخ کبیر (۷/۴۳۶)\n(4) جرح والتعدیل (۳۴۴۸)\n(5) المعجم الکبیر (۲۰/۳۶۶) مجمع الزوائد (۹۷۷۵)"}],[6476,"§۷۸۴۸ ۔ مخمر بن معاویہ قشیری\nحکیم بن معاویہ کے سوانح میں ان کا ذکر ہے۔"],[6477,"§۷۸۴۹ ۔ مخنف بن زید نکری(1)\nابن سکن رحمہ اللہ نے ان کا ذکر کیا ہے، فرماتے ہیں: بعض کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ وہ غیر معروف ہیں، پھر بطریق عبد الرحمن بن عمرو بن جبلہ ان کی حدیث نقل کی ہے، فرماتے ہیں کہ انہوں نے کہا کہ ہم سے جبہ بنت ہشام نکریہ، وہ فرماتی ہیں کہ مجھ سے سنینہ بنت مخنف بن زید نکریہ نے بحوالہ اپنے والد روایت کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اے مخنف! صلہ رحمی کرو تمہاری عمر دراز ہوگی اور نیکیاں کرو تمہارے گھر میں برکت زیادہ ہوگی۔\" (الحدیث) عبد الرحمن، ابن سکن وہ یہ فرماتے ہیں: ان کی روایت میں تردد ہے۔ دوسرے راویوں نے کہا: وہ متروک ہیں۔ اسے ابن شاہین نے اس طریق سے نقل کیا ہے، لیکن ان کی روایت میں فرمایا: مجھ سے سنینہ بنت مخنف بن زید نے بحوالہ اپنے والد فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اے مخنف!....\"۔ پھر اسے ذکر کیا اور یہ اضافہ کیا: \"ہر پتھر اور ڈھیلے کے پاس اللہ کا ذکر کرو وہ تمہارے لیے قیامت کے دن گواہی دے گا۔\"(2)\nکتاب النساء میں اس سند سے دوسری طویل حدیث آئے گی جس سے مذکورہ سنینہ کے صحابیہ ہونے کا پتہ چلتا ہے، اور ان کے یہ والد سیدنا امیر معاویہ رضی اللہ عنہ کی خلافت میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۴۷۹۶) تجرید (۲/۶۵)\n(2) کنز العمال (۴۳۳۹۳) جامع المسانید والسنن (۱۱/۲۰۰)"}],[6478,"§۷۸۵۰ ۔ مخنف بن سلیم(1)\nابن حارث بن عوف بن ثعلبہ بن عامر بن ذیل بن مازن بن ذبیان بن ثعلبہ ازدی غامدی، ابن کلبی رحمہ اللہ کا قول ہے: وہ کوفہ اور بصرہ کے ازد قبیلے سے ہیں، ان کی اولاد سے ابو مخنف لوط بن یحیی بن سعید بن مخنف بن سلیم ہیں فرماتے ہیں: انہیں شرف صحابیت حاصل ہے۔ ان کی حدیث سنن اربعہ کی کتابوں میں بطریق عبد اللہ بن عون بحوالہ مخنف بن سلیم ہے، فرماتے ہیں: \"ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عرفات میں ٹھہرے ہوئے تھے، آپ صلی اللہ علیہ وسلم نے فرمایا: ہر گھر والوں پر ہر سال قربانی واجب ہے۔ (الحدیث)(2) ترمذی کا قول ہے: یہ غریب حدیث ہے ہم اسے حدیث عبد اللہ بن عوف سے جانتے ہیں۔\nمیں کہتا ہوں: اسے بغوی نے بطریق سلیمان تیمی بحوالہ مخنف بن سلیم یا سلیم بن مخنف روایت کیا ہے، لیکن بغوی کا قول ہے: جس شخص کا نام نہیں لیا گیا میرے نزدیک وہ عبد اللہ بن عوف ہیں۔","",{"fn":"(1) اسد الغابہ (۴۷۹۷) استیعاب (۲۵۶۳) تجرید (۲/۶۵)\n(2) ترمذی (۱۵۱۸) نسائی (۴۲۳۵) ابن ماجہ (۳۱۲۵)"}],[6479,"§۷۸۵۱ ۔ مخول بن یزید سلمی(1)\nپھر بہزری۔ ابن سکن رحمہ اللہ کا قول ہے: مکہ میں رہائش اختیار کرنے والوں میں ہیں، ابو یعلی(2) نے بطریق محمد بن سلیمان ابن مسمول بحوالہ قاسم بن مخول بہزری روایت کیا ہے کہ انہوں نے اپنے والد کو فرماتے سنا: میں نے ابواء مقام پر جال لگایا تو اس میں ہرن پھنس گیا، پھر وہ بھاگ گیا میں نے اس کا پیچھا کیا تو میں نے دیکھا کہ ایک شخص نے اسے پکڑ لیا ہے، ہم اس کے بارے میں اپنا جھگڑا لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے۔ آپ صلی اللہ علیہ وسلم نے ہمارے درمیان آدھا آدھا کرنے کا فیصلہ کیا۔ اور مجھ سے فرمایا: \"نماز قائم کرو، زکوۃ دو، حج اور عمرہ کرو، جس طرف حق پھر جائے اس طرف پھر جاؤ\"۔(3) ابن مسمول ضعیف راوی ہیں، اسے ابن سکن رحمہ اللہ نے اپنے طریق سے نقل کیا ہے، فرماتے ہیں مخول کی اس سند کے علاوہ کوئی روایت نہیں۔","",{"fn":"(1) اسد الغابہ (۴۷۹۸) استیعاب (۲۵۶۴) تجرید (۲/۶۵)\n(2) مسند ابویعلی (۳/۱۵۶۸)\n(3) مستدرک حاکم (۴/۱۵۹) کنز العمال (۴۳۵۷۸)"}],[6480,"§۷۸۵۲ ۔ مخیریق نضری اسرائیلی(1)\nبنو نضیر سے ہیں۔ واقدی(2) رحمہ اللہ نے ذکر کیا ہے کہ وہ اسلام لائے اور اُحد میں شہید ہوئے۔ واقدی اور بلاذری کا قول ہے۔ بعض نے کہا: بنو قینقاع سے ہیں، بقول بعض: بنو قطیعون، عالم تھے۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم کے لیے اپنے مال کی وصیت کی تھی، وہ سات باغ تھے جو یہ ہیں: میثب، صائفہ، دلال، حسنیٰ، برقہ، اعواف، مشربہ ام ابراہیم، نبی کریم صلی اللہ علیہ وسلم نے انہیں صدقہ کر دیا۔\nعمر بن شبہ کا اخبار مدینہ میں قول ہے کہ ہم سے محمد بن علی نے بحوالہ ابو عون، انہوں نے ابن شہاب سے روایت کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کے زکوٰۃ کے اموال مخیریق کے تھے، جن کی انہوں نے رسول اللہ صلی اللہ علیہ وسلم تک پہنچانے کی وصیت کی تھی اور خود اُحد میں شریک ہو کر شہید ہو گئے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مخیریق یہودیوں میں سے سبقت کرنے والے، سلیمان فارسیوں میں سے سبقت کرنے والے اور بلال حبشیوں میں سے سبقت لینے والے ہیں۔(3)\nعبد العزیز کا قول ہے: مجھے یہ بات پہنچی ہے کہ وہ بنو قینقاع کے باقی ماندہ لوگوں میں سے۔\nزبیر بن بکار نے اخبار مدینہ میں فرمایا: ہم سے محمد بن حسن نے اور وہ ابن زبالہ ہیں، بحوالہ کئی راویوں سے ان میں محمد بن طلحہ بن عبد الحمید بن ابو لبس بن جبر اور سلیمان بن طالوت ہیں، انہوں نے عثمان بن کعب بن محمد بن کعب سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زکوٰۃ کے اموال مخیریق یہودی کے تھے، جب نبی کریم صلی اللہ علیہ وسلم اُحد کی طرف تشریف لے گئے تو انہوں نے یہودیوں سے کہا: تم محمد صلی اللہ علیہ وسلم کی مدد کیوں نہیں کرتے؟ اللہ کی قسم! تم جانتے ہو کہ ان کی مدد کرنا تم پر حق ہے۔ وہ کہنے لگے: آج ہفتے کا دن ہے، انہوں نے کہا: کوئی نہیں۔۔۔۔۔۔۔۔۔۔۔ انہوں نے اپنی تلوار لے لی اور نبی کریم صلی اللہ علیہ وسلم کی طرف چلے اور لڑائی کی، انہیں بہت سے زخم آئے، جب موت کا وقت آیا تو کہنے لگے: میرے مال محمد صلی اللہ علیہ وسلم کے لیے ہیں جہاں چاہیں خرچ کریں۔\nان کے اموال کی وصیت کا قصہ ذکر کیا اور ان کا نام لیا لیکن میثب کے بدلے میثر فرمایا اور اعواف کے بدلے معوان فرمایا، اور مشربہ ام ابراہیم کا اضافہ کیا جسے \"مہروز\" کہا جاتا تھا۔","",{"fn":"(1) تجرید (۲/۶۵)\n(2) المغازی (۲۶۲)\n(3) تہذیب تاریخ دمشق (۳/۲۴۵) طبقات الکبریٰ (۱/۱۸۳)"}],[6481,"§۷۸۵۳ ۔ مخیس(1)\nابن حکیم عذری، ابو علی جیانی نے اور ابن فتحون نے استیعاب کے حاشیے میں بحوالہ ابو طاہر ذہلی کی کتاب مسانید المقلین ذکر کیا ہے، انہوں نے اس میں بطریق یعقوب بن جبر عذری نقل کیا ہے، میں نے ابو ہلال مبین بن قطبہ بن ابو عمرہ عذری وہ بحوالہ مخیس ابن حکیم حدیث بیان کرتے ہیں کہ انہوں نے ان کو فرماتے ہوئے سنا: میں نبی کریم صلی اللہ علیہ وسلم کے پاس آیا.... پھر اس میں اکیدر دومتہ الجندل کا ذکر کیا، اس کے آخر میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے لیے برکت کی دعا فرمائی، ان کی سند میں ایسے راوی ہیں جو معروف نہیں۔","",{"fn":"(1) اسد الغابہ (۴۷۹۹) استیعاب (۲۵۶۵) تجرید (۲/۶۵)"}],[6482,"§۷۸۵۴ ۔ مدرک بن حارث غامدی(1)\nانہیں شرف صحابیت حاصل ہے، اہل شام میں ان کا شمار ہے۔ ان سے ولید بن عبد الرحمن جرشی نے روایت کی، اسی طرح ابن مندہ، ابو نعیم نے مختصر سے نقل کیا ہے۔\nابو موسیٰ کا قول ہے: محمد بن مسیب ارغیانی نے بحوالہ صحابہ رضی اللہ عنہم ان کا ذکر کیا ہے، ابو زرعہ دمشقی نے قبائل یمن میں سے شام آنے والوں میں ان کا ذکر کیا، اسی طرح محمد بن سمیع نے ان کا ذکر کیا ہے۔ حارث بن حارث غامدی میں ان کی طرف اشارہ ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۰۲) تجرید (۲/۶۵)"}],[6483,"§۷۸۵۵ ۔ مدرک بن زیاد(1)\nابن عساکر نے تاریخ میں ان کا ذکر کیا ہے اور بطریق ابو عمیر عدی بن احمد بن عبد الباقی آدمی نقل کیا ہے کہ ہمیں ابو عطیہ عبد الرحیم بن محرز بن عبد اللہ بن محرز بن سعید بن حبان بن مدرک بن زیاد نے بتایا، فرماتے ہیں: مدرک بن زیاد، رسول اللہ صلی اللہ علیہ وسلم کے صحابی ہیں، ابو عبیدہ کے ساتھ آئے اور دمشق کی راویہ نامی بستی میں وفات پائی وہ پہلے مسلمان تھے جو یہاں دفن ہوئے۔(2) ابن عساکر رحمہ اللہ کا قول ہے: اس طریق کے علاوہ مجھے ان کا ذکر نہیں ملا۔","",{"fn":"(1) مختصر تاریخ دمشق (۲۴/۱۵۳)\n(2) اسد الغابہ (۴۸۰۵) استیعاب (۲۳۸۳) تجرید (۲/۶۵)"}],[6484,"§۷۸۵۶ ۔ مدرک بن عوف بجلی(1)\nاحمد بن جعفر مستغفری رحمہ اللہ نے ان کا ذکر کیا ہے، فرماتے ہیں: انہیں شرف صحابیت حاصل ہے، ابن حبان وغیرہ ان پر سبقت لے گئے ہیں، انہوں نے صحابہ رضی اللہ عنہم میں پھر تابعین میں ان کا ذکر کیا ہے۔ ابو عمر(2) کا قول ہے: ان کے صحابی ہونے میں اختلاف ہے، ان سے قیس بن ابو حازم نے روایت کی، مدرک نے سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت کی۔ ابو بکر بن ابی شیبہ نے سیدنا عمر رضی اللہ عنہ سے بحوالہ مدرک بن عوف بجلی ان کی حدیث نقل کی ہے، فرماتے ہیں: اس اثناء میں کہ میں سیدنا عمر رضی اللہ عنہ کے پاس تھا کہ ان کے پاس نعمان بن مقرن کا قاصد آیا.... پھر قصہ ذکر کیا جو شبیل کے والد عوف کے سوانح میں گزر چکا ہے۔","",{"fn":"(1) استیعاب (۳/۴۳۸)\n(2) اسد الغابہ (۴۸۰۳) استیعاب (۲۳۸۴) تجرید (۲/۶۵)"}],[6485,"§۷۸۵۷ ۔ مدرک غفاری (بے نسبت)(1)\nبغوی رحمہ اللہ اور ابن ابو عاصم(2) نے ان کا ذکر کیا ہے اور بطریق کثیر بن زید بحوالہ خالد بن طفیل بن مدرک، انہوں نے اپنے والد کے حوالے سے نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے انہیں اپنی صاحبزادی کو لینے بھیجا، وہ انہیں مکہ سے لے آئے۔ اسی سند سے ہے کہ نبی کریم صلی اللہ علیہ وسلم جب سجدہ کرتے اور سر اٹھاتے تو فرماتے: \"اے اللہ! میں آپ کی ناراضگی سے پناہ چاہتا ہوں....\"۔ (الحدیث)(3) ابن ابی عاصم کے الفاظ ہیں، اسے یعقوب بن حمید نے بحوالہ سفیان بن حمزہ، انہوں نے کثیر کے حوالے سے نقل کیا ہے۔ رہے بغوی وہ یہ تو انہوں نے بحوالہ حمزہ بن مالک بن حمزہ بن سفیان اسلمی نقل کیا ہے، فرماتے ہیں: مجھ سے میرے چچا سفیان بن حمزہ نے روایت کیا ہے، انہوں نے یہ ذکر کیا، لیکن فرمایا: بحوالہ خالد کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے دادا مدرک کو اپنی بیٹی کی طرف بھیجا، وہ انہیں مکہ سے لے آئے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے پھر اس روایت کو ذکر کیا۔ بغوی رحمہ اللہ کا قول ہے: مدرک سے صرف اسی اسناد سے روایت کی جاتی ہے۔","",{"fn":"(1) ترمذی (۳۵۶۶) نسائی (۱۷۴۶) ابن ماجہ (۱۱۷۹) جامع المسانید والسنن (۱۱/۲۰۰)\n(2) الاحاد والمثانی (۲/۲۵۳)\n(3) ترمذی (۳۵۶۶) نسائی (۱۷۴۶) ابن ماجہ (۱۱۷۹) جامع المسانید والسنن (۱۱/۲۰۰)"}],[6486,"§۷۸۵۸ ۔ مدعم اسود(1)\nرسول اللہ صلی اللہ علیہ وسلم کے مولی تھے، حبشی میں پیدا ہوئے، رفاعہ بن زید جذامی نے انہیں رسول اللہ صلی اللہ علیہ وسلم کو ہدیہ دیا۔ موطا اور صحیحین میں بطریق سالم مولی ابن مطیع، بحوالہ ابو ہریرہ، فتح خیبر میں ان کا ذکر ہے۔ پھر حدیث ذکر کی، اس میں ہے کہ مدعم کو اچانک تیر آ کر لگا جس سے وہ شہید ہو گئے۔(2)","",{"fn":"(1) اسد الغابہ (۴۸۰۶) استیعاب (۲۵۶۷) تجرید (۲/۶۶)\n(2) بخاری (۳۹۹۳، ۶۳۲۹) مسلم (۳۰۶) ابوداؤد (۲۷۱۱)"}],[6487,"§۷۸۵۹ ۔ مدلاج بن عمرو السلمی(1)\nیہ ثقف و مالک کے بھائی ہیں۔ بقول ابن کلبی یہ سلمی قبیلہ سے تعلق رکھتے تھے۔ اور اس قبیلہ کے لوگ مشرف باسلام ہو چکے تھے اور غزوہ بدر میں شریک تھے اور یہ بنی عمرو بن دودان بن اسد بن خزیمہ اور بنی عبد شمس کے اتحادی تھے۔ اور بقول واقدی(2) اور ابن عبد البر یہ سلمی قبیلہ کے لوگ ہیں اور مدلاج بن عمرو تمام اجتماعات میں شریک ہوئے ہیں اور ۵۰ھ میں ان کا انتقال ہوا۔\nاور بقول ابن اسحاق(3) یہ مدلاج بن عمرو بنو سلیم سے تعلق رکھتے ہیں جو کہ بنو حجر کی شاخ ہے اور ابن عبد البر(4) نے نقل کیا ہے کہ بعض نے ان کا نام مدبلج بتلایا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۸۰۸) استیعاب (ت: ۲۵۶۸) تجرید (۲/۶۶)\n(2) المغازی (۱/۱۵۴)\n(3) سیرۃ النبویہ (۲/۳۲۳)\n(4) استیعاب (۴/۳۱)"}],[6488,"§۷۸۶۰ ۔ مدلج الانصاری(1)\nان کا تذکرہ ایک حدیث میں ملتا ہے جس کو ابن مندہ نے سدی صغیر کے طریق سے تخریج کیا ہے کلبی ابو صالح سے اور وہ ابن عباس رضی اللہ عنہما سے روایت کرتے ہیں کہ نبی علیہ السلام نے ایک انصاری غلام کو سیدنا عمر رضی اللہ عنہ کو بلانے کے لیے بھیجا جن کا نام مدلج تھا۔ جب وہ غلام گیا تو کیا دیکھتا ہے کہ سیدنا عمر رضی اللہ عنہ نے دروازہ بند کر کے آرام فرما رہے ہیں اور چت لیٹے ہوئے ہیں۔ تو اس نے اچانک دروازہ کھول کر سلام کیا لیکن سیدنا عمر رضی اللہ عنہ نہ بیدار نہ ہوئے۔ تو غلام واپس چلا گیا۔ بعد میں جب سیدنا عمر رضی اللہ عنہ کو اس بات کا پتہ چلا کہ غلام نے ان کو برہنہ حالت میں دیکھا ہے تو انہوں نے فرمایا کہ اللہ کی قسم! میں پسند کرتا ہوں کہ اللہ تعالیٰ ہماری اولاد اور ہمارے نوکروں کو اس وقت میں بلا اجازت گھروں میں داخل ہونے سے روک دیں۔ یہ کہ کر وہ نبی علیہ السلام کے پاس پہنچے تو یہ آیت نازل ہو چکی تھی:\n﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لِيَسْتَأْذِنكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمُ....﴾(2)\nپھر ابن مندہ نے پوری حدیث بیان فرمائی جس میں یہ بھی ہے کہ نبی علیہ السلام نے سیدنا مدلج کو فرمایا کہ آپ جنتی ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۴۸۰۷) استیعاب (ت: ۲۵۶۶) تجرید (۲/۶۶)\n(2) سورۃ النور الآیۃ (۵۸)"}],[6489,"§۷۸۶۱ ۔ مدلج آخر\nیہ ایک اور مدلج ہیں جن کے نام کے ساتھ کوئی نسبت نہیں ہے۔ ابن قانع نے اسماعیل بن عیاش عن ضمضم بن زرعہ عن ابیہ، عن شریح بن عبید عن مدلج کے طریق سے تخریج کی ہے۔ فرمایا کہ جب نبی علیہ السلام اور آپ کے کچھ صحابہ نے رات کو ایک غزوہ میں پہرہ داری کی تو آپ علیہ السلام نے صبح کے وقت فرمایا کہ تم پر جنت واجب ہو چکی ہے۔ ابن مندہ نے بھی اسماعیل بن عیاش ہی کے طریق سے تخریج کی ہے لیکن انہوں نے ان کے حالات زندگی الگ سے نہیں لکھے بلکہ مدلاج بن عمرو سلمی کے حالات میں ہی ان کا تذکرہ فرمایا (جو کہ بنی عبد شمس کے اتحادی تھے)۔ اور یہ وہی مدلاج ہیں جن کا تذکرہ ابن اسحاق نے شرکاء بدر میں کیا ہے۔ اس لیے کہ ان کے بارے میں کہا گیا ہے کہ ان کا نام یا تو مدلاج تھا یا مدلج تھا۔ گویا کہ انہوں نے ابن السکن کی پیروی کی ہے کہ انہوں نے بھی کہا کہ مدلج بن عمرو سلمی اور یہ بھی کہا گیا ہے کہ مدلاج کو نبی علیہ السلام کی صحبت بھی حاصل تھی اور انہی سے اہل حمص کی روایت مروی ہے۔ ۵۰ھ میں انتقال ہوا۔ ضمضم عن شریح عن مدلج کے طریق سے حدیث بیان فرمائی ہے کہ یہ حضور علیہ السلام کے صحابہ میں سے تھے۔ پوری حدیث بیان کی ہے، لیکن اس میں ان کے والد کا نام اور ان کا نسب ذکر نہیں کیا۔"],[6490,"§۷۸۶۲ ۔ مدلوک الفزاری\nابن ابی حاتم فرماتے ہیں کہ آقا علیہ السلام کے صحبت یافتہ تھے۔ محمد بن سعد نے ملک شام کے رہنے والے صحابہ رضی اللہ عنہم میں ان کا بھی ذکر کیا ہے۔ اور بردیجی نے اسماء مفردہ من الصحابہ میں ان کا ذکر کیا ہے۔ اور مزید ان کا تذکرہ ضمضم بن قتادہ کے حالات میں گزر چکا ہے۔\nامام بخاری رحمہ اللہ(1) نے اپنی کتاب \"التاریخ الکبیر\" میں اور ابن سعد، امام بغوی(2) اور طبرانی(3) نے مطر بن علاء الفزاری کے طریق سے تخریج کی ہے۔ مجھے میری پھوپھی آمنہ یا امیہ بنت ابی الشعثاء اور ہماری لونڈی قطبہ نے یہ حدیث سنائی ہے۔ یہ دونوں فرماتی ہیں کہ ہم نے ابو سفیان کو یہ کہتے ہوئے سنا ہے (امام بغوی رحمہ اللہ نے اپنی روایت میں مدلوک کا بھی اضافہ فرمایا ہے) کہ مجھے میرے آزاد کردہ غلام حضور اقدس صلی اللہ علیہ وسلم کے پاس لے گیا میں مسلمان ہو گیا پھر نبی کریم صلی اللہ علیہ وسلم نے میرے لیے برکت کی دعا فرمائی اور اپنے دست رحمت کو میرے سر پر پھیرا۔ تو سیدنا ابو سفیان کے سر کا وہ حصہ جہاں آپ صلی اللہ علیہ وسلم کا دست مبارک لگا تھا ہمیشہ سیاہ رہا باوجود یکہ باقی پورے سر کے بال سفید ہو چکے تھے۔(4)\nابن مندہ اور ابو نعیم نے ایک اور سند سے اس کی تخریج کی ہے جو کہ مطر سے روایت ہے جس میں یہ بھی ہے کہ مدلوک ابو سفیان سے روایت ہے اور سند میں یہ کہا کہ آمنہ راوی ہیں اور اس میں کوئی شک کا اظہار بھی نہیں کیا۔","",{"fn":"(1) التاریخ الکبیر (۸/۵۵)\n(2) الطبقات (۷/۴۳۶)\n(3) المعجم (الحدیث: ۲۰/۸۰۴)\n(4) مجمع الزوائد (الحدیث: ۹/۴۰۹)"}],[6491,"§۷۸۶۳ ۔ المذبوب التنوخی(1)\nصاحب تجرید نے لکھا ہے کہ حمص ان کا مسکن تھا عبد الصمد بن سعید نے بھی حمص کے رہنے والے صحابہ رضی اللہ عنہم میں تذکرہ فرمایا ہے۔ اور ان کے لیے ان کے اپنے ہی بیٹے مالک کے طریق سے حدیث ذکر کی ہے اور اس کی سند منکر ہے۔","",{"fn":"(1) تجرید (۲/۶۶)"}],[6492,"§۷۸۶۴ ۔ مذعور بن عدی العجلی\nملک شام میں جنگ یرموک میں شریک تھے، اسی طرح فتوح العراق میں بھی شرکت فرمائی۔\nسیف بن عمر نے اپنی سند کے ساتھ بیان فرمایا ہے کہ جب خالد بن ولید رضی اللہ عنہ یمامہ سے واپس آئے تو وہ مثنی بن حارثہ الشیبانی، مذعور بن عدی العجلی اور حرملہ بن مریط حنظلی اور سلمی بن القین حنظلی کے پاس آئے۔ مثنی اور مذعور دونوں نبی علیہ السلام کے قاصد تھے اور صحبت یافتہ تھے۔ جبکہ حرملہ اور سلمی مہاجرین میں سے تھے۔ یہ سب سیدنا ابو بکر صدیق رضی اللہ عنہ کے پاس آئے.... ایک اور جگہ پر بھی ان کا تذکرہ فرمایا ہے جس میں یہ بھی اضافہ ہے کہ مذعور بن عدی العجلی۔ اور سیف بن عمر نے ایک جگہ تحریر کیا ہے کہ خالد بن قیس العجلی نے اپنے والد کے واسطے سے ہمیں ایک حدیث سنائی۔ فرمایا کہ جب مثنی بن حارثہ اور مذعور سیدنا ابو بکر صدیق رضی اللہ عنہ کے پاس آئے تو انہوں نے سیدنا ابو بکر رضی اللہ عنہ سے اہل فارس کے ساتھ جہاد اور لڑائی کی اجازت مانگی اور مزید یہ کہ ہم ہر اس شخص پر زبردستی کر سکیں جو ہمارے ساتھ ملے ہماری قوم میں سے۔ آپ رضی اللہ عنہ نے ان دونوں کو اجازت مرحمت فرما دی۔ اور مذعور بکر بن وائل، ضبیعہ اور عنزہ کے چار ہزار افراد میں سے اکیلا تھا۔ جس نے خفان اور نمارق کو فتح کر لیا۔ اور اسی فتح کا نقشہ وہ اپنے اشعار میں یوں کھینچتے ہیں:\n\"ہم نے بغیر کسی پہنچ کے، قالینوں پر بنی کھجوروں تک خفان کے مقام پر غلبہ حاصل کیا۔ اور ہمیں امید ہے کہ یقیناً ہمارے گھوڑے گشت کریں۔ فرات کے ساحل پر چمکتی ہوئی تلواریں لے کر\"(1)","",{"fn":"(1) مختصر تاریخ دمشق (۲۴/۱۵۷، ۱۵۸)"}],[6493,"§۷۸۶۵ ۔ مذکور العذری(1)\nامام واقدی(2) نے مغازی میں ان سے تذکرہ میں فرمایا ہے کہ یہ نبی کریم صلی اللہ علیہ وسلم سے گائیڈ تھے (یعنی رہنما تھے)۔ امام حاکم رحمہ اللہ نے اکلیل میں انہی کے طریق سے پھر ابو سلمہ بن عبد الرحمن بن عوف کے طریق سے عبد اللہ بن ابی بکر بن محمد بن عمرو بن حزم کے طریق سے جن میں سے ایک دوسرے سے زائد الفاظ پر مشتمل ہیں۔ یہ سب حضرات فرماتے ہیں نبی کریم صلی اللہ علیہ وسلم نے ملک شام کے قریب جانے کا ارادہ فرمایا تو آپ صلی اللہ علیہ وسلم کو بتایا گیا کہ دومتہ الجندل میں ایک بہت بڑا میلہ لگتا ہے جس میں ایک بڑا بازار ہوتا ہے اور بہت سے تاجر شریک ہوتے ہیں۔ یہ خبر سنتے ہی سب لوگ ہوشیار و تیار ہو گئے۔ پھر نبی کریم صلی اللہ علیہ وسلم دو ہزار مسلمانوں کی فوج کو لے کر نکلے۔ آپ صلی اللہ علیہ وسلم رات کو سفر فرماتے اور دن کو چھپ جاتے تھے۔ آپ کے ساتھ آپ کا گائیڈ بنی عذرہ میں سے تھا جو کہ ماہر تجربہ کار گائیڈ مشہور تھا۔ جب نبی علیہ السلام دومتہ الجندل کے قریب پہنچے تو آپ کو آپ کے گائیڈ نے بتایا کہ یہاں آپ کے قریب ہی ان کو چرواہے مال مویشی چرارہے ہوں گے آپ میری ڈیوٹی لگائیں کہ میں اچھی طرح دیکھ کر آؤں۔ تو آپ علیہ السلام نے ان کو اس کام کے لیے مقرر کیا تو یہ عذری ہر اول دستے کے طور پر گئے تو ان کو جانوروں اور بکریوں کے نشانات نظر آئے۔ تو انہوں نے واپس آکر نبی علیہ السلام کو بتا دیا۔ نبی علیہ السلام نکل کھڑے ہوئے اور ان کے مویشیوں پر اچانک حملہ کر دیا۔ جو کچھ مقدر میں تھا لے لیا۔ لیکن جب ان کو پتہ چلا تو ہر طرف سے گھیراؤ کرنے کی کوشش کی لیکن ان کو کوئی بھی نہ مل سکا اور مسلمانوں کی ساری فوج بکھر گئی۔ محمد بن سلمہ نے کافروں کا ایک بندہ گرفتار کر کے نبی علیہ السلام کی خدمت میں پیش کیا، تو آپ علیہ السلام اس کو چند دن تک اسلام کی دعوت دیتے رہے بالآخر وہ مسلمان ہو گیا اور نبی علیہ السلام واپس لوٹ آئے۔ یہ غزوہ ۵ھ کے شروع میں ہوا تھا۔(3)","",{"fn":"(1) اسد الغابہ (ت: ۴۸۱۱) تجرید (۲/۶۶)\n(2) المغازی (۱/۴۰۲)\n(3) مختصر (۲۴/۱۵۹)"}],[6494,"§۷۸۶۶ ۔ مرارہ بن ربعی(1)\nمرارہ بن ربعی بن عدی بن یزید بن جشم۔ علامہ ابن کلبی رحمہ اللہ نے ان کا تذکرہ فرماتے ہوئے لکھا ہے کہ کثرت سے رونے والے صحابہ رضی اللہ عنہم میں سے ایک یہ بھی تھے جن کے بارے میں یہ آیت نازل ہوئی:\n﴿تَوَلَّوْا وَأَعْيُنُهُمْ تَفِيضُ مِنَ الدَّمْعِ﴾(2)\nامام عدوی رحمہ اللہ یہ فرماتے ہیں اس کے علاوہ کسی نے ان کا تذکرہ نہیں فرمایا۔","",{"fn":"(1) تجرید (۲/۶۶)\n(2) سورۃ التوبہ الآیۃ (۹۲)"}],[6495,"§۷۸۶۷ ۔ مرارہ بن الربیع الانصاری(1)\nمرارہ بن ربیع اوسی یا تو بنی عمرو بن عوف سے ان کا تعلق ہے یا بنی عمرو بن عوف کے اتحادی قبیلہ قضاعہ سے ان کا تعلق ہے۔\nیہ مشہور صحابی ہیں غزوہ بدر میں شریک تھے، اور یہ ان تین صحابہ میں سے ہیں جن کی توبہ کا تذکرہ قرآن مجید میں موجود ہے۔ یہ قصہ بخاری و مسلم میں کعب بن مالک کی حدیث میں موجود ہے۔ میں نے پوچھا کہ ایسا واقعہ آپ کے علاوہ کسی اور کے ساتھ بھی پیش آیا؟ تو انہوں نے فرمایا: ہلال بن امیہ اور مرارہ بن الربیع، انہوں نے دو ایسی نیک صالح شخصیات کا تذکرہ کیا جو جنگ بدر میں شریک ہوئے تھے۔\nسیدنا جابر رضی اللہ عنہ کی حدیث میں ہے کہ یہ آیت:\n﴿وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا﴾(2)\nجن صحابہ کے بارے میں نازل ہوئی وہ کعب بن مالک اور مرارہ بن الربیع اور ہلال بن امیہ تھے، یہ تینوں انصاری صحابی تھے۔(3)(4)","",{"fn":"(1) اسد الغابہ (۴۸۱۴) الاستيعاب (۲۳۹۰) تجرید (۲/۶۶)\n(2) سورۃ التوبہ الآیۃ (۹۲)\n(3) بخاری، کتاب المغازی، باب حدیث کعب بن مالک (۴۴۱۸) مسلم، کتاب التوبہ، کعب بن مالک و صاحبیہ (۶۹۴۷)\n(4) البیہقی فی دلائل النبوۃ (۵/۲۷۳، ۲۷۹) طبری فی بیان البیان (۱۱/۵۷)"}],[6496,"§۷۸۶۸ ۔ مرارہ بن مربع(1)\nمرارہ بن مربع بن قیظی انصاری۔ ابن سکن نے ان کے بھائی عبد اللہ کا تذکرہ کرتے ہوئے لکھا ہے کہ جسر ابی عبید کے دن عبد اللہ اور ان کا بھائی عبد الرحمن شہید ہو گئے تھے انہی کا تیسرا بھائی مرارہ تھا جس نے کوئی روایت نہیں کی۔ البتہ بعض اہل علم نے ان کے نسب کا ذکر کیا ہے۔ ابن عبد البر(2) فرماتے ہیں: مرارہ اور ان کے دونوں بھائیوں کو نبی کریم صلی اللہ علیہ وسلم کی صحبت نصیب ہوئی تھی۔ اسی طرح زید بن مربع بھی صحبت یافتہ دربار رسالت تھے۔ ان کے والد کا شمار منافقین میں ہوتا تھا۔","",{"fn":"(1) اسد الغابہ (ت: ۴۸۱۶) استیعاب (ت: ۲۳۹۱) تجرید (۲/۶۳)\n(2) استیعاب (۳/۴۳۹)"}],[6497,"§۷۸۶۹ ۔ مراوح المزنی\nابن قانع نے صحابہ رضی اللہ عنہم میں ان کا بھی ذکر کیا ہے اور انہوں نے ان کے تذکرہ کے لیے ایک حدیث ذکر کی ہے۔ محمد بن حسن بن زبالہ کے طریق سے عبد اللہ بن عمرو بن قاسم، محمد بن بیصم بن عبید بن مراوح عن ابیہ عن جدہ سے کہ نبی کریم صلی اللہ علیہ وسلم نے ان کو عامل مقرر فرمایا تھا (زکوۃ وصول کرنے والا)۔ (اس حدیث کی سند میں جد (دادا) سے مراد بیصم کا دادا ہے نہ کہ محمد کا) اور ان کا مزید تذکرہ عبیدہ بن مراوح کے حالات میں بھی گزر چکا ہے۔"],[6498,"§۷۸۷۰ ۔ مران بن مالک الرازی(1)\nابن اسحاق ان کا تذکرہ کرتے ہوئے لکھتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے خیبر کے مال غنیمت میں سے ان کو بھی عطا فرمایا تھا۔ ان کا اصل نام کیا تھا؟ تو ابن ہشام اور ابن کلبی نے مروان جبکہ واقدی نے مرہ ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۱۳) استیعاب (۲۵۷۱)"}],[6499,"§۷۸۷۱ ۔ مربع بن قیظی\nیہ مرارہ کے والد ہیں جن کا تذکرہ پچھلے صفحات میں(۷۸۶۸) کے تحت گزر چکا ہے۔ ان کا شمار منافقین میں تھا لیکن کچھ لوگوں کا کہنا ہے کہ توبہ تائب ہو گئے تھے۔"],[6500,"§۷۸۷۲ ۔ مرثد بن جابر الکندی(1)\nامام بغوی رحمہ اللہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور فرمایا کہ علی بن قرین نے حبیب بن مرداس البلوی سے روایت نقل کی ہے کہ میں نے غانم بن غالب قیسی کو مرثد بن جابر کندی سے روایت کرتے ہوئے سنا ہے کہ میں نبی کریم صلی اللہ علیہ وسلم کے پاس قاصد بن کر گیا تو میں نے پوچھا اے اللہ کے رسول صلی اللہ علیہ وسلم! کیا ہر سال حج کرنا ضروری ہے؟ آپ علیہ السلام نے ارشاد فرمایا کہ اگر تمہارے اندر استطاعت و قدرت ہو تو ہر سال حج کرو لیکن فرض حج وہ بہر حال ایک ہی ہے۔ اور بقول امام بغوی رحمہ اللہ علی بن قرین مشرقی جانب کا ایک بوڑھا تھا اور رواۃ حدیث میں بہت ضعیف ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۱۷) تجرید (۲/۶۳)"}],[6501,"§۷۸۷۳ ۔ مرثد بن ربیعہ العبدی(1)\nامام بغوی ان کا تذکرہ کرتے ہوئے فرماتے ہیں کہ مجھے شاذ کونی کی ایک روایت ملی ہے ابن قتیبہ سے، معلی بن یزید سے بکر بن مرثد بن ربیعہ فرماتے ہیں کہ میں نے مرثد کو یہ کہتے ہوئے سنا کہ میں نے نبی کریم صلی اللہ علیہ وسلم سے گھوڑوں کی زکوٰۃ کے بارے میں پوچھا کہ زکوٰۃ ہے یا نہیں تو آپ نے ارشاد فرمایا نہیں۔ ہاں اگر کوئی گھوڑا تجارت(2) کی نیت سے بیچنے کے لیے ہو تو اس میں زکوٰۃ ہوگی۔\nامام بغوی رحمہ اللہ یہ فرماتے ہیں کہ یہ حدیث اس کے علاوہ کسی اور سند سے مجھے نہیں ملی۔ اس سند میں بھی شاذ کونی پر بعض علماء نے جھوٹ کا الزام لگایا ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۱۸) تجرید (۲/۶۷)\n(2) جامع المسانید (۱۱/۲۰۸)"}],[6502,"§۷۸۷۴ ۔ مرثد بن زید الغطفانی\nابن فتحون نے مقاتل بن حیان سے نقل کیا ہے کہ یہی وہ شخص ہے جس کے بارے میں یہ آیت نازل ہوئی:\n﴿إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَىٰ ظُلْمًا....﴾\nاس لیے کہ یہی تو اپنے بھتیجے کے مال پر قابض تھا اور اس میں تصرفات کیا کرتا تھا اور سارا مال ہضم کر لیا تھا۔ میں کہتا ہوں: امام واقدی رحمہ اللہ نے جو مقاتل سے روایت نقل کی ہے اس کے الفاظ یہ ہیں۔ یہ آیت بنی غطفان کے ایک آدمی مرثد بن زید کے بارے میں نازل ہوئی جو اپنے چھوٹے سے نابالغ بھتیجے کے مال پر قابض ہو چکا تھا۔"],[6503,"§۷۸۷۵ ۔ مرثد بن الصلت الجعفی(1)\nامام بغوی رحمہ اللہ ان کا تذکرہ کرتے ہوئے عبد الرحمن بن عمرو بن جبلہ کے طریق سے روایت لکھتے ہیں کہ عبد الرحمن بن عمرو فرماتے ہیں کہ میں نے عبد الرحمن بن مرثد کو اپنے والد مرثد بن الصلت سے روایت اور حدیث بیان کرتے ہوئے سنا ہے کہ ان کے والد فرماتے ہیں کہ میں حضور علیہ السلام کے پاس قاصد بن کر آیا تو میں نے پوچھا آلہ تناسل کو چھونے سے وضو ٹوٹ جاتا ہے؟ تو آپ علیہ السلام نے ارشاد فرمایا کہ یہ بھی جسم کا ایک حصہ ہی تو ہے۔(2)\nامام بغوی رحمہ اللہ فرماتے ہیں یہ حدیث منکر ہے، اور اس کے راوی عبد الرحمن بن عمرو حدیث بیان کرنے میں بہت زیادہ ضعیف راوی ہیں۔\nمیں کہتا ہوں: اس ضعیف راوی کی موافقت اسی جیسے ایک اور ضعیف راوی نے کی ہے وہ اس طرح کہ ابن قانع اور یحیی بن یونس شیرازی نے حدیث لکھی ہے علی بن قرین کے طریق سے حبیب بن موسیٰ، عبد الرحمن بن مرثد اپنے والد سے روایت کرتے ہیں جیسا کہ اوپر گزر چکا ہے۔\nاسی طرح ابو موسیٰ نے ذیل میں اس کی تخریج کی ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۱۹) استیعاب (۲۳۹۲) تجرید (۲/۶۷)\n(2) ابن ماجہ کتاب الطہارۃ باب الرخصۃ فی ذلک الحدیث (۴۸۳) مسند امام احمد (۴/۲۲) سنن دارقطنی (۱/۱۳۵) سنن الکبریٰ...."}],[6504,"§۷۸۷۶ ۔ مرثد بن ظبیان(1)\nمرثد بن ظبیان بن سلمہ بن لوذان بن عوف بن سدوس شیبانی پھر سدوسی۔\nابن سکن نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ فرماتے ہوئے حدیث لکھی ہے، عمر بن احیجہ کے طریق سے فرماتے ہیں کہ نجیر بن حاجب بن یونس بن شہاب بن زہیر بن مدعور بن ظبیان بن سلمہ نے اپنے والد سے اور وہ ان کے دادا سے روایت نقل کرتے ہوئے فرماتے ہیں کہ مرثد بن ظبیان ہجرت کر کے حضور علیہ السلام کے پاس تشریف لے گئے اور غزوہ حنین میں شریک رہے۔ واپسی پر حضور علیہ السلام نے بکر بن وائل کی طرف خط لکھ کر ان کو دیا اور دو خوبصورت کپڑے بھی ان کو پہنائے یہ خط لے کر جب اپنے علاقہ میں پہنچے تو اس کو پڑھنے کے لیے کوئی بندہ نہیں ملا سوائے بنو ضبیعہ کے ایک آدمی کے جس کو لوگ بنی الکاتب ہی کہتے تھے۔ ابن سکن فرماتے ہیں کہ یہ غیر مشہور صحابی ہیں۔ میں کہتا ہوں: امام احمد رحمہ اللہ اور بغوی رحمہ اللہ(2) نے قتادہ کے طریق سے مضارب بن حرب بجلی سے روایت کی ہے کہ مرثد بن ظبیان فرماتے ہیں کہ ہمارے پاس حضور علیہ السلام کا خط مبارک آیا لیکن ہم میں سے کوئی بھی اسے پڑھ نہیں سکتا تھا پھر بنو ضبیعہ کے ایک آدمی نے اسے پڑھا (جس کو لوگ بنو الکاتب کہتے تھے) خط کے الفاظ یہ تھے۔\nمحمد رسول اللہ صلی اللہ علیہ وسلم کی طرف سے بکر بن وائل کی طرف۔ تم مسلمان ہو جاؤ تو نجات پا جاؤ گے، انہیں بنی الکاتب کہا جاتا تھا۔ ابن سکن نے تعلیقاً ذکر کیا ہے، فرماتے ہیں: مرسل ہے۔ خلیفہ بن خیاط اپنی کتاب تاریخ میں لکھتے ہوئے فرماتے ہیں کہ یہ روایت محمد بن سواء، قرہ بن خالد اور مضارب سے کہ نبی کریم علیہ السلام نے بکر بن وائل کے ایک قیدی مرثد بن ظبیان کو ہبہ فرما دیا بغوی نے بحوالہ خلیفہ یہ روایت بلاغاً ذکر کی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۴۸۲۰) تجرید (۲/۶۷)\n(2) مسند امام احمد (۵/۶۸)"}],[6505,"§۷۸۷۷ ۔ مرثد بن علقمی التغلبی(1)\nکنیت ابو الکنود ہے۔ امام بغوی رحمہ اللہ ان کا تذکرہ کرتے ہوئے ایک حدیث نقل فرماتے ہیں جس کو ضعیف راویوں میں سے علی بن قرین نے صلت بن سعید مازنی سے انہوں نے بکیر بن مسمار ریاحی سے روایت کیا ہے۔ فرماتے ہیں کہ میں نے ابو الکنود رحیم ابن عامر تغلبی کو یہ کہتے ہوئے سنا ہے کہ انہوں نے خود نبی علیہ السلام سے یہ ارشاد سنا کہ \"جب تم تین آدمی ہو جاؤ تو اپنے میں سے ایک کو امیر مقرر کر لو اور اللہ پر توکل کر کے متوجہ ہو جاؤ۔\"(2)","",{"fn":"(1) اتحاف السادۃ (۶/۳۹۸) المغنی عن حمل الاسفار (۲/۳۵۱)\n(2) اتحاف (۶/۳۹۸) المغنی عن حمل الاسفار (۲/۳۵۱)"}],[6506,"§۷۸۷۸ ۔ مرثد بن عدی الطائی(1)\nان کا تذکرہ کرتے ہوئے بھی امام بغوی علی بن قرین کی روایت لکھتے ہیں، عبد الواحد بن زید بن اعین سے کہ ملت بن سعید ابن مقرن عبدی نے مرثد بن عدی طائی سے یہ سنا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کا یہ ارشاد مبارک خود سنا ہے کہ اہل مشرق میں سے سب سے بہتر بندہ ربیعہ ہے اور ان میں سے سب سے بہتر عبد قیس ہے۔(2)\nامام بغوی رحمہ اللہ یہ تجزیہ فرماتے ہیں کہ یہ احادیث غیر معروف اور بے بنیاد ہیں۔","",{"fn":"(1) اسد الغابہ (۴۸۲۲) تجرید (۲/۶۷)\n(2) معجم الکبیر (الحدیث: ۱۲/۱۲۹۷۰) صحیح ابن حبان (۷۲۹۴) مجمع الزوائد (۱۰/۴۹)"}],[6507,"§۷۸۷۹ ۔ مرثد بن عیاض\nان کا تذکرہ دیکھنے کے لیے عیاض بن مرثد کے حالات دیکھئے۔"],[6508,"§۷۸۸۰ ۔ مرثد بن ابی مرثد الغنوی(1)\nیہ خود بھی صحابی ہیں، ان کے والد بھی صحابی ہیں جن کا نام کناز بن حصین ہے۔ یہ دونوں شرکاء بدر میں سے ہیں اور ان کے والد کا تذکرہ گزر چکا ہے۔ اصحاب سنن نے عمرو بن شعیب عن ابیہ عن جدہ کے طریق سے روایات تخریج کی ہیں کہ مرثد بن ابی مرثد غنوی قیدیوں کو سوار کرتے تھے پھر قرآن مجید کی آیت: ﴿الزَّانِي لَا يَنْكِحُ إِلَّا زَانِيَةً....﴾(2)(3) کے نزول کا قصہ نقل کرتے ہوئے حدیث ذکر کی ہے۔ وفات: ابن اسحاق فرماتے ہیں: مرثد کی شہادت ماہ صفر ۳ھ میں غزوہ رجیع میں ہوئی۔\nان سے ایک اور روایت بھی جس کو احمد بن سنان قطان نے اپنی مسند میں اور امام بغوی و حاکم نے اپنی مستدرک میں اور امام طبرانی رحمہ اللہ نے اوسط میں قاسم بن ابی عبد الرحمن سامی کے طریق سے کہ مرثد بن ابی مرثد بدری صحابی ہیں، فرماتے ہیں کہ نبی علیہ السلام نے ارشاد فرمایا: اگر تم یہ چاہتے ہو کہ تمہاری نمازیں قبول ہو جایا کریں تو تم اپنے میں سے سب سے بہتر آدمی کو امام بنایا کرو۔ اور طبرانی رحمہ اللہ(4) کی روایت میں ہے کہ تم اپنے علماء کو امام بنایا کرو اس لیے کہ علماء تمہارے اور اللہ کے درمیان وفد کی حیثیت رکھتے ہیں۔ ابن عبد البر(5) فرماتے ہیں کہ قاسم کا یہ کلام کہ ابو مرثد نے خود مجھ سے یہ حدیث بیان کی ہے یہ ایک وہم اور غلط خیال ہے اس لیے کہ جو حضور علیہ السلام کی زندگی میں شہید ہو گئے تھے ان کی ملاقات قاسم سے کیسے ہوئی۔ لہذا یہ حدیث مرسل ہی ہو سکتی ہے۔ میں کہتا ہوں: یہ وہم اس شخص کو ہوا ہے جس نے یہ الفاظ لکھے ہیں: عن القاسم، حدثنی مرثد لیکن صحیح روایت یوں ہے: عن القاسم عن مرثد۔ جمہور علماء نے اس حدیث کی تخریج یونہی کی ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۴۸۲۴) استیعاب (۲۳۹۳) تجرید (۲/۶۸)\n(2) ابوداؤد کتاب النکاح باب فی قولہ تعالی: ﴿الزَّانِي لَا يَنْكِحُ إِلَّا زَانِيَةٌ﴾ الحدیث (۲۰۵۱) ترمذی کتاب تفسیر القرآن باب ومن سورۃ النور الحدیث (۳۱۷۷) نسائی کتاب النکاح باب تزویج زانیۃ (۳۲۲۸)\n(3) سورۃ النور آیۃ (۳)\n(4) المعجم الکبیر (۲۰/۷۷۷)\n(5) استیعاب (۳/۴۴۰)"}],[6509,"§۷۸۸۱ ۔ مرثد بن وداعہ(1)\nکنیت ابو قتیلہ، حمصی لقب ہے۔ امام بخاری رحمہ اللہ(2) فرماتے ہیں: نبی علیہ السلام کے صحبت یافتہ تھے۔ حریز نے جریر بن عثمان کے طریق سے تخریج کی ہے حمیر بن یزید رجبی سے کہ جریر بن عثمان سے میں نے علاوہ کہتے تھے کہ میں نے ابو قتیلہ صحابی رسول کو نماز پڑھتے ہوئے دیکھا کہ وہ دوران نماز کبھی کبھی پسو مار دیا کرتے تھے۔\nابو حاتم(3) نے امام بخاری پر رد کیا ہے کہ ان کو نبی علیہ السلام کی صحبت حاصل نہیں ہے۔ امام بخاری رحمہ اللہ کی دلیل واضح ہے۔\nابن حبان نے صحابہ میں بھی ان کا تذکرہ کیا ہے اور تابعین میں بھی ان کا ذکر فرمایا ہے۔ ملک شام(4) کی فضیلت کے بارے میں ایک حدیث ہے جس کو امام ابوداؤد اور بغوی نے خالد بن معدان کی روایت ذکر کی ہے، عبد اللہ بن حوالہ سے۔\nبہت سے لوگوں نے صحابہ کرام رضی اللہ عنہم میں ان کا تذکرہ کیا ہے۔ مطین اور طبرانی(5) نے کنتیوں میں ان کا ذکر فرمایا ہے اور خالد بن معدان کی ہی ان سے ایک اور حدیث نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۲۶) استیعاب (۲۳۹۴) تجرید (۲/۶۸)\n(2) التاریخ الکبیر (۷/۴۱۵)\n(3) الجرح والتعدیل (۸/۲۹۹)\n(4) ابوداؤد کتاب الجہاد باب فی سکنی الشام (۲۴۸۳) مسند احمد (۴/۱۱۰)\n(5) المعجم الکبیر (۸/۱۶۳)"}],[6510,"§۷۸۸۲ ۔ مَرْحَب(1)\nمرحب یا ابو مرحب۔ ابوداؤد رحمہ اللہ(2) نے شعبی کے طریق سے ان کی ایک حدیث تخریج فرمائی ہے۔ لیکن یقینی نہیں ہے کہ ان کی ہے یا کسی اور سے روایت ہے۔\nابن سکن فرماتے ہیں کہ ان کو ابو مرحب سوید بن قیس کہا جاتا ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۲۷) استیعاب (۲۵۶۹) تجرید (۲/۶۸)\n(2) ابوداؤد کتاب الجنائز باب لم یدخل القبر (۳۲۰۹، ۳۲۱۰) دلائل النبوۃ (۷/۲۵۵) جامع المسانید (۱۱/۲۱۶)"}],[6511,"§۷۸۸۳ ۔ مرداس بن عبد الرحمن\nان کے حالات مرداس سلمی کے تذکرہ میں آئیں گے۔"],[6512,"§۷۸۸۴ ۔ مرداس بن عبد سعد السعدی\nابن شاہین نے صحابہ کرام رضی اللہ عنہم میں ان کا تذکرہ کرتے ہوئے ایک روایت یحیی بن عبد اللہ بن عبد بن سعد کے طریق سے نقل کی ہے، فرماتے ہیں: بنی عبد بن سعد کا ایک آدمی مرداس نامی آیا۔ وہ مشرف باسلام ہو کر واپس جا رہا تھا کہ راستے میں حضور علیہ السلام کے گھڑ سواروں کی ایک جماعت نے اس کو دیکھا تو کافر سمجھ کر غلطی سے مار ڈالا۔ پھر نبی علیہ السلام کو سارا واقعہ بتایا گیا۔ اس کی سند میں کچھ گڑ بڑ ہے۔"],[6513,"§۷۸۸۵ ۔ مرداس بن عروہ العامری(1)\nابن سکن صحابہ کرام رضی اللہ عنہم میں ان کا تذکرہ کرتے ہوئے فرماتے ہیں کہ یہ کوفہ کے رہنے والے تھے۔ جبکہ امام بغوی اور ابن حبان نے ان کو ثقفی قرار دیا ہے اور فرمایا ہے کہ یہ بھی نبی علیہ السلام کے صحبت یافتہ تھے۔\nامام بخاری، ابن سکن اور بیہقی(2) نے ولید بن ابی ثور کے طریق سے تخریج کی ہے۔ زیاد بن علاقہ سے کہ مرداس بن عروہ فرماتے ہیں کہ قبیلے کا ایک آدمی ان کے بھائی کو پتھر مار کر فرار ہو گیا جس سے وہ شہید ہو گئے۔ تو ہم نے اس کا پیچھا کیا تو وہ سیدنا ابو بکر رضی اللہ عنہ کے پاس بیٹھا ہوا پکڑا گیا ہم اس کو نبی علیہ السلام کے پاس لے گئے تو آپ صلی اللہ علیہ وسلم(3) نے ہمیں قصاص دلوایا۔\nمحمد بن جابر نے زیاد کے طریق سے اور امام بغوی و ابونعیم مسدد کے طریق سے یہی روایت نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۲۸) استیعاب (۲۳۹۵) تجرید (۲/۶۸)\n(2) التاریخ الکبیر (۷/۴۳۵)\n(3) المعجم الکبیر (۲۰/۷۱۰) مجمع الزوائد (۶/۲۸۸) جامع المسانید (۱۱/۲۱۸)"}],[6514,"§۷۸۸۶ ۔ مرداس بن عُقْفان(1)\nمرداس بن عقفان ابن سعیم بن قریط بن جناب بن الحارث بن خزیمہ بن عدی بن جندب العنبری بن عمرو بن تمیم التمیمی العنبری۔ ابن سکن ان کا تذکرہ کرتے ہوئے ان کی حدیث کی تخریج فرماتے ہیں محمد بن موسیٰ ہاشمی سے اور محمد بن عیسی منفعہ سے۔ ابن عبد البر کی تحقیق کے مطابق(2) یہ مرداس بن عقفان تمیمی وہی مرداس بن مرداس ہی ہیں جو نبی علیہ السلام کے صحبت یافتہ تھے اور کہتے تھے کہ میں نبی علیہ السلام کی خدمت اقدس میں حاضر ہوا تو آپ صلی اللہ علیہ وسلم نے میرے لیے برکت کی دعا فرمائی۔ یہ بات ان کا اپنا بیٹا بکر روایت کرتا ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۳۴) استیعاب (۲۳۹۷) تجرید (۲/۶۸)\n(2) استیعاب (۳/۴۴۳)"}],[6515,"§۷۸۸۷ ۔ مرداس بن عمرو\nان کا تذکرہ ابن نہیک کے حالات کے تحت آئے گا۔"],[6516,"§۷۸۸۸ ۔ مرداس بن قُليس الدوسي(1)\nابو موسیٰ ذیل میں ان کا تذکرہ کرتے ہوئے ابن الخرائطی کے طریق سے کتاب الہواتف میں ایک حدیث ذکر کی ہے۔ عیسی ابن یزید کے طریق سے کہ خالد بن کیسان اس شخص کی بات نقل کرتے تھے کہ جو مرداس بن قیس دوسی سے یہ حدیث بیان کرتے ہیں کہ مرداس کہا کرتے تھے میں نے نبی علیہ السلام کی خدمت میں حاضر ہو کر نجومیوں کی غیبت کی باتیں بتانے کا تذکرہ(2) کیا اور جو کچھ تبدیلیاں اس سے واقع ہوتی ہیں ان کا بھی ذکر کیا اور یہ کہ ہمارے ہاں بھی کچھ لوگ یہ کام کرتے ہیں۔ پھر ایک لمبا قصہ سنایا، جس میں یہ بھی تذکرہ تھا کہ نجومی لوگ اکثر باتیں درست کرتے ہیں اور کبھی کبھی ان سے بھی غلط بات نکل جاتی ہے۔ تو آپ نے جواب ارشاد فرمایا کہ اے دوس کی جماعت! میرے دنیا میں آجانے کے بعد آسمان کے دروازے بند ہو گئے اور یہ کہانت اس کے بعد سے مرمٹ چکی ہے۔\nمصنف فرماتے ہیں: اس سند میں عبد اللہ بن محمد بلوی بھی ہیں لیکن عیسی کے بارے میں میرا خیال ہے کہ یہ وہی ابن داب ہیں جو کہ جھوٹے کذاب ہیں۔","",{"fn":"(1) اسد الغابہ (۴۸۳۰) تجرید (۲/۶۸)\n(2) اسد الغابہ (۴/۱۰۶)"}],[6517,"§۷۸۸۹ ۔ مرداس بن مالک الاسلمی\nان کا تذکرہ مرداس کی پٹی کے آخر میں آ رہا ہے۔"],[6518,"§۷۸۹۰ ۔ مرداس بن مالک الغنوی(1)\nابن شاہین ان کا تذکرہ کرتے ہوئے منذر بن محمد کے طریق سے روایت لاتے ہیں حسین بن محمد اپنے والد سے اور وہ حمزہ ابن عبد اللہ بن یزید غنوی جو کہ مرداس کے بیٹے ہیں، اپنے والد کے بارے میں کہتے ہیں کہ وہ نبی علیہ السلام کی خدمت میں قاصد بن کر گئے تو آپ علیہ السلام نے ان کے چہرے پر ہاتھ پھیر کر خیر و بھلائی کی دعا دی اور ان کو ایک خط بھی لکھ دیا کہ تم اپنی قوم کے زکوۃ، صدقات کے والی اور نگران ہو۔(2)","",{"fn":"(1) اسد الغابہ (۴۸۳۲) تجرید (۲/۶۸)\n(2) اسد الغابہ (۴/۱۰۶)"}],[6519,"§۷۸۹۱ ۔ مرداس بن ابی مرداس\nیہ وہی ابن عقفان ہیں جن کا تذکرہ گزر چکا ہے۔"],[6520,"§۷۸۹۲ ۔ مرداس بن مروان(1)\nمرداس بن مروان بن جذع بن یزید بن حارث بن حرام بن کعب بن غنم۔ یہ انصاری خزرجی ہیں۔ ابن کلبی رحمہ اللہ فرماتے ہیں کہ یہ اپنے والد سمیت مشرف باسلام ہو چکے تھے اور صلح حدیبیہ کے موقع پر انہوں نے بھی بیعت رضوان میں حصہ لیا تھا۔ امام عدوی نے بھی ان کا تذکرہ فرمایا اور ابو علی غسانی وغیرہ نے بالاستیعاب ان کے حالات لکھے ہیں۔","",{"fn":"(1) اسد الغابہ (۴۸۳۵) تجرید (۲/۶۹)"}],[6521,"§۷۸۹۳ ۔ مرداس بن مویلک(1)\nمرداس بن مویلک بن رباح بن ثعلبہ بن سعد بن عوف بن کعب بن ملان بن غنم بن غنی بن اعصر الغنوی۔ ابن کلبی ان کا تذکرہ فرماتے ہوئے لکھتے ہیں کہ یہ نبی علیہ السلام کے پاس قاصد بن کر گئے اور صحبت سے فیض یاب ہوئے اور آپ علیہ السلام کو ہدیہ میں ایک گھوڑا پیش کیا۔ میں کہتا ہوں: امام طبری نے ان کو اور مرداس بن مالک کو دو الگ الگ شخصیات قرار دیا ہے جبکہ ابن اثیر فرماتے ہیں کہ ایک ہی شخصیت دو ناموں سے مشہور ہیں لیکن راجح اور بہتر قول یہ ہے کہ یہ دونوں الگ الگ ہیں۔","",{"fn":"(1) اسد الغابہ (۴۸۳۲) تجرید (۲/۶۹)"}],[6522,"§۷۸۹۴ ۔ مرداس بن نہیک الضمری(1)\nبعض حضرات کا کہنا ہے کہ یہ عمرو کے بیٹے ہیں۔ بعض فرماتے ہیں یہ اسلمی ہیں یا غطفانی ہیں۔ پہلی بات سب سے بہتر ہے۔ ابن عبد البر وغیرہ نے ان کا تذکرہ فرمایا ہے۔ تفسیر سدی اور تفسیر ابن جریج میں ابو عمر(2) نے حضرت عکرمہ سے اور تفسیر سعید بن ابی عروبہ میں حضرت قتادہ روایت کی ہے اسی طرح بعض دوسرے حضرات بھی فرماتے ہیں کہ اس بات میں کسی کا کوئی اختلاف نہیں کہ وہ نہیک جنہوں نے سلام کیا تھا اور فرمایا تھا کہ میں مومن ہوں (اس کے باوجود ان کو قتل کیا گیا)۔ اس قصہ میں مقتول کا نام مرداس ہی تھا۔ ہاں البتہ اس بات میں بہت اختلاف ہے کہ قاتل کون تھا؟ اور اس لشکر اسلام و مجاہدین کا امیر کون تھا۔ میں کہتا ہوں: آگے چل کر نون کی پٹی میں یہ بات بھی آئے گی کہ سیر واقدی میں ان کا نام نہیک بن مرداس بتایا گیا ہے۔ اور حرف العین کے تحت گزر چکا ہے کہ یہ عامر بن اضبط ہیں۔ جن کا تذکرہ محکم بن جامہ کے حالات میں گزر چکا ہے۔ اور میں نے خطیب ابو بکر بغدادی کے خط میں محمد بن اسامہ کے حالات میں (جو کہ متفق سے ہیں) پڑھا ہے یونس بن بکیر اپنی سند سے اسامہ سے روایت کرتے ہیں جو کہ مغازی ابن اسحاق سے(3) ہے کہ اسامہ فرماتے ہیں کہ میں اور ایک آدمی انصاری آدمی سے ملے.....الخ۔ خطیب بغدادی فرماتے ہیں کہ دوسرا شخص جو اسامہ کے ساتھ تھا وہ نہیک بن سنان تھے، اس کے علاوہ اور بھی کچھ اختلافات ہیں علماء کے مابین۔ مغازی کی اس روایت کے علاوہ ایک دوسری روایت میں ہے ایک نو مسلم شیخ اپنی قوم کے لوگوں سے یہ بات نقل کرتے ہیں کہ نبی علیہ السلام نے غالب بن عبد اللہ کلبی لیث کو ایک جہادی لشکر میں بنو ضمرہ کے علاقہ میں بھیجا۔ تو وہاں بنی حرقہ کا ایک آدمی مرداس بن نہیک تھا جو کہ اس قبیلہ کا اتحادی تھا تو اسامہ رضی اللہ عنہ نے اس کو قتل کر دیا۔ اسامہ بن زید بن حارثہ کے پوتے اپنے دادا کی بات نقل کرتے ہیں کہ میں اور میرا ایک ساتھی ایک انصاری سے ملے تو جب ہم نے اس پر تیر و تلوار کو اٹھایا تو کہنے لگا: اَشْهَدُ اَنْ لَّا اِلٰهَ اِلَّا اللہُ۔ تو ہم نے اس کی پروا کیے بغیر اس کو قتل کر دیا۔ اور تفسیر کلبی میں ابو صالح سے سیدنا ابن عباس رضی اللہ عنہما کی روایت ہے، فرماتے ہیں مرداس اسلمی کے بارے میں یہ آیت نازل ہوئی: ﴿وَلَا تَقُولُوا لِمَنْ أَلْقَىٰ إِلَيْكُمُ السَّلَامَ لَسْتَ مُؤْمِنًا﴾(4) \"جو تمہاری طرف سلام میں پہل کرے اسے یوں نہ کہہ دو کہ تو مؤمن نہیں ہے۔\" مقاتل بن حیان بھی اپنی تفسیر میں ضحاک سے ابن عباس رضی اللہ عنہما کی روایت اسی طرح نقل فرماتے ہیں۔ ابو نعیم معتمر بن سلیمان کے طریق سے روایت کرتے ہیں کہ معتمر کے والد ابو سعید سے نقل کرتے ہیں کہ نبی علیہ السلام نے اسامہ ابن زید بن حارثہ کو بنو ضمرہ کے لوگوں کی طرف بھیجا تو وہ مرداس نامی ایک آدمی سے ملے جس کے پاس کچھ بکریاں تھیں۔ عبد بن حمید نے قتادہ کے طریق سے تخریج کی ہے کہ مذکورہ آیت بنی غطفان کے ایک آدمی مرداس کے بارے میں نازل ہوئی۔ واقعہ یہ ہوا نبی علیہ السلام نے ایک لشکر غالب لیثی کی سرکردگی میں بھیجا تو مرداس کے گھر والے اپنے گھوڑوں سمیت پہاڑ پر چڑھ گئے تو مرداس ان سے کہنے لگا کہ میں تو مسلمان ہوں میں تمہارے ساتھ نہیں آتا۔ لیکن مسلمانوں نے اس کو قتل کر دیا، اور جو کچھ اس کے پاس تھا وہ بھی لے لیا تو پھر یہ آیت نازل ہوئی۔ اگر چہ اس میں بھی اختلاف ہے کہ قاتل کون تھا جیسا کہ مقتول کی تعین بھی مختلف فیہ ہے، لیکن ممکن ہے کہ یہ ایک واقعہ نہ ہو بلکہ واقعات مختلف ہوں کئی سارے ہوں۔","",{"fn":"(1) اسد الغابہ (۴۸۳۶) استیعاب (۲۳۹۸) تجرید (۲/۶۹)\n(2) استیعاب (۳/۴۴۳)\n(3) سیرۃ النبویہ (۴/۲۰۴)\n(4) سورۃ النساء الآیۃ (۹۴)"}],[6523,"§۷۸۹۵ ۔ مرداس(1)\nمرداس یا ابن مرداس بیعت رضوان میں شریک تھے۔ ابو نعیم نے ان کا تذکرہ کرتے ہوئے شعبہ کے طریق سے سلیمان ابن عبد الرحمن سے روایت نقل کی ہے کہ راشد بن سیار فرماتے ہیں کہ میں پانچ ایسے افراد کی گواہی دے سکتا ہوں جو بیعت رضوان تحت الشجرہ میں شریک تھے۔ ان میں سے ایک مرداس یا ابن مرداس تھے۔(2) ان سب لوگوں نے مغرب سے پہلے ہی نماز پڑھ لی تھی۔ اس روایت کے راوی راشد تک سب کے سب با اعتماد اور ثقہ ہیں البتہ راشد کو ابن حبان نے ثقہ تابعین میں ذکر فرمایا ہے اور لکھا ہے کہ یہ عبد اللہ بن ابی اوفی کے آزاد کردہ غلام تھے۔ اسی طرح خطیب بغدادی نے بھی ان کے حالات موتلف میں لکھے ہیں، سیار کے تذکرہ میں اور فرمایا کہ راشد بن سیار یہ عبد اللہ بن ابی اوفی کے غلام تھے۔","",{"fn":"(1) اسد الغابہ (۴۸۳۳) تجرید (۲/۶۹)\n(2) اسد الغابہ (۴/۱۰۶)"}],[6524,"§۷۸۹۶ ۔ مرداس بن مالک الاسلمی(1)\nیہ بھی بیعت رضوان میں شریک تھے۔ ابن قانع نے ان کے والد کا نام عبد الرحمن لکھا ہے۔ امام مسلم اور اوزاعی فرماتے ہیں کہ صرف قیس بن ابی حازم نے ہی ان سے روایت نقل کی ہے جبکہ کچھ دوسرے لوگوں کا خیال یہ ہے کہ زیاد بن علاقہ نے بھی ان سے روایت لی ہے، حالانکہ یہ بات صحیح نہیں ہے۔ کیونکہ وہ شیخ زیاد بن علاقہ اور ہیں جن کا ذکر مرداس بن عروہ کے حالات میں گزرا ہے کیونکہ یہ حدیث تو مرداس اسلمی کی ہے۔(2) صحیح بخاری میں یذھب الصالحون الخ۔ ابن سکن فرماتے ہیں کہ بعض اہل علم کا خیال یہ ہے کہ مرداس بن عروہ ہی اسلمی ہیں جن کے والد کے اسم گرامی میں اختلاف ہے۔ لیکن صحیح بات یہ ہے کہ وہ اسلمی اور ہیں مرداس بن عروہ نہیں۔","",{"fn":"(1) اسد الغابہ (۴۸۳۱) استیعاب (۲۳۹۶) تجرید (۲/۶۸)\n(2) بخاری کتاب الرقاق باب ذہاب الصالحین (۶۴۳۴) مسند احمد (۴/۱۹۳) الاحاد والمثانی لابن ابی عاصم (۴/۲۳۶۸، ۲۳۶۹)"}],[6525,"§۷۸۹۷ ۔ مرداس الضمری\nابن نہیک کے حالات میں ان کا تذکرہ گزر چکا ہے۔"],[6526,"§۷۸۹۸ ۔ مرداس المعلم(1)\nابو زید دودی نے کتاب الاسرار میں بغیر سند کے ذکر کیا ہے کہ نبی علیہ السلام مرداس المعلم کے پاس سے گزرے تو فرمایا کہ پتلی اور باریک چپاتی کھانے سے بچو۔ کتاب اللہ پر شرط لگانے سے بچتے رہو۔ اور مجھے ابھی تک اس کی کوئی سند نہیں مل سکی۔","",{"fn":"(1) تجرید (۲/۶۹)"}],[6527,"§۷۸۹۹ ۔ مرزبان بن النعمان(1)\nمرزبان بن نعمان بن امرؤ القیس بن حجر بن عمرو بن معاویہ بن حارث الاکبر ابن الحارث الاکبر کندی۔ امام طبری اور ابن الکلمی فرماتے ہیں کہ یہ اشعث بن قیس کے ساتھ قاصد بن کر نبی علیہ السلام کی خدمت میں حاضر ہوئے تھے۔","",{"fn":"(1) اسد الغابہ (۴۸۳۷) استیعاب (۲۵۷۲) تجرید (۲/۶۹)"}],[6528,"§۷۹۰۰ ۔ مرزوق الثقفی(1)\nقبیلہ ثقف کا غلام تھا۔ امام واقدی نے ان غلاموں میں ان کا بھی تذکرہ کیا ہے جو نبی علیہ السلام کی خدمت میں حاضر ہو کر مسلمان ہو گئے تھے۔ یہ تقریباً دس غلام تھے جو طائف سے آئے تھے تو نبی علیہ السلام نے ان کو آزاد فرما دیا۔ تو یہ مرزوق عثمان کا غلام تھا۔","",{"fn":"(1) اسد الغابہ (۴۸۳۸) استیعاب (۲۵۷۰) تجرید (۲/۶۹)"}],[6529,"§۷۹۰۱ ۔ مرزوق الصیقل\nابن حبان اور عسکری فرماتے ہیں کہ ان کو نبی علیہ السلام کی صحبت کا شرف حاصل ہوا۔ ابن عبد البر فرماتے ہیں کہ ان کی مسند حدیث میں... امام بغوی و طبرانی(1) نے محمد بن حمیر کے طریق سے روایت کی ہے کہ ابو الحکم نے ہمیں بتایا کہ مرزوق صیقل نے خود مجھے بتایا کہ میں نے حضور علیہ السلام کی ذو الفقار نامی تلوار کو تیز کیا جس کے دستہ میں چاندی کی گرہ تھی اور اس کی رسی میں گول حلقے تھے اور اس کے درمیان میں چاندی کی چرخی تھی۔ میں کہتا ہوں: اس میں تو کوئی ایسی چیز نہیں ہے جس سے یہ معلوم ہو کہ ان کو نبی علیہ السلام کی صحبت حاصل ہے۔ اس لیے کہ یہ بھی تو ممکن ہے کہ یہ تلوار کسی شخص کے پاس ہو جس کو یقیناً نبی علیہ السلام کی صحبت حاصل ہو۔","",{"fn":"(1) المعجم الکبیر (۲۰/۸۴۴)"}],[6530,"§۷۹۰۲ ۔ مرضی ابن مقرن المزنی\nابن فنتون ان کا تذکرہ کرتے ہوئے طبری سے نقل کرتے ہیں کہ سراقہ بن عمرو نے اہل باب کے لئے ایک معاہدہ لکھا جس میں عبد الرحمن بن ربیعہ اور سلمان بن ربیعہ اور بکر بن عبد اللہ شریک تھے اور مرضی بن مقرن نے لکھا۔"],[6531,"§۷۹۰۳ ۔ مرہ بن الحباب(1)\nمرہ بن حباب بن عدی بن جد بن عجلان بلوی ہیں۔ آل عمرو ابن عوف کے اتحادی تھے۔ انصار میں سے تھے۔ امام طبری فرماتے ہیں غزوہ احد میں شریک ہوئے تھے جبکہ ابن الکلمی کا خیال ہے بدر میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۴۸۴۳) استیعاب (۲۳۸۵) تجرید (۲/۷۰)"}],[6532,"§۷۹۰۴ ۔ مرہ بن حبیب الفہری\nیہ عمرو بن حبیب کے بیٹے ہیں ان کا تذکرہ آگے چل کر آئے گا۔"],[6533,"§۷۹۰۵ ۔ مرہ بن سراقہ الانصاری(1)\nابو عمر ان کا تذکرہ کرتے ہوئے لکھتے ہیں کہ یہ غزوہ حنین میں شہید ہو گئے تھے۔\nابن اثیر رحمہ اللہ(2) فرماتے ہیں ابو عمر کی یہ بات صحیح نہیں کیونکہ غزوہ حنین میں شریک ہونے والے عروہ بن مرہ ہیں نہ کہ مرہ ابن سراقہ۔ میں کہتا ہوں: کہ اس میں کوئی تضاد نہیں ممکن ہے دونوں غزوہ حنین میں شریک ہوں۔","",{"fn":"(1) اسد الغابہ (۴۸۴۵) استیعاب (۲۳۸۶) تجرید (۲/۷۰)\n(2) اسد الغابہ (۴/۱۰۹)"}],[6534,"§۷۹۰۶ ۔ مرہ بن شراحیل\nان کے تذکرہ کے لیے دیکھیے شراحیل بن مرہ۔"],[6535,"§۷۹۰۷ ۔ مرہ بن عمرو(1)\nنسب: مرہ بن عمرو بن حبیب بن وائلہ بن عمرو بن شیبان بن محارب بن فہر۔ لقب: القرشی الجمحی۔\nامام بخاری رحمہ اللہ(2) الادب المفرد میں ان کی حدیث کی تخریج فرماتے ہیں اور امام بغوی ابن عیینہ کی روایت سے بیان فرماتے ہیں کہ صفوان بن سلیم انیسہ سے روایت کرتے ہیں کہ ام سعید فہریہ اپنے والد مرہ سے بیان کرتی ہیں کہ نبی علیہ السلام نے ارشاد فرمایا کہ میں اور یتیم کی پرورش کرنے والا جنت میں ان دو انگلیوں کی طرح ہوں گے (شہادت والی انگلی اور درمیان والی انگلی) چاہے وہ یتیم اس کا اپنا جگر گوشہ ہو یا کسی اور کا ہو۔(3) ابو یعلی(4) نے یزید بن زریع کے طریق سے تخریج فرمائی ہے محمد بن عمرو سے، صفوان سے، لیکن انیسہ کا ذکر کیے بغیر فرماتے ہیں: ام سعید بنت مرہ بن عمرو زہری نے نبی علیہ السلام سے روایت کیا ہے۔\nابو بکر بن ابی شیبہ اس حدیث کی سند یوں بیان فرماتے ہیں۔ محمد بن بشیر عن محمد بن عمرو عن ام سعید بنت مرہ بن عمرو زہری۔ یعنی اس سند میں عمرو کو مرہ سے پہلے ذکر کیا۔ مطین ہارون بن اسحاق سے تخریج کر کے سند یوں بیان کرتے ہیں۔ عن المحاربی عن محمد بن عمرو۔ اس میں مرہ کا بھی ذکر نہیں بلکہ ام سعید فرماتی ہیں میں نے خود نبی علیہ السلام سے سنا ہے۔ ابن مندہ اور باوردی نے مطین سے تخریج کی ہے۔ اور عورتوں کے ناموں میں عنقریب ایک اور اختلاف کا بھی تذکرہ ہوگا۔ محمد بن عمرو پر اور اس پر ابن السکن کا کلام بھی آئے گا اسیرہ کے تذکرے میں۔ اور ان کا مزید تذکرہ مرہ ہمدانی کے حالات میں آئے گا چوتھی قسم میں۔ ان شاء اللہ!\nابو عمر فرماتے ہیں: عورتوں کی کنیتوں میں سے ام سعید بھی ہے جو کہ عمرو کی بیٹی ہیں۔ اور بعض حضرات کا کہنا ہے صفوان بن سلیم نے عمیر الجمحی سے روایت بیان کی ہے، یتیم کی پرورش کے متعلق۔ اسی طرح اس حدیث کی سند میں صفوان کے بارے میں بھی اختلاف ہے۔\nمیں کہتا ہوں: یہ سب کچھ اختلاف باقی رہنے کے باوجود اس میں کوئی شک نہیں کہ ام سعید بنت مرہ فہریہ اور ہیں اور ام سعید بنت عمرو اور عمیر الجمحیہ یہ اور ہیں۔","",{"fn":"(1) اسد الغابہ (۴۸۴۸) استیعاب (۲۳۸۷) تجرید (۲/۷۰)\n(2) الادب المفرد (۱۳۲)\n(3) شرح السنۃ (۱/۱۲۳) مجمع الزوائد (۵/۲۷۱) جامع المسانید (۱۱/۲۲۱)\n(4) مسند ابی یعلی (۸/۴۸۶۶) (۱۲/۷۵۵۳)"}],[6536,"§۷۹۰۸ ۔ مرہ بن عمرو العقیلی(1)\nاسماعیلی نے ان کا تذکرہ کرتے ہوئے علی بن قرین کے طریق سے تخریج کی ہے کہ خشرم بن حسن عقیلی نے عقیل بن طریف عقیلی سے سنا ہے۔ مرہ بن عمرو عقیلی فرمایا کرتے تھے کہ میں نے نبی علیہ السلام کے پیچھے نماز پڑھی تو آپ نے سورہ فاتحہ کی تلاوت فرمائی۔(2)","",{"fn":"(1) اسد الغابہ (۴۸۴۹) تجرید (۲/۷۰)\n(2) اسد الغابہ (۴/۱۱۰)"}],[6537,"§۷۹۰۹ ۔ مرہ بن کعب البہری(1)\nکہا جاتا ہے کہ یہ وہی کعب بن مرہ ہیں جن کا تذکرہ حرف کاف کے تحت گزر چکا ہے۔\nایوب ابو قلابہ سے اور وہ ابو الاشعث سے روایت کرتے ہیں کہ ایک دفعہ کچھ خطیب لوگ ملک شام میں جمع ہو کر تقریریں کر رہے تھے ان میں کچھ صحابہ کرام رضی اللہ عنہم بھی تھے تو سب سے آخر میں جو بندہ کھڑا ہوا اس کا نام مرہ بن کعب تھا جس نے یوں تقریر شروع کی کہ اگر میں نے نبی علیہ السلام سے خود یہ حدیث نہ سنی ہوتی تو آج میں کھڑا نہ ہوتا کہ میں نے نبی علیہ السلام کو ارشاد فرماتے ہوئے سنا کہ فتنے بہت ہی قریب ہیں اور فتنوں کا ذکر فرمایا کہ اتنے میں ایک آدمی کپڑوں میں لپٹا ہوا گزرا تو آپ علیہ السلام نے ارشاد فرمایا کہ یہ شخص اس دن بھی ہدایت اور حق پر ہوگا۔ تو میں کھڑا ہوا اور اس شخص کے کندھوں سے پکڑ کر دیکھا تو وہ سیدنا عثمان غنی رضی اللہ عنہ تھے۔(2)\nیہ تو عبد الوہاب ثقفی کی روایت ہے ایوب سے سلیمان بن حرب حماد کے واسطہ سے ایوب سے نقل کرتے ہیں۔ ابو الربیع نے حماد بن زید کے طریق سے تخریج کرتے ہوئے سند یوں بیان فرمائی ہے: عن ایوب عن ابی قلابہ عن رجل۔ یعنی اس میں آخری راوی کا نام ذکر نہیں کیا۔ اور اسحاق بن ابی اسرائیل سند یوں فرماتے ہیں: عن حماد عن ایوب عن ابی قلابہ۔ فرماتے ہیں میرا خیال ہے کہ ابو قلابہ کے بجائے ابو الاشعث ہیں۔ ابو ہلال الراسبی نے اس کو یوں روایت کیا ہے: عن قتادہ عن عبد اللہ بن شقیق عن مرہ البہزی کہ نبی علیہ السلام نے ارشاد فرمایا کہ عنقریب گائے کے سینگ کی طرح فتنے ہوں گے(3) اتنے میں ایک آدمی کپڑوں میں لپٹا ہوا بندہ گزرا تو آپ صلی اللہ علیہ وسلم نے فرمایا یہ اور اس کے ساتھی حق پر ہوں گے۔ یہ شخص عثمان رضی اللہ عنہ تھے۔ اور کہمس نے اس کو یوں روایت فرمایا: عن عبد اللہ بن شقیق عن ہرم بن الحارث عن اسامہ بن خریم عن مرہ۔\nان تمام روایات کو امام بغوی رحمہ اللہ نے تخریج فرمایا ہے اور عبد الوہاب ثقفی کی روایت کو امام ترمذی رحمہ اللہ نقل کر کے فرماتے ہیں یہ حدیث حسن اور صحیح ہے۔ اور امام احمد بن حنبل رحمہ اللہ نے ابن علیہ سے اور ایوب سے اسی طرح کی روایت نقل فرمائی ہے۔ اور ابو ہلال اور کہمس کی روایت کو ذکر کرتے ہوئے ابو قلابہ میں کوئی اختلاف ذکر نہیں فرمایا کہ یہی مرہ بن کعب ہیں۔ اور اصل حدیث کو امام احمد بن حنبل نے بیان فرمایا جبیر بن نفیر کے طریق سے کہ ہم سیدنا عثمان رضی اللہ عنہ کی شہادت کے بعد سیدنا معاویہ کے ساتھ ایک جگہ جمع تھے کہ کعب بن مرہ کھڑے ہو کر یوں گویا ہوئے: ہم نبی علیہ السلام کے ساتھ بیٹھے ہوئے تھے کہ اچانک سیدنا عثمان رضی اللہ عنہ کپڑوں میں لپٹے ہوئے وہاں سے گزرے تو آپ علیہ السلام نے ارشاد فرمایا کہ اس آدمی کے پاؤں تلے سے فتنوں کا ظہور ہونے والا ہے۔ اس دن جو بھی شخص اس کی پیروی و اتباع کرے گا وہی ہدایت و حق پر ہوگا۔(4)\nاور کعب بن مرہ کے حالات میں ایک اور حدیث بھی گزری ہے۔ لیکن اس میں یہ شک ظاہر کیا گیا ہے کہ یہ کعب بن مرہ ہیں یا مرہ بن کعب ہیں۔ بعض حضرات کا کہنا ہے کہ یہ دو الگ الگ شخصیات ہیں جبکہ دوسرے بعض حضرات فرماتے ہیں کہ یہ ایک ہی شخصیت ہیں جن کے نام میں تقدیم و تاخیر ہو گئی ہے۔ حقیقت کا علم اللہ کو ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۵۰) استیعاب (۲۳۸۸) تجرید (۲/۷۰)\n(2) ترمذی کتاب المناقب باب فی مناقب عثمان رضی اللہ عنہ (الحدیث: ۳۷۰۴) معجم الکبیر (الحدیث: ۲۰/۳۱۵) مسند امام احمد (۵/۳۳)\n(3) معجم الکبیر (۲۰/۳۱۵) مسند احمد (۵/۳۳)\n(4) معجم الکبیر (۲۰/۳۱۷) تاریخ بغداد (۱۲/۵۸)"}],[6538,"§۷۹۱۰ ۔ مرہ بن مالک\nان کے بھائی عبد الرحمن بن مالک کے حالات میں ان کا تذکرہ ہو چکا ہے۔"],[6539,"§۷۹۱۱ ۔ مرہ بن ابی مرہ\nابن مندہ نے ان کا تذکرہ فرمایا ہے۔ ان کا تذکرہ ۷۹۱۲ میں ہے۔"],[6540,"§۷۹۱۲ ۔ مرہ بن وہب بن جابر(1)\nان کا سلسلہ نسب یوں ہے: مرہ بن وہب بن جابر بن عتاب بن مالک بن کعب بن عمرو بن سعد بن عوف بن ثقیف۔ لقب ثقفی تھا۔ اور یہ یعلی کے والد محترم ہیں۔ امام بغوی وغیرہ ان کا تذکرہ کرتے ہوئے عبید اللہ بن ابی زیاد کے طریق سے تخریج کرتے ہیں کہ ام یحییٰ بنت یعلی اپنے والد کے بارے میں فرماتی ہیں کہ میں فتح مکہ کے دن ان کو لے کر نبی علیہ السلام کی خدمت میں حاضر ہوئی اور عرض کیا کہ اے اللہ کے رسول! یہ میرے والد آپ کے ہاتھ پر بیعت ہجرت کرنا چاہتے ہیں۔ نبی علیہ السلام نے ارشاد فرمایا: فتح مکہ کے بعد کوئی ہجرت نہیں لیکن جہاد اور نیت ہے۔(2) انہی کی ایک اور حدیث ابن ماجہ میں موجود ہے لیکن اس کی سند میں اعمش کے بارے میں اختلاف ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۴۶) استیعاب (۲۳۸۹۹)\n(2) ابوداؤد کتاب الجہاد باب فی الہجرۃ ھل انقطعت (۲۴۸۰) ترمذی کتاب السیر باب ما جاء فی الہجرۃ (۱۵۹۰) مسند احمد (۱/۲۲۶) مستدرک حاکم (۲/۲۵۷) معجم الکبیر (۱۰/۴۱۲)"}],[6541,"§۷۹۱۳ ۔ مرہ بن ابی عزہ\nسلسلہ نسب یوں ہے: مرہ بن ابی عزہ بن عمرو بن عمیر بن وہب بن حذافہ بن نجح لقب جحی۔ ان کے والد جنگ احد کے بعد غزوہ حمراء الاسد میں شہید ہو گئے تھے۔ اور اس مرہ کا ایک بیٹا یا پوتا مدینہ میں رہتا تھا جس کا ذکر سیدنا زبیر رضی اللہ عنہ نے فرمایا ہے۔"],[6542,"§۷۹۱۴ ۔ مرہ\nان کی کوئی نسبت نہیں ہے، ان کا ذکر حرب کے حالات میں گزرا ہے اور آگے یعیش کے حالات میں مزید آئے گا۔ ان شاء اللہ تعالیٰ"],[6543,"§۷۹۱۵ ۔ مروان بن الجذع\nان کا نسب ان کے والد مرداس کے حالات میں گزر چکا ہے۔ ابن الکلبی فرماتے ہیں کہ یہ بڑھاپے میں مسلمان ہو گئے تھے اور ان کا بیٹا بھی مسلمان تھا اور یہ صلح حدیبیہ میں شریک تھے۔ اور یہ مروان نبی علیہ السلام کی طرف سے امین و نگران تھے خیبر کی تقسیم پر۔"],[6544,"§۷۹۱۶ ۔ مروان بن الحکم\nیہ حکم بن ابو العاص کے بیٹے ہیں۔ اموی ہیں۔ سیدنا عثمان رضی اللہ عنہ کے چچا زاد بھائی تھے۔ ان کا ذکر دوسری قسم میں آئے گا۔"],[6545,"§۷۹۱۷ ۔ مروان بن قیس الاسدی(1)\nبعض حضرات کا کہنا ہے یہ تمیمی ہیں۔ امام بخاری رحمہ اللہ(2) فرماتے ہیں کہ یہ بھی دربار رسالت کے صحبت یافتہ تھے، اور ان کا بیٹا ان سے روایت کرتا ہے جس کو امام بخاری اور بغوی اور طبرانی نے یحییٰ بن سعید اموی کے طریق سے تخریج کیا ہے کہ عمران بن یحییٰ اسدی فرماتے ہیں کہ میں نے اپنے چچا سے سنا کہ ایک آدمی نبی علیہ السلام کی خدمت میں حاضر ہو کر عرض کرنے لگا کہ میرے والد کا انتقال ہو گیا اور انہوں نے منت و نذر مانی ہوئی تھی کہ وہ پیدل حج کریں گے ایک بڑا جانور ذبح کریں گے لیکن اب وہ فوت ہو گئے ہیں اور انہوں نے کوئی مال وغیرہ بھی نہیں چھوڑا تو کیا میں ان کی طرف سے حج اور قربانی کی قضا کر سکتا ہوں تو نبی علیہ السلام نے فرمایا: جی ہاں، آپ حج کی قضا بھی کریں اور قربانی بھی کریں۔ پھر بطور مثال کے ارشاد فرمایا کہ اگر آپ کے والد پر کسی بندے کا قرض ہوتا اور آپ اس کو ادا کر دیتے تو وہ بندہ کتنا خوش ہوتا! اسی طرح اللہ تعالیٰ بھی راضی اور خوش ہو جائیں گے۔(3) امام بغوی رحمہ اللہ فرماتے ہیں اس سند کے علاوہ مجھے اور کوئی سند نہیں ملی۔","",{"fn":"(1) اسد الغابہ (۴۸۴۲) استیعاب (۲۴۰۰) تجرید (۲/۶۹)\n(2) تاریخ الکبیر (۷/۳۶۷)\n(3) معجم الکبیر (۲۰/۸۴۳) مجمع الزوائد (۴/۱۹۲) جامع المسانید (۱۱/۲۲۶، ۲۲۷)"}]])